INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193883550', 'Cilindro Roda Vw Crossfox 2005 a 2014 - 1356109 - CCR9213', 'Cilindro Roda Vw Crossfox 2005 a 2014 1356109 CCR9213 1.6 8V - TRASEIRO ESQ/DIR (11/16" OU 17,46mm)O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 36.51, 36.51, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd41-m7rnf2gcfyh961', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22193883550', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197063916', 'Filtro Combustível Toyota Hilux 2005 a 2012 - 179470 - JFC2072', 'Filtro Combustível Toyota Hilux 2005 a 2012 179470 JFC2072 (CD / CS) - Motor 2.5 16v Diesel/Turbo Diesel /(SW4 / SRV / CD) - Motor 3.0 16v Turbo Diesel - (Automático/Mecânico) - (Refil) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 41.83, 41.83, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rasq-ma98nbkd9ada1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22197063916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393748071', 'Cano Refrigeração PALIO 1996/2000 COM AR - 98141 - VC211', 'Cano Refrigeração PALIO 1996/2000 COM AR VALCLEI VC211 Motor 1.0/1.5 8v Álcool/Gasolina - (Com ACD/Ar Quente/Desembaçador) (Tubo do Fluxo D''Água do Motor) O Tubo de Refrigeração do motor é um item de suma importância para o sistema de arrefecimento, a sua vida útil está ligada diretamente aos cuidados com a manutenção e troca do fluído (água + anticorrosivo) dentro do período recomendado. Quando não utilizado da maneira correta este tubo libera uma camada corrosiva que circula pelo sistema de arrefecimento danificando todos os componentes ligados ao sistema de arrefecimento.', 42.54, 42.54, NULL, 'Automobiles > Automobile Spare Parts > Radiators, Engine Cooling & Climate Control', 'https://cf.shopee.com.br/file/sg-11134201-7rat4-majcdodv0nddf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22393748071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197747543', 'Suporte Articulado Para TV Zinnia Elysium PRO, 32 Pol. a 75 Pol., Preto, ZNO-ELYPRO-BL01', 'SUPORTE ARTICULADO PARA TV ZINNIA ELYSIUM PRO Trazendo conforto e praticidade no dia a dia, torna a rotina mais funcional com maior aproveitamento do tempo gasto em frente à TV. O suporte universal articulado Zinnia Elysium PRO é perfeito para tornar a rotina mais proveitosa evitando inconveniências devido ao ângulo do pescoço, uma vez que possui uma articulação que se adequa ao ângulo de visão de quem utiliza. DESIGN Ocupando pouco espaço, esse item foi pensado para ficar nos bastidores de forma clean criando um aspecto mais aberto. CONFORTO Criado para atuar na ergonomia, para que você possa passar horas em frente à televisão, este item torna uma experiência confortável. PRATICIDADE Com uma articulação horizontal em ±90° e inclinação de ±15°, torna simples e fácil de movimentar sua TV de acordo com suas necessidades. DIA A DIA Seja na sua sala, quarto ou recepção, este suporte entregará toda a dinâmica necessária para se ter um bom aproveitamento da sua televisão. Seu cotidiano ficará mais leve e fácil de aproveitar. Marca: Zinnia Modelo: ZNO-ELYPRO-BL01 Tamanho da placa Traseira: 300 x 225 mm Tamanho da placa Frontal: 650 x 200 mm Tamanho dos braços de Montagem: 430 x 32 mm VESA: 600 x 400 mm Suporte de TV: 32" – 75" Distância da Parede: 60 – 443 mm Peso Suportado: 65KG Inclinação: ± 15° Giratório: ± 90° Características: - Universal para todas as TVs. - Inclinação para baixo de 15° para a melhor visualização. - Giratório em 180° para a esquerda e direita. - Fácil de instalar. - Sistema de gerenciamento de cabos. - Capa de plástico para a placa de parede. - Estrutura super sólida. - Braços com inclinação extra grandes. Garantia de 12 meses. _______________________________ PICHAU INFORMÁTICA LOJA OFICIAL A Pichau Informática, com mais de 18 anos de experiência, é um dos principais nomes no mercado nacional de tecnologia. Comprometida com a qualidade, eficiência e satisfação do cliente, busca constantemente melhorias para oferecer serviços e produtos de excelência.', 470.58, 192.27, NULL, 'Home Appliances > TVs & Accessories > TV Brackets', 'https://cf.shopee.com.br/file/sg-11134201-7rd4f-lwmz7o0hs6o807', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F627750190%2F21197747543', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
