INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697336591', 'Ração Golden Special Gatos Adultos Castrados Frango e Carne 3kg', 'Ração Golden Special Gatos Adultos Castrados Frango e Carne 3kg - Indicado para gatos; - Para gatos adultos castrados; - Auxilia no controle do ganho de peso; - Ajuda na redução do odor das fezes; - Auxilia na saúde do trato urinário; - Rico em nutrientes. A Ração Golden Special Gatos Adultos Castrados Frango e Carne é um alimento rico, completo e balanceado que desempenha um papel essencial no controle do peso do seu felino, graças à sua composição com teores reduzidos de calorias e gorduras. Golden Special Gatos Castrados contribui para a prevenção dos principais tipos de cálculos urinários, por contar com a tecnologia de SSR, que promove um trato urinário saudável para o animal. Contém um teor proteínas especiais cuidadosamente selecionados que minimizam o odor das fezes. Um alimento altamente palatável e não contendo adição de corantes e aromatizantes artificiais. Ingredientes Farinha de vísceras de frango, farinha de carne e ossos de bovino, glúten de milho*, proteína concentrada de soja*, grão de milho*, quirera de arroz, farelo de arroz desengordurado, polpa desidratada de beterraba, gordura de frango, biomassa de microalgas (Schizochytrium sp.), cloreto de potássio, cloreto de sódio, levedura de cana-de-açúcar autolisada e desidratada, ácido cítrico, bentonita, BHA (Butilhidroxianisol), BHT (Butilhidroxitolueno), cloreto de amônio, DL-metionina, extrato de yucca (0,05%), hexametafosfato de sódio, hidrolisado de fígado de suíno, sulfato de amônio, taurina, vitamina A, vitamina B1, vitamina B2, vitamina B3, vitamina B5, vitamina B6, vitamina B7, vitamina B9, vitamina B12, vitamina C, cloreto de colina, vitamina D3, vitamina E, vitamina K3, iodeto de cálcio, selenometionina hidroxi análoga, sulfato de cobre pentahidratado, sulfato de ferro, sulfato de manganês, sulfato de zinco monohidratado.', 72.9, 69.9, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/br-11134207-820le-mr0jk1xouhhi69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F23697336591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
