INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498021064', 'Película para Garmin Forerunner 265S - Hydrogel HD - Gshield', 'DESCRIÇÃO A Película de Hydrogel da Gshield oferece proteção avançada para a tela do seu smartwatch, garantindo uma experiência duradoura e sem preocupações. Com tecnologia inovadora de hidro nano PET e TPU Soft Gel, essa película protege contra riscos indesejados. O revestimento oleofóbico não só aprimora a resistência a arranhões, mas também minimiza marcas de digitais, proporcionando uma visualização sempre clara e nítida. A película se ajusta perfeitamente às extremidades curvas do seu dispositivo, assegurando uma cobertura total sem comprometer a estética e a funcionalidade. Optar pela Película de Hydrogel Gshield é escolher um escudo sofisticado que combina tecnologia de ponta e durabilidade, mantendo a tela do seu relógio sempre impecável. Cuide do seu smartwatch com estilo e confiança, escolhendo a excelência em proteção que só a Gshield oferece. ESPECIFICAÇÕESMaterial: Hidro nano pet + TPU Soft Gel Marca: GshieldEspessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High DefinitionCertificações: US MilitaryDimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais.', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7rbn4-m5je1hraxv1w2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F19498021064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
