INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792802095', 'Capa Case Capinha para Samsung Galaxy Tab S9 - Phantom - Gshield', 'Proteja seu Tablet / iPad com a Capa Phantom da Gshield! Fabricada por um Polímero de alta resistência e com encaixe perfeito no tablet, que possibilita a proteção das bordas e traseira do dispositivo com toque macio, suave e antiderrapante; possui uma elevação em todas as extremidades que evita que a tela entre em contato direto com as superfícies. A capa Phantom possui na sua traseira uma alça kick stand e uma alça em velcro com rotação 360º, que possibilita utilizá-la em diferentes posições, proporcionando o uso confortável em diversas situações: base para ler, digitar, ver vídeos ou fazer vídeo chamadas. ESPECIFICAÇÕES Material: Polimero de alta densidade - Não Amarela. Marca: Gshield Dimensões: Dimensões exatas do aparelho Cor: Preta Certificações: Us Military COMPATIBILIDADE Samsung Galaxy Tab S9 ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 208.97, 208.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rblm-lqnhw4lb7kk7b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23792802095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794431532', 'Gshield Saco à Vácuo Organizador Safe Bag à Prova d’Água Reutilizável para Viagem 35 x 43cm com Vedação Hermética, Preto', 'SAFE BAG GSHIELD – SACO DE COMPRESSÃO A VÁCUO GRANDE 35 X 43 CM! Organize melhor sua mala e aproveite muito mais espaço durante as viagens com o Safe Bag Gshield. Desenvolvido para armazenar e comprimir roupas e outros itens, ele reduz o volume da bagagem e ainda ajuda a proteger o conteúdo contra água, umidade, poeira e sujeira. PRINCIPAIS CARACTERÍSTICAS • Sistema de compressão a vácuo que reduz o volume das roupas • Ajuda a otimizar o espaço dentro de malas e mochilas • Zíper hermético para uma vedação mais segura • Proteção contra água, umidade, poeira e sujeira • Material leve, resistente e flexível • Produto compacto, reutilizável e fácil de transportar • Ideal para viagens, academia, praia, camping e organização doméstica • Pode ser utilizado em malas de bordo, mochilas e bagagens despachadas ESPECIFICAÇÕES - Marca: Gshield - Modelo: Safe Bag - Material: Oxford/Poliéster com revestimento em TPU - Dimensões: 35 x 43 cm - Cor: Preto - Certificação: IP67 - Resistência à água: submersão de até 1 metro por até 30 minutos, quando corretamente vedado - Fechamento: Zíper hermético - Sistema: Compressão a vácuo - Quantidade: 1 unidade OBSERVAÇÃO Para garantir a resistência à água e o funcionamento adequado da compressão, certifique-se de que o zíper esteja completamente fechado e corretamente vedado antes do uso. LEVE MAIS, OCUPE MENOS ESPAÇO! Garanta agora o seu Safe Bag Gshield e viaje com a bagagem mais organizada, compacta e protegida.', 159.99, 159.99, NULL, 'Travel & Luggage > Travel Accessories > Travel Organizers', 'https://cf.shopee.com.br/file/sg-11134201-824hs-mf19wyz4z2mm9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22794431532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17580017451', 'Baseus Detector De Segurança Portátil Com Lente Escondida Anti-Peeping', 'Descrição: Ei~ Bem-vindo à Loja Oficial Baseus Flagship!!! Por favor, leia a descrição do produto claramente, escolha a necessidade. A maioria dos itens tem estoques prontos! Aproveite~ ❥Pacote: 1* Detector de Lente Escondida Pinhole 1* Cabo USB Para Tipo-C 0,3m ❥Parâmetros: Nome da marca: BASEUS Nome: Detector de Câmera Baseus Heyo No do modelo: BS-HA016 Parâmetros de potência nominal:USB Tipo-C/DC5V 0,1A Capacidade da bateria: 60mAH Ajuste: 2 engrenagens Tamanho do produto: 43mm*12mm*43mm Material: ABS + PC Peso do produto: 15g', 105.8, 60.9, NULL, 'Home & Living > Safety & Security > Others', 'https://cf.shopee.com.br/file/cn-11134207-7qukw-lhd8ix1u1b6ncf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F279868721%2F17580017451', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12219611086', 'Delux M618GX Mouse Óptico Ergonômico Vertical Sem Fio 6 Botões 1600DPI Para PC / Windows Mac / Escritório', 'Descrição do produto em inglês após português Mouse Vertical Sem Fio Delux M618GX 6 Botões 800/1200/1600DPI Fio Óptico com Concha Protetora de Borracha para PC Laptop Descrição do Produto: A Deluxe M618GX mouse é um tipo de mouse vertical sem fio, adotando design ergonômico humano. O novo método de segurar com palma pode o descanso do usuário livre e reduzir o cansaço do braço, proporcionando sensação confortável. Mouse de escritório sem fio 2.4G, tornando seu trabalho mais eficiente.O mouse com casca protetora de borracha irá reduzir o cansaço por muito tempo de usar. Características: Mouse vertical humano de engenharia, pulso-cura, proporcionando um método de trabalho sanitário; Mouse sem fio 2.4G, 10 metros de distância eficiente; Revestimento de borracha em descanso palma e parte principal para potencializar a experiência do usuário Descanso de palma de borracha removível, anti-derrapante Especificações: Mouse Sem Fio Dpi:800/1200/1600 6 Botões: Clique Esquerdo / Clique direito/ roda de rolagem/Botão Avante/DPI Bateria: 2*Pilhas AAA (Não Inclusas) Tamanho: 135,5 mm (C) × 10,0 mm (L) ×87,0 mm (A) Interface: USB Compatível Para Windows XP /7/8/10 Caixa Contém: 1× Mouse M618GX 1× Manual do Usuário ************************************************** Delux M618GX Wireless Vertical Mouse 6 Buttons 800/1200/1600DPI Optical Office Mice with Rubber Protective Shell for PC Laptop Product Description: Deluxe M618GX Mouse is a type of wireless vertical mouse, adopting human ergonomic design. The new griping holding method with palm rest can free user’s wrist and reduce the tiredness of arm, providing comfortable feeling. 2.4G wireless office mouse, making your work more efficient.The mouse with rubber protective shell will reduce the tiredness for long time using. Features: Human engineering vertical mouse, wrist-healing, providing a health working method; 2.4G wireless mouse, 10 meters efficient distance; Rubber coating on palm rest and main part to enhance user experience Removable rubber palm rest, anti-skid Specifications: Wireless Mouse DPI:800/1200/1600 6 Buttons: Left Click/ Right Click/ scroll wheel/ Forward/Backward/DPI Button Battery: 2*AAA batteries (Not Included) Size: 135.5 mm (L) × 100.0 mm (W) ×87.0 mm (H) Interface: USB Compatible For Windows XP /7/8/10 Box Contains: 1× M618GX Mouse 1× User Manual', 181.67, 89.99, NULL, 'Computers & Accessories > Keyboards & Mice > Mice', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m292d573jrlqb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F280443173%2F12219611086', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593394388', 'Capa Case Capinha Antichoque Discovery p/ Motorola Moto Edge 40 Neo Proteção, Anti-impacto - Gshield', 'A Capa Discovery para Motorola Moto Edge 40 Neo da Gshield é a escolha definitiva para quem busca uma proteção completa e um estilo inigualável para seu dispositivo. Desenvolvida com materiais de alta qualidade, como polímeros de absorção de impacto e borracha termoplástica resistente, a capa oferece uma defesa confiável contra quedas, arranhões e impactos do dia a dia. Sua construção robusta é complementada por um design cuidadosamente elaborado, que combina elegância e funcionalidade. As bordas elevadas proporcionam uma proteção adicional à tela e à câmera, enquanto os recortes precisos garantem acesso fácil a todos os botões, portas e câmeras do seu dispositivo. Além disso, a capa Discovery apresenta um padrão texturizado exclusivo, proporcionando uma aderência segura e confortável em suas mãos, evitando escorregão acidentais. Seu acabamento fosco suave ao toque não apenas oferece uma sensação premium, mas também ajuda a evitar impressões digitais e manchas. Seja para aventuras ao ar livre ou para o uso diário, a capa Discovery da Gshield oferece uma proteção superior sem comprometer o estilo. Escolha a capa que vai além da simples proteção e eleve o visual do seu Motorola Moto G84 com a capa Discovery da Gshield. ESPECIFICAÇÕES - Marca: Gshield - Material: Polipropileno de alta densidade - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military COMPATIBILIDADE - Motorola Moto G84', 87.97, 87.97, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rdwj-m0s001jnd2ry8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F23593394388', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22833753583', 'Luz Traseira Inteligente De Freio Com Sensor ROCKBROS Sem Fio De Controle Remoto Sinalização De Volta À Noite', 'Marca: ROCKBROS Nome do produto:Luz traseira inteligente Material: ABS + PC Tamanho: 8 * 3,5 * 2 cm Peso: Luz traseira 42 g, controle remoto 18 g Capacidade da bateria: Luz traseira 500 mAh, controle remoto 240 mAh Precauções: Por favor, carregue antes de usar. Características do Características: 1.Lembrete de direção, aviso para veículos traseiros. 2.O controle do botão sem fio é mais conveniente (cerca de 1,5 metros de distância). 3.Luz de freio sensível ao freio sensível, ciclismo mais seguro. 4.Clique na tecla de função para alternar o modo e clique duas vezes para alternar o modo inteligente/manual.', 229.62, 145.1, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7qvcw-leo7u6nn1b0bde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F236693054%2F22833753583', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994454274', 'Kit: Glutamina 1Kg + Glutamina 500g - 100% Pura Importada - Soldiers Nutritio', 'Kit: Glutamina 1Kg + Glutamina 500g - 100% Pura Importada - Soldiers Nutrition ESTE KIT CONTÉM OS SEGUINTES ITENS: - Glutamina 1Kg - Glutamina 500g Glutamina - 100% Pura Importada - Soldiers Nutrition Acompanha Colher Dosadora 5g BENEFÍCIOS DA GLUTAMINA: - Controla o processo de anabolismo e catabolismo; - Removo os excessos de amônia e nitrogênio do corpo; - Regula a síntese e degradação de proteínas; - Regulação do sistema imune. A glutamina participa de forma relevante na síntese de outros aminoácidos e ajuda a manter a homeostase dos tecidos durante o processo de catabolismo. Outras funções importantes inerentes à glutamina é o fato dela conseguir liberar quantidades extras de hormônios na corrente sanguínea, como por exemplo, a testosterona. SOMOS FABRICANTES, PRODUTO DIRETO DA FÁBRICA PARA VOCÊ COM TOTAL GARANTIA DE QUALIDADE ANVISA: Registro ISENTO conforme resolução RDC 27 de 06 de agosto de 2010 anexo I. Registro ISENTO conforme resolução RDC 240/2018.', 349.9, 169.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfiona0u83y84e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F347988064%2F23994454274', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17271708822', 'Película Hydrogel Fosca Gshield Motorola Moto G10 Proteção Antirrisco', 'Aumente a resistência com a película para Motorola Moto G10 A Película de Hydrogel Fosca para Motorola Moto G10, da Gshield, garante proteção extra para a tela do seu dispositivo. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d ) Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Grau de transparência: 97% High Definition Certificações: US Military Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. COMPATIBILIDADE Motorola Moto G10 ITENS INCLUSOS 1x películas de hydrogel Kit de instalação GARANTIA 3 meses contra defeitos de fabricação', 54.97, 54.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/d0ced821afca5ab24fe54c8f341bcaa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F17271708822', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
