INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498402052', 'Pneu 195/40R17 81W XL Ovation VI-388 Aro 17 Perfil Baixo Esportivo Alta Performance', 'O Pneu 195/40R17 81W XL VI-388 Ovation foi desenvolvido para quem busca visual esportivo, alta performance e segurança na condução. Seu perfil baixo entrega respostas rápidas ao volante, maior estabilidade em curvas e excelente aderência em altas velocidades. A construção reforçada XL suporta cargas maiores e oferece mais segurança mesmo em uso esportivo. Ideal para projetos personalizados e veículos que exigem precisão, sem abrir mão da confiabilidade no uso diário. Produto novo, pronto para instalação, com rodagem firme e controle absoluto. RESUMO DA FICHA TÉCNICA Medida: 195/40R17 Índice de carga: 81 (até 462 kg por pneu) Índice de velocidade: W (até 270 km/h) Modelo: VI-388 Marca: Ovation Construção: Radial Aplicação: Passeio / Esportivo Aro: 17 Tecnologia: XL (Extra Load) CARROS COMPATÍVEIS : (Sempre confirme a medida no manual do veículo ou no pneu original.) Volkswagen Golf (preparado/rebaixado) Volkswagen Polo (projetos esportivos) Volkswagen Saveiro Chevrolet Corsa Chevrolet Celta Chevrolet Onix (customizado) Fiat Palio Fiat Punto Fiat Uno (preparado) Ford Fiesta Honda Fit (projetos personalizados)', 779.73, 479.1, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7reoz-m8go4f2rt8k7a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648136452%2F22498402052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27380071814', 'Chuteira Futebol de Quadra Futsal Adulto Techno ll Original Umbro', 'Chuteira Futsal Techno II Umbro Modelo: U01FB00333 Foi desenvolvida para jovens jogadores que buscam estilo, tecnologia e desempenho nas quadras. Com um design moderno e ousado, seu cabedal em material laminado com textura plana apresenta um efeito visual dinâmico, combinando acabamentos foscos e brilhantes com arte gráfica em serigrafia e cores contrastantes. O icônico Diamante Umbro em destaque na lateral reforça o visual esportivo e sofisticado. A palmilha interna em EVA forrada em tecido garante conforto e amortecimento, enquanto o solado de borracha monocolor antiderrapante, equipado com tecnologia HYPERGRIP, oferece máxima tração e estabilidade para movimentos ágeis e precisos no futsal. Seja para treinos ou partidas, a Chuteira Umbro Techno II proporciona leveza, aderência e um ajuste perfeito, elevando sua performance nas quadras. Características: - Design moderno e ousado: Efeito pixel com acabamentos fosco e brilhante; - Cabedal em material laminado: Textura plana com arte gráfica em serigrafia e cores contrastantes; - Diamante Umbro em destaque: Visual esportivo e sofisticado; - Palmilha em EVA forrada em tecido: Maior conforto e amortecimento durante o jogo; - Solado de borracha monocolor: Antiderrapante para melhor aderência e estabilidade; - Tecnologia HYPERGRIP: Tração aprimorada para movimentos rápidos e precisos; - Leve e resistente: Ideal para treinos e partidas de futsal. Composição: - Cabedal: 100% Sintético. - Forro: 100% Poliéster. - Palmilha: 90% EVA e 10% Poliéster. - Sola 100% Borracha. A Chuteira Futsal Techno II Umbro pode ser encontrada aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 249.99, 179.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi0985nmxwci80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F27380071814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
