INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192959984', 'Melhores Decisões, Menos Arrependimentos | Andy Stanley', 'Boas perguntas levam a melhores decisões.Descubra cinco perguntas revolucionárias para fazer sempre antes de tomar uma decisão ― perguntas que ajudarão em suas finanças, relacionamentos, carreira e muito mais. Suas decisões determinam a direção e a qualidade da sua vida, e também criam a sua história. Embora ninguém planeje complicar a própria vida ao tomar decisões ruins, muitas pessoas não sabem como fazer boas escolhas. Em Melhores decisões, menos arrependimentos, Andy Stanley ajudará você a aprender a parar de tomar decisões ruins. O autor ensina a fazer cinco perguntas transformadoras, sejam grandes ou pequenas. Melhores decisões, menos arrependimentos ajudará você a trilhar o caminho para o sucesso em todas as fases da vida. 14x21cm 192 Páginas', 44.9, 38.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd5k-lu3rzngxruem75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23192959984', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
