INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17732730608', '1001 Perguntas e Respostas da Bíblia | | Venâncio Josiel dos Santos', 'Não se trata de mais um livro, mas sim, de um novo lançamento de cunho mais didático. A partir de agora, as organizações de treinamento de nossas igrejas, como: Escola Bíblica Dominical, Mocidade, Adolescentes, Organizações Missionárias, Grupos de Crescimento, etc. , terão em mãos uma obra elaborada com esmero, por um dos maiores "Experts" do assunto; Dr. Venâncio Josiel dos Santos. Escritor renomado; advogado; professor, Doutor em Teologia; além da vasta experiência como professor de Escolas Bíblicas. 14x21cm 118 Páginas', 33.9, 33.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/82d45ac17ce70f62d51fe2eeaf2ff4d1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F17732730608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8714445044', 'Cristianismo Puro e Simples | Capa Dura | C. S. Lewis', 'Em um dos períodos mais sombrios da humanidade, a Segunda Guerra Mundial, C.S. Lewis foi convidado pela BBC a fazer uma série de palestras pelo rádio com o intuito de explicar a fé cristã de forma simples e clara. Mais tarde, ajustado pelo próprio Lewis, esse material daria origem a Cristianismo puro e simples, um grande clássico da literatura. Na obra mais popular e acessível de seu legado, Lewis apresenta os principais elementos da cosmovisão cristã, gradativamente conduzindo o leitor a temas mais profundos e complexos, provocando reflexão e debate. Nesta edição especial e com tradução de uma das maiores especialistas em Lewis do Brasil, você vai encontrar as palavras que encorajaram e fortaleceram milhares de ouvintes em tempos de guerra e ainda reverberam mais de 70 anos depois288 páginas21x14cm', 44.9, 42.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/bc17a05c89e8fd0a4b0bc10c8cfc7eeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F8714445044', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
