INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19038542844', 'Kit Alfaparf SDL Smooth - Sh 250ml + Cond 200ml + Óleo 100ml', 'A linha Semi di Lino Smooth indicada para o tratamento de controle dos cabelos indisciplinados e difíceis de cuidar. O Kit Alfaparf Semi Di Lino Smooth Smoothing proporciona alinhamento dos fios com efeitos incríveis e imediatos. Além disso, controla o frizz causado pela umidade e pelos agentes atmosféricos. Descubra o tratamento Semi di Lino Smooth para valorizar a textura dos cabelos rebeldes! * RESULTADO: Nutrição * SUGESTÕES DE USO: Shampoo 1. Aplique o shampoo no cabelo molhado; 2. Massageie suavemente; 3. Enxague; 4. Repita a operação se necessário. Condicionador 1. Aplique o condicionador no cabelo molhado; 2. Massageie suavemente; 3. Finalize enxaguando. Óleo Capilar 1. Aplicar no cabelo úmido ou seco; 2. Despeje algumas gotas na mão e espalhe sobre o cabelo; 3. Finalize como desejado. * OBSERVAÇÕES: Imagem Meramente Ilustrativa. * ITENS INCLUSOS: 1 Alfaparf Semi Di Lino Smooth Smoothing Low Shampoo250 ml 1 Alfaparf Semi Di Lino Smooth Smoothing Low Condicionador200 ml 1 Alfaparf Semi Di Lino Smooth Smoothing Óleo Capilar 100 ml', 424.9, 424.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/a4204392f2cbef3194da675786f5fdf5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F19038542844', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20028595248', 'Wella Pro Invigo Brilliance Cond 1000ml', '* DESCRIÇÃO TÉCNICA: INVIGO COLOR BRILLIANCE Condicionador promove um tratamento intenso para melhorar a superfície do fio e aumentar o brilho da cor. Contém uma poderosa combinação de novos ingredientes para manter a vibração da cor e proteger o cabelo colorido. As moléculas de encapsulamento de cobre mantêm a vibração da cor do cabelo. A Histidina e a Vitamina E ajudam a controlar o processo de oxidação após o procedimento de coloração e ajudam a proteger a cor (Anti-Oxidant Shield Technology). O Caviar de Lima é conhecido por conter várias vitaminas e anti-oxidantes. Garante 7 (sete) semanas de proteção da cor do cabelo se o uso do produto for regular. * MODO DE USO: Aplique no comprimento do cabelo molhado. Distribua o produto igualmente e então enxague bem. * RESULTADO: Cabelos tratados com Ph otimizado. Garante 7 semanas de proteção e aumento do brilho da cor do cabelo quando o uso é regular.', 322.9, 222.9, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/141e926fa504ec51b21df290b275afdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20028595248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
