INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259441259', 'Ração Úmida Whiskas Sachê Frango ao Molho para Gatos Adultos', 'Whiskas Sachê Frango ao Molho é uma ração úmida deliciosa e nutritiva, feita com ingredientes naturais de alta qualidade, vitaminas e minerais. Cozidos a vapor, os pedacinhos de frango são irresistíveis para seu gato! * Refeição completa e balanceada para gatos adultos. * Ajuda a manter a saúde do trato urinário. * Sem conservantes, corantes ou aromatizantes artificiais. Guia alimentar: sirva 3 sachês por dia para gatos adultos de 4kg. Cada sachê de Whiskas equivale a 1/4 de xícara de Whiskas seco (1 xícara = 200ml).', 3.79, 3.79, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mo5ms28b9lhc0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259441259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892840843', 'Arame Para Solda Mig Uso Sem Gás 0.8mm - Kit 2 Rolos De 1 Kg E71t-gs Start', 'Distribuído por Ismafer Ferramentas Arame de Solda 1kg 0.8mm Uso sem Gás 2 unidades Descrição do Produto: O Arame de Solda 0.8mm da Start é ideal para soldagem sem gás, oferecendo praticidade e eficiência em diversos projetos de soldagem. Fabricado com material de alta qualidade, este arame proporciona uma soldagem consistente e durável, sendo adequado para profissionais e amadores que buscam um excelente acabamento em suas soldagens. Ficha Técnica: - Peso: 1kg - Diâmetro: 0.8mm - Marca: Start - Uso: Sem Gás Vantagens: - Praticidade: Dispensa o uso de gás, facilitando o processo de soldagem. - Alta Qualidade: Material resistente, garantindo soldagens duradouras. - Versatilidade: Adequado para diversas aplicações de soldagem. - Consistência: Proporciona soldagens uniformes e de alta qualidade. Usos Recomendados: - Reparos domésticos e industriais. - Projetos de soldagem automotiva. - Manutenção e fabricação de estruturas metálicas. - Soldagem em locais onde o uso de gás não é viável. EAN: 7908822401209 SKU: KIT24033x2 Distribuído por Ismafer Ferramentas', 87.67, 86.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-81zuv-mmj2pvr6cbno91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F986003177%2F23892840843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
