INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298314502', 'Alarme De Moto Com Presença Moto 3i Liga No Controle Stetsom Universal', '*** ALARME UNIVERSAL *** ----- ALARME MOTO TRIPLO I STETSOM ----- O completo Alarme para Motos Evolution Triplo I com Bloqueio é uma excelente opção para garantir mais segurança para sua moto. Acompanha 2 controles, sendo um convencional e um de presença, que ao se afastar da moto, o alarme é automaticamente acionado. Este produto tem várias funções como ignição pelo controle, opção de ligar e desligar silencioso, sensor por aceleração, função manobrista, localização e várias outras. Este modelo se diferencia do modelo Duplo I por permitir ignição pelo controle e permitir imersão total na água sem danificar o alarme. IMPORTANTE!!: O Controle Funciona de 10 a 20 Metros de Distância e corta a corrente após 1 minutos (se após 1 minuto a moto não detectar nenhum dos sensores o alarme é ativado automaticamente) Mais informações: . Acionamento da Ignição por controle remoto . Norma IP67 (resistente a imersão total do produto em água) . Antifurto/Bloqueador (integrado) . Bloqueio de ignição . Saída para pisca . Sirene dedicada . Função Manobrista . Controle de Presença Especificações Técnicas: . 2 anos de garantia com o fabricante . Bateria longa duração . Compatível Bloqueio por presença . Controle ante clonagem . Controle convencional . Controle de presença . Desabilita alarme pela chave master . Disparo de advertência pelo controle . Função localizar . Função Manobrista . Habilita alarme pela chave master . Ignição pelo controle . IP67 (Permite imersão na água sem danos ao alarme) . Memória para controles . Opção de liga e desliga silencioso . Pisca setas alternadas (economia de bateria do veículo) . Relatório de disparo . Resistente a interferências eletromagnéticas . Sensor por acelerômetro . Sirene Dedicada de alto volume sonoro . Antifurto Integrado Conteúdo da Embalagem: . 01 Sirene Dedicada . 01 Central . 01 Controle Convencional . 01 Controle com Função Presença . Chicote . Manual e Certificado de Garantia', 335.23, 335.23, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mesl9e1pg6wxcf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1634328463%2F21298314502', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
