INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11240227408', 'Chá Leão Camomila 25g em sachês - 25 Unidades', 'A família de Ervas que todo mundo conhece com a qualidade de Leão, marca líder do segmento de chás, sinônimo de tradição e qualidade com mais de 120 anos de experiência. #FicadeBoa com Chás Leão ESPECIFICAÇÕES: - Sabor: Camomila. - Aplicação: Chás de Infusão - Embalagem: Uma (1) Caixa de Chá Leão Camomila contém 25 sachês NÃO embalados individualmente. - Fabricante: Leão Alimentos e Bebidas LTDA. INFORMAÇÕES NUTRICIONAIS: - Ingredientes: CAPÍTULOS FLORAIS DE CAMOMILA. - Porção: 1g para 1 Sachê. - Os chás não possuem quantidade significativa de valor energético, carbohidratos, proteínas, gorduras totais, gorduras saturadas, gorduras trans, fibra alimentar e sódio. ALÉRGICO: - NÃO CONTÉM: Glúten MODO DE PREPARO: - Despeje água quente (a 90C) em uma xicara de 240ml. - Coloque o sachê e deixe em infusão por cinco (5) minutos. - Se preferir, adoce. INFORMAÇÕES IMPORTANTES: - Conservar ao abrigo do Sol e Calor em local limpo, seco, arejado e sem odor. - Produto sujeito a variação de suas características, devido à presença de ingredientes naturais. - Utilize água filtrada. - Usar a quantidade indicada de água é importante para garantir uma melhor experiência. - As imagens dos produtos e/ou seus componentes são meramente ilustrativos, exceto quando indicado o contrário no próprio anúncio.', 22.1, 22.1, NULL, 'Food & Beverages > Beverages > Tea & Tea Bags', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1fq5bwik0zsb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F520921300%2F11240227408', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47912843830', 'Furadeira Perfurador e Rompedor 1000W Profissional 5kg para Concreto e Demolição', '🔨Furadeira Perfurador Rompedor 1000W – Potência e Desempenho Profissional Leve mais eficiência para suas obras e reformas com a furadeira Perfurador Rompedor 1000W. Desenvolvido para quem busca potência, resistência e praticidade, ele é ideal para perfurar concreto, alvenaria, tijolos e realizar pequenos trabalhos de demolição com rapidez e precisão. ⚡ Principais Diferenciais ✅ Motor de alta potência de 1000W ✅ Sistema SDS Plus para troca rápida e segura das brocas ✅ 3 Funções em 1: • Perfuração • Perfuração com impacto • Rompimento/Demolição ✅ Excelente desempenho em concreto e alvenaria ✅ Empunhadura ergonômica para maior conforto durante o uso ✅ Estrutura reforçada e alta durabilidade ✅ Ideal para uso profissional e residencial 🛠 Aplicações • Instalações elétricas e hidráulicas • Obras e reformas • Perfuração de concreto e alvenaria • Remoção de revestimentos • Pequenos serviços de demolição 📦 Conteúdo da Embalagem • 1 furadeira Perfurador Rompedor 1000W • 1 Maleta resistente para transporte • 3 Brocas SDS Plus • 2 Escovas de carvão reserva 🚚 Envio Rápido e Produto Novo Produto novo, com envio rápido e suporte antes e após a compra para garantir a melhor experiência. 💪 Potência, praticidade e resistência em uma única ferramenta. Garanta já a furadeira Profissional 1000W!', 485.63, 266.0, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820lh-mpwqgezv1pts82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F356560587%2F47912843830', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
