INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53359698791', 'Boneco Funko Pop! Excl Dungeons & Dragons Dragão Az c Chase', 'O Boneco Funko Pop! Exclusivo Dragão Azul com Chase traz uma das criaturas mais icônicas do universo de D&D em uma versão cheia de poder e mistério. Representando o Blue Dragon Wyrmling, este colecionável em vinil destaca o visual imponente do jovem dragão azul, com a possibilidade de encontrar a rara versão Chase perolizada, tornando a experiência ainda mais especial para colecionadores. Com aproximadamente 8 centímetros de altura, é um item exclusivo e altamente desejado, perfeito para fãs de Dungeons & Dragons e Funko Pop! que buscam uma peça diferenciada, com alto valor colecionável e presença marcante na coleção.', 199.99, 199.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-820o9-mnn30m4qyr5y6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1289869635%2F53359698791', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50112422457', 'Conjunto Feminino Infantil Magia De Urso', 'Descrição: Conjunto Feminino Infantil Magia De Urso Casaco branca com estampa frontal e capuz interativo. Calça preta super confortável. Tudo pensado e produzido com muito amor e carinho. Selecionamos os melhores materiais para crianças que desejam ser destaque por onde passam! Guia de Tamanhos Como medir a criança? Utilizando uma fita métrica, envolva as regiões a serem medidas. Busto: Enrole a fita métrica em torno do corpo, na linha do peito. Comprimento: Comece pelo topo do ombro e meça até chegar no comprimento desejado. Quando for calça, short ou saia, comece medindo na linha da cintura. Cintura: Enrole a fita métrica em torno da cintura, sem apertar. As medidas da tabela abaixo são referentes á parte frontal da peça, então busto e cintura você deve multiplicar por 2. A tabela pode sofrer alterações de 1 á 2 cm para mais ou menos, leve isso em conta na hora de selecionar o tamanho adequado. Características: - Estação: Inverno - Gênero: Feminino - Tecido Peça: Moletom - Composição: 50% Algodão e 50% Poliéster - Faixa Etária: 1 à 12 anos - Garantia: 1 Mês - Idade recomendada: 1 - 12 anos - Tipo de Roupa: Conjunto - Tabela de Medidas: Tabela de Medidas Casaco: Tamanho | Busto | Comprimento 2 | 32CM | 37CM 3 | 34CM | 41CM 4 | 36CM | 43CM 6 | 39CM | 46CM 8 | 41CM | 47CM 10 | 42CM | 50CM 12 | 45CM | 53CM Tabela de Medidas Calça: Tamanho | Cintura | Comprimento 2 | 20CM | 51CM 3 | 22CM | 55CM 4 | 23CM | 62CM 6 | 24CM | 72CM 8 | 26CM | 77CM 10 | 27CM | 83CM 12 | 28CM | 88CM', 69.9, 50.33, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-824gh-mpm6zgh7z3lu0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F717393801%2F50112422457', NULL,