INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42118723576', 'Boneca Infantil Cry Babies Dreamy Day Care Multikids - BR2461', 'Mais realismo e fofura na hora de brincar com a Boneca Dreamy da Multikids! A Boneca Dreamy vai encantar as crianças com sua expressão fofa e funções interativas que imitam um bebê de verdade. Ela chora lágrimas de verdade e emite sons realistas que tornam a brincadeira de faz de conta ainda mais divertida. Basta retirar a chupeta de sua boca para que ela chore cada vez mais, e só para quando recebe a chupeta de volta. Uma experiência lúdica que estimula o cuidado, a imaginação e a criatividade das crianças. - Chora lágrimas de verdade: emoção e realismo na hora da brincadeira. - Sons de bebê: emite sons iguais aos de um bebê de verdade. - Interatividade com a chupeta: tire a chupeta e ela chora, devolva e ela se acalma. - Funciona com pilhas: utiliza 2 pilhas AAA (inclusas). - Brincadeira divertida e educativa: estimula o cuidado e a imaginação das crianças. Especificações: - Largura do produto: 13.5cm - Altura do produto: 31cm - Peso do produto: 595g - Faixa etária: +3 Anos - Comprimento do produto: 16.5cm - Composição do Material: ABS - Desenvolvimento: CognitivoMotor Características: - Marca: Multikids - Modelo: BR2461 Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 01x Boneca Dreamy - 01x Roupa - 01x Fralda de plástico - 01x Mamadeira - 01x Par de sapatos', 298.67, 261.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mekemby9sm4nc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F42118723576', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54752829043', 'Lapiseira Plus 2.0 Pote com 24 Unidades Leo&Leo Leonora - 4774', 'A Lapiseira Plus 2.0 da Leoeleo é uma opção prática e versátil para suas atividades de escrita. Este pote contém 24 unidades da lapiseira, prontas para uso. A Lapiseira Plus 2.0 apresenta um design clássico e funcional, com corpo robusto e resistente. Sua ponta de 2.0mm permite traços mais grossos, ideais para preenchimento e desenhos mais marcantes. Com a Lapiseira Plus 2.0, você terá uma escrita suave e consistente, sem interrupções. Seu mecanismo de avanço de grafite é eficiente e confiável, garantindo uma experiência de escrita agradável. Além disso, a Lapiseira Plus 2.0 possui uma empunhadura confortável e ergonômica, proporcionando conforto durante o uso prolongado. Eleve seu desempenho na escrita com a Lapiseira Plus 2.0 da Leoeleo. Tenha à disposição uma lapiseira de qualidade e durabilidade para suas tarefas cotidianas. Características: - Marca:Leonora - Modelo:4774 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - Lapiseira Plus 2.0 Pote c/24 Und Leo&Leo', 48.43, 41.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-822xb-mi20p9xdf9q9e7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F54752829043', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
