INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43431529402', 'Smilinguido - Bíblia do Bebê', '📖 Descrição Esta Bíblia foi desenvolvida para introduzir os pequenos ao universo bíblico de forma lúdica e acessível. Com ilustrações coloridas da Turma do Smilinguido, personagens queridos no meio cristão infantil, a obra apresenta histórias bíblicas selecionadas em linguagem adaptada para bebês e crianças em fase inicial de leitura. O objetivo é despertar desde cedo o interesse pela Palavra de Deus, fortalecendo valores cristãos como amor, amizade, bondade e fé. A capa dura garante resistência e durabilidade, ideal para o manuseio por crianças. 📑 Ficha técnica Título: Smilinguido – Bíblia do Bebê Autor: Ciranda Cultural (edição e adaptação) Editora: Ciranda Cultural ISBN: 9786526127131 Idioma: Português Formato: Capa dura ilustrada Número de páginas: 48 Dimensões: 13 cm x 17 cm Peso: 390 g Categoria: Religião e Espiritualidade, Bíblia Infantil, Literatura Cristã 🔑 Palavras-chave smilinguido, bíblia do bebê, ciranda cultural, bíblia infantil, histórias bíblicas para crianças, capa dura ilustrada, evangelização infantil', 21.86, 21.86, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-820m9-mp7xvj6l4937e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F380531074%2F43431529402', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
