INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997636890', 'Kit Relação Transmissão C/ Retentor Factor 150 2016 a 2024 Corrente Coroa e Pinhão.', 'Descrição Descrição: Kit Relação Transmissão Com Retentor Aplicação: Factor 150 - 2016 Até 2024 Referencia: 55555 Marca: Hardt Coroa: 39Z Dentes Pinhão 14 Dentes Corrente: 428H x 124HO Com Retentor Características do Produto: Descrição do Kit: Os Kits de transmissão da Hardt são compostos de coroa, pinhão e corrente. Cada peça possui embalagem individual e lubrificação protetora para garantir a qualidade final do produto. Descrição da Coroa: Coroa em Aço SAE 1045 certificado de acordo com normas internacionais. Tratamento térmico por indução, que garante maior durabilidade ao conjunto. Acabamento superficial com zincagem de alta resistência à corrosão. Dentes com camada endurecida por têmpera para garantir menor desgaste. Descrição do Pinhão: Pinhão em aço SAE 1045 de alta ductilidade, desenvolvido para melhor performance. Tratamento térmico integral para durabilidade superior. Descrição da Corrente: O Kit de transmissão com O''ring Hardt é composto de pinhão, coroa e a famosa corrente com retentor O''ring, um anel que protege os componentes da corrente, evitando a entrada de resíduos e água na lubrificação dos pinos e buchas, aumentando a vida útil do produto. Menos ruído e redução do número de paradas para regulagem da corrente. Desde já Agradecemos a preferencia . Shopping da MotoBike', 219.9, 149.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lsq9qgcx8j65a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F531303273%2F18997636890', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
