INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997078845', 'Coxim Motor Gm Corsa 1994 a 2002 - 810391 - ACX02054', 'Coxim Motor Gm Corsa 1994 a 2002 810391 ACX02054 (Dianteiro) (Lado Esquerdo) São divididos em 3 grupos: coxins do motor, coxins do câmbio e coxins do amortecedor. A função do coxim de motor/câmbio é ser o ponto de apoio do motor no chassi, fazendo a absorção da vibração do motor e evitando que seja transmitido para o veículo. O uso de coxins danificados diminuirá significativamente a vida útil do motor/câmbio do veículo.', 57.44, 57.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbm9-ln9324n6qbzgfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22997078845', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
