INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893557527', 'Jogo 2 Pneus Pirelli Aro 15 P400 Evo 195/55R15 85H', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a marca Pirelli A Pirelli nasceu na Itália há mais de 100 anos, em Milão. Com longa tradição na construção de pneus, a marca produz soluções para carros, motos, tratores, caminhões e ônibus e possui fábricas espalhadas pelo mundo. A Pirelli é a atual fornecedora de pneus da Fórmula 1, a principal categoria do automobilismo mundial, e possui longa tradição em pneus de alto desempenho.', 1103.76, 1015.46, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rfhe-m32aab7np42143', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F22893557527', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
