INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592659840', 'Saco para Lavar Roupa Premium Grande Branco/Azul Log Ordene', 'O Saco para Lavar Roupa Premium Grande Branco/Azul Log Ordene é ideal para cuidar das suas roupas delicadas. O produto conta com proteção extra e reforçada para preservar as fibras de tecido das peças. Sua estrutura evita a formação de pelos e bolinhas junto à peça e serve para diferentes tipos de máquinas de lavar roupas. Medidas: 49,5 x 60 cm (A x L x C)', 35.9, 31.9, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rfgw-m9691tfcdqrk86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22592659840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18361908076', 'Bico Injetor Ford Ka Hatch 1.0 8v 2008 A 2013 Ete', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação FORD KA 1.0 8V/1.0 8V ST FLEX 3P 2008 até 2013 KA 1.0 TECNO 8V FLEX 3P 2008 até 2011 Conteúdo Da Embalagem 1 Bico Injetor Cor do Produto No Observação 1.0 8V MPI Rocam Flex Tipo de Veículo para Carros Marca A ETE Acessórios pertence ao Grupo Rainha das Sete ,que atua no segmento de reposição automotiva, sendo um dos grupos que mais cresce no país, e que mantém parcerias com as multinacionais TE Connectivity e Delphi Automotive Systems, no Brasil. Iniciou suas atividades em 1989, com a Rainha das Sete, primeira empresa do grupo, fabricando soquetes, rabichos e porta-fusíveis. O Produto Os bicos injetores são componentes de extrema precisão, responsáveis por pulverizar finamente o combustível na câmara de combustão do motor. Quanto melhor for a pulverização, maior será o rendimento do motor. Em consequência, se obtém mais economia de combustível com menor emissão de gases poluentes. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 6 meses • Valor Unitário • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7895479063402 Código do Fabricante ETESTKM119 Combustível FLEX Combustível Flex', 60.04, 60.04, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rbli-lltdcxwgsmrvb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F18361908076', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697631406', 'Jogo Velas Ignição ASTRA 1995/2006 - 7133 - GV5R01', 'Jogo Velas Ignição ASTRA 1995/2006 MOTOR 1.8/2.0 8V SOHC MPFI (GASOLINA - ROSCA LONGA) (Vela Resistiva) Conduzir a alta voltagem elétrica para a parte interna da câmara de combustão e transformar essa voltagem em faísca, gerando e inflamando a mistura ar/combustível. Apesar de pequenina e simples, trata-se de um item extremamente importante para o carro. O desempenho da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes.', 73.08, 73.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-822yz-mofkpnkvnxfl87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22697631406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
