INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398245295', 'Cabo De Vela ASTRA 1.8 8v 1998 Ate 2004 - 85337 - GM76', 'Cabo De Vela ASTRA 1.8 8v 1998 Ate 2004 1.8/2.0 8vConduz a alta tensão produzida pela bobina (ou transformador) até as velas de ignição, sem permitir fugas de corrente, garantindo uma ignição sem falhas. Reduz de interferências eletromagnéticas, que podem prejudicar o funcionamento dos componentes eletrônicos do veículo, unidades de comando eletrônico e etc. Cabos resistivos - com o resistor instalado dentro dos terminais. Cabos supressivos - com o supressor instalado dentro do próprio cabo e sua resistividade depende do seu comprimento.', 56.86, 56.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-822z2-mofld8qwu5mze5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22398245295', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094358625', 'Puzzle 1000 Peças Garagem Vintage - Castorland Importado 1045742', 'Os quebra-cabeças Castorland® são fabricados na Polônia pela Castor®, uma empresa reconhecida no mercado há mais de 30 anos. São muito populares e apreciados por sua excelente qualidade em mais de 50 países em todo o mundo. A Castor® sempre se destacou pela rigorosa seleção e processamento gráfico de seu estoque de imagens, bem como pela extraordinária riqueza de detalhes que quase salta aos olhos em cada peça. Você achará a coleção de quebra-cabeças Castorland inspiradora. Pensando de diversificação, a Grow traz para o Brasil uma coleção de Puzzles da marca CASTORLAND para os apaixonados por cada quebra-cabeças. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. Puzzle Importado Fabricante: Castorland® Condição: NOVO/ LACRADO Quantidade de peças: 1000 peças Dimensões do puzzle montado: 68,0 × 47,0 cm Dimensões da embalagem: 35,0 × 25,0 × 5,0 cm', 199.99, 199.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-mdkh34h7120a17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F22094358625', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23394852528', 'BOMBA MANUAL PCP 3 ESTÁGIOS QGK BM3', 'BOMBA MANUAL PCP 3 ESTÁGIOS QGK BM3 Bomba manual de alta pressão desenvolvida para enchimento de cilindros PCP, oferecendo praticidade, autonomia e eficiência no uso. Seu sistema de 3 estágios proporciona bombeamento mais leve e eficiente, reduzindo o esforço e garantindo melhor desempenho. Construída em aço carbono resistente, conta com base estável, manopla ergonômica emborrachada e manômetro integrado para controle preciso da pressão. Possui também filtro anti-umidade, que ajuda a proteger o equipamento contra corrosão, além de mangueira com conexão padrão compatível com a maioria dos modelos PCP. FICHA TÉCNICA Marca: QGK Modelo: BM3 Tipo: Bomba manual PCP Estágios: 3 Pressão máxima: Até 300 BAR Material: Aço carbono Manômetro: Integrado Filtro anti-umidade: Sim Conexão: 1/8" BSP Base: Pés fixos para maior estabilidade Aplicação: Enchimento de cilindros PCP ITENS INCLUSOS 01 Bomba manual PCP 3 estágios – QGK 01 Mangueira com engate rápido 01 Kit de manutenção básico 01 Manual de instruções', 699.9, 469.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-825zs-ml26rjaswf0m39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1246438712%2F23394852528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097557253', 'Cilindro Mestre Embreagem Gm Astra 1998 a 2011 - 1333838 - AH254739', 'Cilindro Mestre Embreagem Gm Astra 1998 a 2011 1333838 AH254739 1.8 8V/ 2.0 8/16V O Cilindro Mestre de Embreagem é um dispositivo de controle que converte a força mecânica ( controlada a partir dos pés do condutor) em uma pressão hidráulica. Essa pressão é usada para atuar no servo da embreagem , que é montado na caixa de engrenagem e conectado na alavanca da embreagem. A fim fornecer a informação do curso da embreagem (exemplo para atuação rachada), Os cilindros mestre de embreagem são equipados geralmente com um interruptor do curso.', 172.78, 172.78, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rd4i-lvmvnenzc4y42a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22097557253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19961905608', 'Jogo Vela De Ignição Parati 1.6 1.8 97 A 2004 Original Ngk', 'Aplicação VOLKSWAGEN PARATI 1.6 MI PLUS TOTAL FLEX 8V 4P 2005 até 2009 PARATI 1.6 MI/ 1.6 MI CITY 2000 até 2004 PARATI 1.6MI/1.6MI CITY/T.FIELD T.FLEX 2004 até 2013 PARATI 1.8 MI CITY TOTAL FLEX 8V 4P 2005 PARATI 1.8 MI CROSSOVER TOTAL FLEX 8V 4P 2005 PARATI 1.8 MI PLUS TOTAL FLEX 8V 4P 2005 até 2009 PARATI 1.8 MI T. FIELD TOTAL FLEX 8V 4P 2005 até 2008 PARATI 1.8 MI/ 1.8 MI PLUS 2004 até 2005 PARATI C 1.6/ CL 1.6 MI 2P E 4P 1997 até 1999 PARATI CL 1.8 MI 2P E 4P 1997 até 1999 PARATI COMFORTLINE 1.6 MI TOT.FLEX 8V 4P 2006 até 2007 PARATI COMFORTLINE 1.8 MI TOT.FLEX 8V 4P 2006 até 2007 PARATI GL 1.8 MI/ CLUB 1.8 MI 2P E 4P 1997, 1999 PARATI SURF 1.6 MI TOTAL FLEX 2008 até 2013 PARATI SURF 1.8 MI TOTAL FLEX 2008 até 2009 PARATI TITAN 1.6 MI TOTAL FLEX 8V 4P 2009 até 2012 Conteúdo Da Embalagem 4 Velas de Ignição Cor do Produto No Tipo de Veículo para Carros Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. Além disso, a NGK é uma companhia certificada pela ISO/TS 16.949 e obedece as diversas regras de referências internacionais de qualidade. Os mais de 1300 funcionários da NGK do Brasil passam por um absoluto programa de treinamento e integração à filosofia de trabalho, no qual são estimulados a contribuir com propostas de melhoria contínua em benefício da organização e da sociedade. O Produto A Finalidade fundamental da vela de ignição é mandar a corrente elétrica que o transformador faz até a câmara de combustão, até modificar em uma faísca elétrica de alta tensão, o que dará início a combustão, ou seja, é responsável pela certa queima da mistura ar combustível. Importante • Recomendamos que os produtos sejam aplicados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor referente ao jogo • Imagem meramente ilustrativa EAN 7897707511068 Código do Fabricante BUR7ETB10 Combustível ÁLCOOL Combustível Álcool', 103.07, 103.07, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbmr-lltbs7epqiw36d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F19961905608', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293591479', 'Chinelo Aramis Sand Masculino', 'FOOT ONE TAMANHOS DISPONÍVEIS 33/34 - Selecione 34 35/36 - Selecione 36 37/38 - Selecione 38 39/40 - Selecione 40 41/42 - Selecione 42 43/44 - Selecione 44 45/46 - Selecione 46 Lembre-se de que, geralmente, os chinelos tendem a ficar mais justos no início, e é recomendado escolher uma numeração um pouco maior do que a sua numeração habitual. Isso ajuda a garantir mais conforto e evitar problemas de tamanho. Caso tenha dúvidas sobre a numeração ideal, nossa equipe está à disposição para ajudar! DESCRIÇÃO DO PRODUTO: O Chinelo Aramis Sand Masculino é um modelo elegante e confortável, ideal para o dia a dia. Fabricado com materiais de alta qualidade, como borracha ou couro, oferece resistência e conforto. Sua sola antiderrapante proporciona segurança ao caminhar, enquanto a palmilha macia garante bem-estar. Com design moderno e versátil, é perfeito para ocasiões casuais e descontraídas. CARACTERÍSTICAS: - Design Sofisticado: O modelo possui um design moderno e elegante, com linhas limpas e detalhes sutis que adicionam um toque de sofisticação. Perfeito para homens que buscam estilo sem abrir mão do conforto. - Materiais de Alta Qualidade: Confeccionado com materiais de primeira linha, como borracha ou couro, o chinelo oferece resistência e durabilidade, além de proporcionar um visual refinado e um toque suave ao contato com a pele. - Sola Antiderrapante: A sola foi projetada para garantir maior segurança e aderência ao caminhar, especialmente em superfícies molhadas, reduzindo o risco de escorregões e proporcionando estabilidade. - Conforto Ergonomicamente Planejado: A palmilha macia e a estrutura ergonômica do chinelo garantem um ajuste confortável e adequado ao formato dos pés, proporcionando uma sensação de bem-estar durante o uso prolongado. - Versatilidade: O design neutro e elegante permite que o chinelo seja usado em diversas ocasiões casuais, como passeios ao ar livre, encontros informais, ou em momentos de lazer, oferecendo estilo em diferentes situações. - Durabilidade e Resistência: Com materiais de alta resistência, o chinelo tem uma longa vida útil, mantendo sua aparência e funcionalidade mesmo após o uso contínuo. - Ajuste Confortável: A estrutura do chinelo foi projetada para se ajustar ao formato do pé, proporcionando uma sensação de conforto durante o uso, sem apertos ou desconfortos. - Estilo Discreto: Com detalhes sutis e cores discretas, o modelo pode ser facilmente combinado com diferentes tipos de roupas, seja para um look mais casual ou para um visual mais descomplicado e elegante. - Marca: Aramis - Modelo: Sand - Gênero: Masculino ITENS INCLUSOS: 01 - Par de Chinelo', 107.99, 107.99, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/sg-11134201-7rbk3-m5k560mg1wffd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F396321395%2F23293591479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993629751', 'Carabina de Pressão New Jade Oxidada 5.5mm - CBC + Luneta 4x20', 'Carabina de Pressão New Jade Oxidada 5.5mm - CBC A Carabina de Pressão New Jade é a mais silenciosa, precisa e veloz em sua categoria. Modelo fácil de engatilhar com corpo todo produzido em polímero, deixando a arma muito mais leve. Sua coronha é ambidestra com detalhes que proporcionam uma melhor "pegada". Para evitar a oxidação rápida de seu cano, ela possui uma capa/camada protetora ao longo de todo cano. Para acoplar luneta e red dot, essa carabina possui ranhura de 11mm. Possui sistema de cano basculante, tiro à tiro, com carregamento direto no cano. A alça de mira possui regulagem na vertical. E a massa de mira é fixa, protegida por túnel. Ambas são em fibra óptica. Especificações Fabricante: CBC Modelo: Jade New Calibre: 5.5mm(.22) Acabamento: Oxidado Coronha: Polipropileno – Preta Gatilho: Convencional Velocidade (boca) m/s: 137 Velocidade (boca) pés/seg: 450 Energia (boca) joules: 8,5 Força necessária para engatilhar (kg): 8,5 Sistema de Funcionamento: Sistema de engatilhamento por alavanca acionada pelo basculamento do cano Capacidade: Tiro individual de chumbinhos Sistema de Pontaria: Aparelho de pontaria com fibra óptica Alça de mira com regulagem horizontal e vertical Massa de mira fixa protegida por túnel Segurança: Trava ambidestra automática localizada no gatilho Sistema que impede o disparo com o cano aberto Mola: Convencional em Aço Distância máxima do tiro(m): 152 Peso (kg): 2,1kg ATENÇÃO: "O uso do produto exige treinamento e equilíbrio emocional." "Deverá ser guardado em lugar seguro e fora do alcance de terceiros."', 1010.9, 707.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Shooting & Survival Games', 'https://cf.shopee.com.br/file/sg-11134201-7ra19-m54hl0mrugevb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567374315%2F23993629751', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
