INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298257918', 'FILTRO COMBUSTÍVEL UNO VIVACE 1.0 1.4 2013 2014 2015 - 99015 - FCI1660', 'FILTRO COMBUSTÍVEL UNO VIVACE 1.0 1.4 2013 2014 2015 Motor 1.0/1.4 8v Fire Evo Flex - (Mecânico) (Plástico)O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 27.11, 27.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6q-m6vr61o4lu7d50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298257918', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
