INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21261850994', 'Kit Vela Cabo Vela Ignição Uno Mille 1.0 95 96 97 98 99 Ngk', 'Aplicação FIAT UNO MILLE 1.0 ELECTRONIC 4P 1993 até 1996 UNO MILLE 1.0/ I.E./ ELECTRONIC/ BRIO 1993 até 1997 UNO MILLE CELEB. WAY ECON. 1.0 F.FLEX 2P 1994 UNO MILLE SX YOUNG 1.0 IE 1998 até 1999 Conteúdo Da Embalagem 4 Velas de Ignição 1 Jogo de Cabo de Vela de Ignição Cor do Produto No Tipo de Veículo para Carros Marca A NGK fabrica itens automotivos desde 1959 no Brasil. Revestimentos porcelanizados, cabos de ignição e velas, terminais supressivos e cerâmicas técnicas fazem parte da extensa gama de produtos da empresa. O Produto A finalidade primordial da vela de ignição é propagar a corrente elétrica que o transformador gera até a câmara de combustão, até converter em uma centelha elétrica de alta voltagem, o que iniciará a combustão, ou seja, é o executor pela certa queima da mistura ar-combustível. Os cabos de ignição têm o papel de conduzir a corrente elétrica do transformador até as velas de ignição partilhando a corrente na ordem certa da ignição do motor. Importante • Recomendamos que os produtos sejam aplicados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses. • Valor referente ao kit. • Imagem meramente ilustrativa. EAN 7897707501595 Código do Fabricante SCT07 Combustível GASOLINA Combustível Gasolina', 160.68, 160.68, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbkg-llt8362kco9cf3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21261850994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20761905355', 'Kit Vela E Cabo Vela De Ignição Zafira 2.0 2001 A 2012 Bosch', 'Aplicação CHEVROLET ZAFIRA COLLECTION 2.0 FLEXPOWER 8V AUT. 2012 ZAFIRA COMFORT 2.0 MPFI FLEXPOWER 8V 5P 2009 até 2012 ZAFIRA ELEG.2.0 MPFI FLEXPOWER 8V 5P AUT 2009 até 2012 ZAFIRA ELEGANCE 2.0 MPFI FLEXPOWER 8V 5P 2009 até 2010 ZAFIRA ELITE 2.0 MPFI FLEXPOWER 8V AUT 2009 até 2012 ZAFIRA ELITE 2.0 MPFI FLEXPOWER 8V 5P 2009 até 2011 ZAFIRA EXPRES. 2.0 MPFI FLEXPOWER 5P AUT 2009 até 2012 Conteúdo Da Embalagem 4 Velas de Ignição 1 Jogo de Cabo de Vela Cor do Produto No Tipo de Veículo para Carros Marca O Grupo Bosch é um líder mundial no fornecimento de tecnologia e serviços. A empresa emprega mais de 390.000 colaboradores em todo o mundo. A Bosch oferece soluções inovadoras para casas e cidades inteligentes e mobilidade e indústria conectadas. A empresa utiliza sua expertise em tecnologia de sensores, software e serviços. A mesma está presentes em aproximadamente 60 países. O Produto A vela é a peça responsável por produzir a fagulha inicial que acende a mistura de combustível e ar contida dentro do motor, criando a explosão necessária para acionar os pistões, criando a força mecânica necessária para fazer o veículo se mover. A função dos cabos de vela é conduzir a alta tensão produzida pela bobina ou transformador até as velas de ignição, sem permitir fugas de corrente, garantindo uma ignição sem falhas. Importante • Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses. • Valor referente ao kit. • Imagem meramente ilustrativa. • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 4047024616899 Código do Fabricante F00099C01 Combustível FLEX Combustível Flex', 197.09, 197.09, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbkb-llw69vvrgu3dfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20761905355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20259973697', 'Jogo Vela De Ignição Ford Ecosport 1.0 1.6 2003 A 2017 Bosch', 'Aplicação FORD ECOSPORT FREESTYLE 1.6 16V FLEX 5P 2012 até 2017 ECOSPORT FREESTYLE 1.6 16V FLEX 5P AUT. 2016 até 2017 ECOSPORT S 1.6 16V FLEX 5P 2013 até 2015 ECOSPORT SE 1.6 16V FLEX 5P AUT. 2016 até 2017 ECOSPORT SE 1.6 16V FLEX 5P MEC. 2013 até 2017 ECOSPORT SE DIRECT 1.6 16V FLEX 5P AUT. 2017 ECOSPORT TITANIUM 1.6 16V FLEX 5P 2013 até 2015 ECOSPORT XL SUPERCHARGER 1.0 8V 95CV 5P 2003 até 2006 Conteúdo Da Embalagem 4 Velas de Ignição Cor do Produto No Observação Somente Motor 1.0 8v / 1.6 16v Tipo de Veículo para SUV''s e Caminhonetes Marca O Grupo Bosch é um líder mundial no fornecimento de tecnologia e serviços. A empresa emprega mais de 390.000 colaboradores em todo o mundo. A Bosch oferece soluções inovadoras para casas e cidades inteligentes e mobilidade e indústria conectadas. A empresa utiliza sua expertise em tecnologia de sensores, software e serviços. A mesma está presentes em aproximadamente 60 países. O Produto A Função Principal da vela de ignição é transmitir a corrente elétrica que o transformador gera até a câmara de combustão, até transformar em lume elétrica de alta tensão, o que dará início a combustão, ou seja, é responsável pela certa queima da mistura ar combustível. Apesar de pequena e simples, trata-se de um item muito importante para o carro. A performance da vela vai definir o bom funcionamento do motor, controlar os níveis de combustível e até mesmo a emissão de poluentes. Importante • Recomendamos que os produtos sejam aplicados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. • Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. • Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. • Tempo de garantia: 3 Meses • Valor referente ao jogo • Imagem meramente ilustrativa • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 4047024656871 Código do Fabricante F000KE0P45 Combustível FLEX GASOLINA Combustível Flex Gasolina', 90.22, 90.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbmj-llxge6bek2eb46', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F20259973697', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42873140489', 'Andador Articulado 3 Barras Hidrolight', 'Andador Articulado 3 Barras - Hidrolight foi desenvolvido para oferecer mais liberdade, segurança e estabilidade para pessoas com dificuldade de locomoção, déficit de equilíbrio, fraqueza muscular ou em recuperação pós-cirúrgica. Com estrutura em alumínio leve, este andador suporta até 135 kg, sendo ideal para proporcionar suporte durante a deambulação. Oferece três modos de uso: fixo, articulado e dobrável, garantindo conforto e praticidade para o usuário. Indicações de uso mais frequentes: Suporte para pessoas com dificuldade de locomoção ou déficit de equilíbrio Auxílio no pós-operatório e em casos de fraqueza muscular Ajuda idosos a manter a mobilidade com segurança, prevenindo quedas Os 5 maiores benefícios e diferenciais do Andador Articulado 3 Barras - Hidrolight Possui estrutura leve em alumínio, proporcionando resistência e fácil manuseio, ideal para uso diário. Três modos de uso (fixo, articulado e dobrável), permitindo ao usuário escolher a função mais adequada às suas necessidades. Suporta até 135 kg, oferecendo maior segurança e estabilidade para pessoas de diferentes pesos. Apoio de mãos anatômico e ponteiras em borracha aderente, que ajudam a evitar escorregões e proporcionar conforto durante o uso. Fácil de montar e dobrar, o que facilita o armazenamento e transporte em espaços pequenos, como porta-malas.', 179.9, 139.9, NULL, 'Health > Medical Supplies > Injury & Disability Support', 'https://cf.shopee.com.br/file/br-11134201-81z1k-mfk2vq318jyf97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F42873140489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211511960', 'Kit Body Splash e Hidratante Roses Barbour''s', 'Body Splash Roses 200ml Hidratante Corporal Roses 230g HIDRATANTE: Essential Body Cream Roses Barbour’s Beauty 230g é um hidratante desodorante corporal desenvolvido para proporcionar hidratação prolongada, toque aveludado e perfumação sofisticada em uma rotina de cuidados prática e confortável. Sua textura leve facilita a aplicação e espalhabilidade, garantindo rápida absorção sem deixar sensação pegajosa na pele. Sua fragrância feminina, luminosa e irresistível combina notas cítricas e florais com um fundo delicadamente adocicado, criando uma experiência sofisticada e envolvente ao longo do dia. O perfil olfativo destaca acordes de Pimenta Rosa, Flor de Pêssego e Almíscar Branco, trazendo frescor, elegância e sensualidade na medida certa. A fórmula reúne ativos hidratantes e nutritivos que auxiliam no cuidado diário da pele, como Glicerina e Hidroxietil Ureia, que ajudam a manter a hidratação e o conforto prolongado. Conta ainda com Manteiga de Karité, Óleo de Girassol, Óleo de Amêndoas e Óleo de Coco, que contribuem para nutrição, maciez e toque sedoso. Pantenol, Ácido Hialurônico e Vitamina E complementam a fórmula promovendo aparência saudável, pele mais confortável e sensorial suave e aveludado.Ideal para quem busca uma pele hidratada, macia, perfumada e com sensação de frescor durante todo o dia. Pode ser usado sozinho ou combinado com o Body Splash Roses para intensificar e prolongar a perfumação através da técnica de layering. BENEFÍCIOS: • Textura leve, fácil de espalhar e rápida absorção • Hidratação prolongada com conforto ao longo do dia • Pele macia, aveludada e delicadamente perfumada • Sensação confortável sem pesar ou deixar a pele oleosa • Fragrância cítrica floral feminina, sofisticada e envolvente • Ideal para layering com o Body Splash Roses • Fórmula enriquecida com ativos hidratantes e nutritivos NOTAS DA FRAGRÂNCIA: • Perfil olfativo: Cítrica floral com notas adocicadas • Notas em destaque: Pimenta Rosa, Flor de Pêssego e Almíscar Branco MODO DE USAR:Aplique o hidratante sobre a pele limpa e seca, massageando suavemente até completa absorção. Reaplique sempre que desejar intensificar a hidratação e perfumação. RESULTADO: Pele hidratada, macia, confortável, iluminada e perfumada com uma fragrância feminina marcante e sofisticada. PRECAUÇÕES: Uso externo. Não ingerir. Manter fora do alcance de crianças. Em caso de irritação, suspenda o uso e procure orientação médica. Evite contato com os olhos. Caso ocorra, enxágue abundantemente com água. Inspirado em: Importado BODY SPLASH: O Body Splash Roses Desodorante Colônia da Barbour’s Beauty é uma fragrância encantadora que evoca a beleza e o romance das rosas frescas em plena floração. Combinando notas florais, frutadas e amadeiradas, esta fragrância é perfeita para mulheres que apreciam a delicadeza e sofisticação das flores. As notas de topo, com laranja sanguínea e mandarina, trazem um frescor inicial irresistível. No coração, gardênia, jasmim e pêssego se unem para criar uma aura romântica e envolvente, enquanto as notas de fundo, como caramelo, cera de abelha e patchouli, adicionam profundidade e mistério, garantindo uma fragrância duradoura. Perfeito para qualquer ocasião, o Body Splash Roses oferece uma experiência olfativa que combina charme, feminilidade e elegância. O Body Splash Roses utiliza uma fórmula leve e refrescante, com uma combinação equilibrada de notas florais e frutadas que garantem um fragrância duradoura e envolvente. Com uma composição que permite uma aplicação suave e uniforme, o perfume se dispersa de forma delicada, proporcionando frescor e elegância sem sobrecarregar os sentidos. A combinação de caramelo e patchouli nas notas de fundo garante um rastro sofisticado e marcante. BENEFÍCIOS: Fragrância Romântica e Feminina: Notas florais e frutadas evocam a delicadeza das rosas, criando uma experiência olfativa encantadora. Suave e Duradouro: A fragrância permanece na pele ao longo do dia, deixando um rastro sutil e sofisticado. Frescor e Elegância: As notas de topo proporcionam frescor imediato, enquanto as notas de fundo garantem profundidade e mistério. Versátil: Ideal para uso diário ou eventos especiais, oferecendo uma fragrância leve e envolvente para qualquer ocasião. Fórmula Leve: Proporciona uma aplicação suave e refrescante, deixando a pele delicadamente perfumada sem sobrecarregar. NOTAS DA FRAGRÂNCIA:Notas de Topo: A fragrância se inicia com uma explosão de laranja sanguínea e mandarina, proporcionando uma sensação inicial de frescor e vitalidade que é simplesmente irresistível.', 112.9, 79.03, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/br-11134207-820lc-mos4fq8ffkee58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1579330222%2F58211511960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498125926', 'Kit 2 Pares Meia Sapatilha Algodão Infantil Antiderrapante Bebê Soquete Cano Curto Menino Menina', 'O Kit com 2 Meias Sapatilha Antiderrapante Winston é ideal para proteger os pezinhos dos bebês e crianças com conforto, segurança e muito estilo. Com design tipo sapatilha e solado antiderrapante, oferece mais estabilidade para os primeiros passos e brincadeiras, sem abrir mão da fofura. Principais Benefícios: Antiderrapante: Segurança extra para evitar escorregões em pisos lisos. Estilo sapatilha: Cano curto e calce fácil, ideal para dias quentes e para usar com qualquer tipo de roupa. Estampas divertidas: Cores alegres e desenhos que encantam meninos e meninas. Toque macio e respirável: Com alto teor de algodão, garante conforto para o uso prolongado. Composição: 82% Algodão – Suavidade e absorção natural do suor. 17% Poliamida – Durabilidade e leveza. 1% Elastano – Flexibilidade para um ajuste perfeito. Indicado para: Bebês e crianças pequenas em fase de engatinhar ou dar os primeiros passos Uso diário em casa, escolinha ou passeios. Um ótimo presente para chás de bebê, aniversários ou compor o enxoval. Produto 100% nacional, fabricado no Brasil com qualidade superior. Com mais de 56 anos de tradição, a Winston é referência em conforto e confiança para todas as fases da infância. Fabricadas no Brasil, nossas meias são um produto 100% nacional, desenvolvido com carinho e responsabilidade para garantir o melhor para os pés das suas filhas e filhos . Ao escolher Winston, você está optando por apoiar a indústria local e fortalecer a economia nacional. A Winston está no mercado há 56 anos, construindo uma história de confiança e qualidade. Nossas meias são produzidas com o compromisso de entregar sempre o melhor para nossos clientes. Ao escolher Winston, você está optando por uma marca com décadas de experiência e dedicação ao conforto e bem-estar de seus consumidores.', 59.99, 59.99, NULL, 'Baby & Kids Fashion > Baby & Kids Accessories > Socks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbfjdogaf2wo7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920749716%2F23498125926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
