INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793628272', 'Cooler Fan LED RGB Processador CPU Multi Intel AMD Knup G-VR344', 'O Cooler para Processador com TDP de 150W é a solução ideal para quem busca eficiência no resfriamento do seu sistema. Com quatro tubos de calor e rolamento hidráulico, ele garante um desempenho superior na dissipação de calor, mantendo seu processador sempre em temperatura ideal para um funcionamento estável e duradouro. Com uma velocidade de 1500 rpm ± 10%, esse cooler foi desenvolvido para proporcionar um fluxo de ar potente e constante, enquanto o seu design otimizado ajuda a reduzir o ruído durante a operação, garantindo um ambiente mais silencioso. Além disso, ele conta com um conector de 3 pinos, compatível com a maioria das placas-mãe no mercado. ESPECIFICAÇÕES: - TDP: 150W - 4 Tubos de calor - Modelo: G-VR344 - Velocidade: 1500 rpm ± 10% - Tensão de operação: 12Vdc - Tipo de rolamento: Hidráulico - Conector: 3 Pinos - Dimensões do dissipador: 122 x 70 x 153mm (C x L x A) - Dimensões do cooler: 120 x 120 x 25mm (C x L x A) CONTEÚDO: 1 Cooler para Processador', 112.07, 73.01, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-7ra0j-m51w2ebuxbbr10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376716003%2F23793628272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
