INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997973974', 'Kit 2 Displays de Mini Chocolate Linea Sabor Ao Leite Zero Lactose e Branco 15 unidades de 13g', 'Linea Chocolate é sem adição de açúcares. Adoçado com sucralose e maltitol e com a manteiga de cacau como o 1º ingrediente, resulta em um chocolate macio e cremoso. Sabor indescritível que derrete na boca! 1 Kit Composto por: - 1 display Mini Chocolate Linea Ao Leite Zero Lactose 15 Unidades de 13g cada - 1 display Mini Chocolate Linea Branco 15 Unidades de 13g cada INGREDIENTES SABOR CHOCOLATE AO LEITE ZERO LACTOSE manteiga de cacau, leite em pó integral zero lactose, massa de cacau, edulcorante maltitol, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. NÃO CONTÉM GLÚTEN INGREDIENTES SABOR CHOCOLATE BRANCO manteiga de cacau, leite em pó integral, soro de leite desmineralizado, gordura vegetal, fibra de milho solúvel, colágeno, edulcorantes: maltitol e sucralose, umectante: polidextrose, emulsificantes: lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. CONTÉM LACTOSE.', 181.18, 144.94, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-m1ehkrrn97p641', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1365822827%2F22997973974', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393148795', 'Relógio Orient Automático Masculino 469SS087NH E1SX', 'SOBRE A EMPRESA: Somos a Relógios Campana, uma empresa especializada em vendas online, revendedora autorizada das maiores marcas do mercado. Trabalhamos apenas com relógios originais com garantia de fábrica. Comprando conosco você tem a segurança que receberá seu produto nas seguintes condições: ✅ REVENDEDOR AUTORIZADO ✅ PRODUTO ORIGINAL ✅ GARANTIA DO FABRICANTE ✅ PRODUTO NOVO ✅ EMBALAGEM ORIGINAL DO PRODUTO ✅ MANUAL DE INSTRUÇÕES ✅ CERTIFICADO DE GARANTIA ✅ NOTA FISCAL ✅ RELÓGIO A PRONTA-ENTREGA SOBRE O PRODUTO: O relógio Orient 469SS087 E1SX oferece a combinação ideal de robustez, confiabilidade e elegância atemporal — perfeito para uso no dia a dia ou em ocasiões sociais. Ele integra os elementos clássicos da marca, com construção sólida e funcionamento automático (sem bateria). Especificações: Marca: Orient Modelo: 469SS087 E1SX Tipo de relógio: Analógico Gênero: Masculino Cor da caixa: Prateado Cor da pulseira: Prateado Estilo: Casual Alarme: Não Cronômetro: Não Calendário: Sim Luz: Não – ponteiros fluorescentes Resistência à água: Sim – rotinas diárias Tipo de fecho: Dobrável com trava lateral Material da caixa: Aço Inoxidável Material da Pulseira: Aço Inoxidável Características do vidro: Cristal Mineral Tamanho da caixa: 42 mm Espessura da caixa: 12 mm Comprimento da pulseira: 25 cm Largura da pulseira: 22 mm Tampa do fundo: Rosqueado Peso: 150 Gramas Alimentação: Automático Conteúdo da Embalagem: Relógio, nota fiscal, certificado garantia e manual de instruções Garantia do Fabricante: 12 meses Fabricante: Orient Relógios da Amazônia LTDA', 1129.9, 1129.9, NULL, 'Watches > Men Watches', 'https://cf.shopee.com.br/file/sg-11134201-823r7-moybbjlvv28b77', 'https://shope.ee/an_redir?origin_link=https%3A%2