INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993489727', 'Kit Deo Colônia Tabu Tradicional Flores 60Ml (2 unidades)', '✨ Fragrância: Feminina O Kit Deo Colônia Tabu | Tradicional + Flores, é a escolha perfeita para quem deseja ter o melhor dos dois mundos. O Tabu Tradicional exala uma fragrância poderosa e elegante, enquanto o Tabu Flores traz uma suavidade floral envolvente. Juntos, esses perfumes oferecem uma fragrância completa para todas as ocasiões, garantindo frescor e feminilidade o dia todo. Uma combinação ideal para mulheres que apreciam sofisticação e frescor. O que o Kit contém? ✅ 1 unidade - Deo Colônia Tabu Tradicional ✅ 1 unidade - Deo Colônia Tabu Flores Benefícios: ✅ Fragrância clássica tradicional Tabu ✅ Fragrância floral delicada e envolvente ✅ Pele suave e fresca o dia inteiro ✅ Praticidade e frescor em um único kit Modo de Uso: 1️⃣Escolha a fragrância que combina com o momento: Tabu Tradicional para ocasiões mais marcantes ou Tabu Flores para um toque de frescor. 2️⃣Reaplique ao longo do dia para manter a intensidade do aroma.', 44.78, 38.54, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/sg-11134201-7rep1-m1poabhgnoo745', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436104412%2F22993489727', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
