INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197845961', 'Kit 2 Dermotivin Original Sabonete Líquido para Pele Mista ou Oleosa 300ml', 'Dermotivin Original Sabonete Líquido Pump 300ml Sua formulação, com extratos naturais de calêndula, aloe vera e derivados do óleo de coco, possui ação emoliente, suavizante e reduz a oleosidade, mantendo o equilíbrio natural da pele. Como resultado, proporciona uma pele mais uniforme. Produto não comedogênico. Dermatologicamente testado. Cuidado diário. Benefícios: Possui ação emoliente, suavizante e reduz a oleosidade, mantendo o equilíbrio natural da pele. Uso específico: Pele mista a oleosa. Modo de Usar: Aplique sobre o rosto e pescoço umedecidos em suaves movimentos circulares. Enxágue por completo. Use duas vezes ao dia ou conforme orientação do seu dermatologista. Precauções e avisos de segurança: Mantenha o produto longe do alcance das crianças. Se ocorrer irritação, interrompa o uso. Em caso de ingestão acidental, procure atendimento médico. Em caso de contato com os olhos, enxágue imediatamente. Conservar em temperatura ambiente e ao abrigo do sol. Uso externo. Principais Características: Elimina o excesso de oleosidade sem ressecar. Ação emoliente e suavizante proporcionada pelos extratos de Aloe Vera e Calêndula. Marca: Dermotivin. Linha: Original. Peso Líquido (Volume): 300ml. Local de Utilização: Limpeza facial. (Apresentação / Categoria) do SKU: Líquido.', 110.18, 110.18, NULL, 'Beauty > Beauty Tools > Facial Care Tools', 'https://cf.shopee.com.br/file/sg-11134201-823pb-molo743py7m46c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23197845961', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
