INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20697678065', 'Antipulgas e Carrapatos NexGard Spectra Cães de 2 a 3,5kg', 'Antipulgas e Carrapatos NexGard Spectra Cães NexGard Spectra tem um rápido início de ação e atinge 100% de eficácia em 8 horas para pulgas. Pode ser administrado em cães adultos e filhotes acima de 2kg e a partir de oito semanas de vida.Referência no tratamento contra parasitas externos e internos, NexGard Spectra é o tablete mastigável comprovadamente seguro para cães de qualquer raça e conta com uma linha completa para atender diferentes portes e pesos.Os tabletes NexGard Spectra foram pensados para evitar a dificuldade usual na administração de remédios a animais, apresentando sabor agradável que os cães adoram.Para manter seu pet livre de pulgas, carrapatos, sarna e vermes, administre NexGard Spectra mensalmente, uma solução completa, é um e pronto!', 94.99, 88.34, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjeh70dc0jra99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F20697678065', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
