INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893635658', 'Temporizador Analógico 24h Bivolt Bestfer', 'O Temporizador Analógico 24h Bivolt Bestfer é a solução ideal para quem busca praticidade e eficiência no controle de equipamentos elétricos. Com sua capacidade de programação de até 24 horas, ele permite uma gestão fácil do consumo energético. Compatível com 110V e 220V, oferece versatilidade para diferentes ambientes e aplicações. Este temporizador é perfeito para automatizar o funcionamento de eletrodomésticos, iluminação e sistemas de segurança. Seu indicador LED facilita a visualização do status, proporcionando maior segurança e conveniência ao usuário. Vantagens: - Tipo de Temporizador: Analógico, ideal para programação simples. - Bivolt: Compatível com 110V e 220V. - Programação até 24 horas: Controle eficiente do uso de energia. - Modos Automático e Manual: Flexibilidade no controle dos aparelhos. - Indicador LED: Luz que indica o funcionamento do dispositivo. - Proteção contra Sobrecargas: Maior segurança e durabilidade. Especificações técnicas: Marca: Bestfer Tipo: Temporizador analógico Voltagem: Bivolt (110V/220V) Frequência: 50/60 Hz Saída: 1 tomada padrão Conteúdo da embalagem: 1 Temporizador Analógico 24h Bivolt Bestfer Garantia: - 3 meses de garantia', 81.9, 47.5, NULL, 'Home Appliances > Electrical Circuitry & Parts > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4ys4z1bo9tee4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22893635658', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
