INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13953654110', 'Ração Úmida Whiskas Sachê Gatos Adultos Cordeiro Ao Molho 85g', '- Indicada para gatos; - Refeição completa e balanceada; - Feita com ingredientes naturais de alta qualidade, vitaminas e minerais; - Sem conservantes, sem corantes artificiais e sem aromatizantes artificiais; - Suculentos pedacinhos cozidos a vapor; - Ajuda a manter a saúde do trato urinário; - Porção ideal de proteína, vitaminas e sais minerais; - Disponível em embalagem com 85 g. Inclua o alimento úmido nas refeições do seu gato pelo menos 1 vez ao dia e mantenha-o sempre saudável. Toda mudança na alimentação deve ser feita de forma gradual. Inicie oferecendo 1 sachê ao dia dividido entre 2 refeições e aumente a quantidade nos próximos 7 dias. Mantenha sempre água fresca à disposição do seu gato. INGREDIENTES Miúdo de cordeiro, miúdo de suíno, carcaça de frango, plasma suíno em pó, farinha de trigo, celulose em pó, água, amido de milho, taurina, vitaminas (D3, E, C, B1, B6, K3, cloreto de colina, niacina, ácido fólico), minerais (cloreto de sódio – sal comum, cloreto de potássio, sulfato de cobre, iodato de cálcio, óxido de zinco, óxido de manganês, óxido de magnésio), tripolifosfato de sódio, xilose, glicina, corante natural caramelo, goma xantana. Eventuais substitutivos: Carne mecanicamente separada de frango, miúdo de ave, vísceras de aves, gordura de frango, cabeça de frango, pé de frango, miúdo de bovino, baço de bovino, baço suíno, polpa de beterraba, glúten de trigo, proteína concentrada de soja, fosfato bicálcico.', 5.49, 5.49, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/1470a8ac821ca8975f34107ba217c495', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F398944029%2F13953654110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
