INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40668101557', 'Sandália Chinelo Molekinha Menina Infantil Papete Conforto Rosa', '👧 Sandália Chinelo Molekinha Menina Infantil Papete Conforto com Elástico ✨ A Sandália Papete Molekinha Infantil foi feita para acompanhar o dia a dia das pequenas com muito conforto e estilo. O fechamento em elástico facilita o calce, garantindo praticidade e firmeza ao caminhar. Com design moderno e detalhes delicados, é ideal para passeios, escola ou momentos de lazer, unindo bem-estar e versatilidade. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/41354860152/ ✅ Diferenciais do Produto 👧 Fechamento em elástico que facilita o calce 🌸 Design moderno e delicado 👣 Palmilha macia e confortável 💪 Solado leve e antiderrapante ✔️ Ideal para uso diário das meninas 📋 Ficha Técnica Marca: Molekinha Modelo: Papete Infantil Conforto com Elástico Gênero: Menina / Infantil Estilo: Casual / Dia a Dia Material externo: Sintético Material interno: Têxtil macio Palmilha: Confortável Solado: Borracha antiderrapante Fechamento: Elástico (calce fácil) 🧼 Dicas de Limpeza Limpar com pano levemente úmido Usar sabão neutro se necessário Secar à sombra em local arejado Não expor ao sol ou calor em excesso 📏 Tabela de Tamanhos (cm aproximados) 17/18 - 12,4cm 19/20 - 12,9cm 21/22 - 14,3cm 23/24 - 15,7cm 25/26 - 16,9cm', 99.9, 59.9, NULL, 'Baby & Kids Fashion > Girl Shoes > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meeqpcj4d3pc67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F40668101557', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54258417573', 'Tênis Ramarim Plataforma Casual Confortável Original 2483232', '***ENVIO IMEDIATO APÓS A CONFIRMAÇÃO DO PAGAMENTO*** SEJAM BEM VINDOS À KROKODILUS SURF! DESCRIÇÃO: O tênis feminino Ramarim é ideal para quem busca conforto e praticidade sem abrir mão de um visual moderno. Com design casual e acabamento sofisticado, o modelo combina perfeitamente com produções urbanas e looks versáteis do dia a dia. Seu cabedal traz mix de materiais e detalhes que deixam o visual mais elegante e estiloso. O fechamento em cadarço proporciona melhor ajuste aos pés, enquanto o solado baixo garante estabilidade e conforto durante o uso prolongado. Produzido com materiais resistentes e acabamento de qualidade, esse tênis é perfeito para combinar com jeans, vestidos, shorts e conjuntos casuais, sendo uma excelente opção para quem busca um calçado confortável e cheio de personalidade. ESPECIFICAÇÕES: Marca: Ramarim; Categoria: Tênis feminino; Gênero: Feminino; Material do cabedal: Sintético; Fechamento: Cadarço; Solado: Borracha / PVC resistente; Palmilha: Macia e confortável; Altura do solado: Aproximadamente 2,5 cm; Estilo: Casual / Urbano; Indicação de uso: Dia a dia, passeios, trabalho. TABELA DE TAMANHOS: 34 - 23cm 35 - 23,5cm 36 - 24cm 37 - 25cm 38 - 25,5cm 39 - 26cm 40 - 26,5cm', 199.9, 149.9, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-820lg-mn2xetegotmob3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F54258417573', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593691941', 'Par Cubo Preto Dianteiro/traseiro Cg Fan 125 2009 Até 2018', 'PAR DE CUBO PRETO FAN 125 09 FREIO A TAMBOR Anuncio Contem: 01 - Cubo Roda Traseira (PRETO) - (TAMBOR) 01 - Cubo Roda Dianteira (PRETO) - (TAMBOR) PERSONALIZAÇÃO : CUBO PRETO Compatível com: Fan 125 - Ano 2009 até 2018 (FREIO TAMBOR) Sendo líder de mercado, os cubos são confeccionados em liga de alumínio especial e com pintura no padrão da original, além de serem produzidos em modernos equipamentos de usinagem, proporcionam grande durabilidade e resistência do produto. Conservação Os cuidados para conservação da Pintura, tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 309.9, 309.9, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-820lc-mpw6aeyvvev4c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1012518791%2F22593691941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
