INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698679941', 'Adaptador Joy para Bebê Conforto i Prime KikkaBoo', 'Praticidade no Passeio Transforme seu carrinho Joy em um verdadeiro Travel System com o adaptador exclusivo para Bebê Conforto i-Prime. Com um simples clique, você acopla o bebê conforto à estrutura do carrinho, proporcionando mais praticidade e segurança nos passeios com o seu bebê. Versatilidade no Uso O Bebê Conforto i-Prime pode ser instalado no carro tanto com quanto sem os adaptadores, garantindo flexibilidade para o dia a dia e para diferentes necessidades de transporte. Design e Estilo Disponível na elegante cor preta, esse adaptador é o complemento ideal para quem busca versatilidade e mobilidade sem abrir mão do conforto e da segurança.', 89.9, 89.9, NULL, 'Mom & Baby > Baby Travel Essentials > Stroller Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7ra17-mbh5hvwj8xutdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1419417476%2F22698679941', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
