INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256320821', 'Accu-Chek Guide Me 50ct Kit mg/dl sc', 'Monitor Accu-Chek Guide com 50 Tiras para Medir Glicemia O Monitor Accu-Chek Guide é uma solução prática para acompanhar os níveis de glicose no sangue com rapidez e precisão. Este kit inclui o monitor Accu-Chek Guide e 50 tiras de teste, oferecendo mais praticidade no dia a dia para quem realiza medições frequentes. Por que escolher este kit? Resultados em até 5 segundos com codificação automática Tiras intuitivas que facilitam a inserção Monitor com visor ampliado, fácil de ler e usar Kit completo para medições rápidas e confiáveis no dia a dia Como usar Insira a tira no monitor corretamente Realize a punção no dedo com o lancetador Aplique a gota de sangue na tira Em poucos segundos, visualize o resultado no visor Dica:Troque a lanceta a cada uso para manter a higiene e o conforto durante as medições.', 163.9, 163.9, NULL, 'Health > Medical Supplies > Health Monitors & Tests', 'https://cf.shopee.com.br/file/sg-11134201-8261q-mliakgr597nzf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1752518960%2F58256320821', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
