INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201682173', 'Bateria Para Apache 200 Dafra 9ah', 'Produzidas com tecnologia VRLA e separadores de fibra de vidro AGM, a Pioneiro disponibiliza ao mercado a linha Pioneiro MBR, com alto padrão de qualidade, buscando atender aos motociclistas mais exigentes. Bateria livre de manutenção, à prova de vazamentos, que oferece maior resistência a impactos e vibrações. Sua qualidade é comprovada através das certificações ISO 9001, INMETRO e IATF 16949, que levaram a Pioneiro MBR ao mercado de montadoras, tornando-a um produto orginal das marcas Dafra, KTM e Royal Enfield. Pioneiro MBR, a energia para viver a liberdade em duas rodas! Marca Pioneiro MBR Modelo MBR 9A YS Material Chumbo-Ácido Tipo de Bateria AGM Tecnologia VRLA Tensão 12 V Capacidade (C10) (25ºC) 9 Ah Corrente de Partida (CCA) (-10°C) 90 A Tempo até 6V 40 s Carga Lenta 0,9 A x 5 ~ 10 h Carga Rápida 4,5 A x 1 h Polaridade Esquerda Tipo de Polo Reto Selada Sim Classificação Livre de Manutenção Posição de Instalação Horizontal, Vertical Dimensões (C x L x A) 137 x 76 x 134 mm Peso 2,75 kg Garantia 9 meses Aplicação DAFRA APACHE RTR 200cc SUNDOWN VBLADE 250cc SUZUKI EN 125 YES, EN 125 YES CARGO, INTRUDER 125', 287.0, 287.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Batteries', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi1ofccrkuted2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F858321375%2F58201682173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
