INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42266903517', 'Jogo Infantil Cirurgião Game Dinossauro +4 Anos Braskit Brinquedo Infantil Educativo Coordenação', 'Desafie sua habilidade e concentração com o Jogo Operando Dinossauro! O objetivo é simples e emocionante: usar a pinça metálica para retirar todas as peças da base sem encostar nas laterais… se errar, o dinossauro acorda! Perfeito para brincar sozinho ou com amigos, este jogo estimula a coordenação motora fina, paciência e raciocínio rápido, garantindo momentos de risadas e competição saudável. Funciona com 3 pilhas AA (não inclusas) e é indicado para crianças a partir de 4 anos. Características: - Tema: Dinossauro - Inclui: Base do jogo, pinça metálica e peças para retirar - Idade recomendada: +4 anos - Alimentação: 3 pilhas AA (não inclusas) - Ideal para jogar sozinho ou em grupo Benefícios: - Estimula coordenação motora e precisão - Incentiva concentração e habilidades manuais - Promove interação entre amigos e família - Brincadeira divertida e desafiadora Características: - Marca: Braskit - Modelo: 1203 Imagens Meramente Ilustrativas Conteúdo da Embalagem: - 01x Jogo Cirurgião - 12x Peças jogo infantil cirurgião; jogo cirurgião dinossauro; brinquedo educativo braskit; jogo interativo infantil; jogo de habilidade crianças; jogo cirurgião game; jogo dinossauro infantil; brinquedo diversão +4 anos; jogo cirurgião braskit 1203; jogo clássico infantil', 72.18, 61.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-824gp-me4ewne54w0060', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F42266903517', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
