INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15609110616', 'Shampoo lava autos neutro com cera concentrado luxcar', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia. 500 ml O alto poder de limpeza do Lava Autos Neutro com Cera Concentrado Luxcar remove até as sujeiras mais pesadas, promove alto brilho e proteção, pode ser utilizado em qualquer veículo ou pintura sem manchar. Produz mais espuma com menos produto e é muito mais fácil de enxaguar que os lava autos convencionais. Vantagens: • Nanotecnologia: Separa a sujeira da lataria evitando riscos e hologramas. • Limpa e encera simultaneamente. • Enxágue muito mais rápido com menos água. • Não agride nem mancha pinturas novas ou clássicas. • Limpa, desengordura e dá alto brilho em todas as partes do seu carro. Modo de usar: Em um balde com 1 litro de água diluir 100 ml do Lava Autos com Cera Concentrado Luxcar. Aplicar sobre a lataria do veículo com uma esponja macia ou luva microfibra na sombra. A espuma formada deverá ser deixada sobre a lataria por pelo menos 3 minutos para em seguida ser removida com água. Após secagem com pano limpo e macio o resultado será um veículo limpo e com brilho intenso. Validade 24 meses.', 26.0, 26.0, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/aa32b65f1949df8e067fbd85a5186630', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F15609110616', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
