INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699759953', 'Tenis Mizuno Space 5 Masculino Tamanho Espcial 101034034', 'Tênis Mizuno Space 5, Tecido mesh e cabedal injetado proporcionando estrutura e um visual arrojado. O tênis ideal para te acompanhar em todas as suas atividades. Sua entressola de tecnologia exclusiva que proporciona mais conforto e seu solado possui borracha garantindo aderência e durabilidade. Além disso, seu cabedal possui um tecido que garante respirabilidade e flexibilidade para os pés. Medidas: 37 - 24,5cm 38 - 25cm 39 - 25,5cm 40 - 26,5cm 41 - 27,5cm 42 - 28cm 43 - 29cm 44 - 30cm 45 - 31cm 46 - 32cm 47 - 33cm 48 - 33,5cm Preto/Pétala Cabedal preto com detalhes em alaranjado. Solado branco com detalhes em preto e laranja. Preto/Preto (Cód 69) Cabedal e solado em preto, com detalhes no cabedal em dourado. Preto (cód 90) Cabedal em preto com detalhes em branco, solado branco com detalhes em preto. Chumbo (cód 924) Cabedal em cinza e preto com detalhes em amarelo açafrão, solado bege com detalhes em caramelo Branco Cabedal e solado em branco, com detalhes em preto e forro interno em preto. Tamanho especial Produto ORIGINAL e com garantia. *Após comprar, não esqueça de avaliar nosso produto e nosso atendimento, seu feedback é muito importante para nós, com ele temos como medir onde manter a qualidade e onde melhorar.*', 379.99, 339.99, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me92ojxb3w1t72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F325939221%2F20699759953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
