INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259444012', 'Lacta Intense 70% Cacau Chocolate', 'O novo chocolate Lacta Intense 70% original possui alto teor de cacau sem perder a cremosidade do chocolate Lacta que você já conhece. É uma experiência única no segmento de chocolates amargos. Possui o sabor intenso do cacau combinando com uma maciez irresistível, derretendo lentamente na boca e fazendo cada momento delicioso durar ainda mais. Além de toda a deliciosidade, este chocolate é feito de cacau sustentável, ajudando o meio ambiente. Impossível não se apaixonar! Aproveite e conheça toda a linha de produtos Lacta Intense.', 19.49, 17.53, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-8259a-mqnelcm1mwpabc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58259444012', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29476851029', 'Cubo De Atividades 7 Em 1 Brinquedo Infantil Buba', 'O Cubo de Atividades 7 em 1 da Buba é o brinquedo ideal para estimular o desenvolvimento dos bebês. Com um design colorido e atraente, este classificador é perfeito para crianças de 6 meses a 3 anos, promovendo habilidades motoras essenciais enquanto brincam. Feito de plástico e borracha, o cubo é seguro e durável, permitindo que os pequenos explorem e aprendam de forma divertida. Com dimensões de 17 cm de comprimento, 15 cm de largura e 15 cm de altura, ele é compacto e fácil de manusear para as mãozinhas curiosas. O brinquedo conta com diferentes atividades que mantêm a atenção das crianças, ajudando a desenvolver a coordenação motora e a percepção espacial. Além disso, o som envolvente proporciona uma experiência lúdica que incentiva a interação e a exploração. Ideal para momentos de brincadeira em casa ou em passeios, o Cubo de Atividades Buba é uma excelente escolha para pais que buscam um brinquedo educativo e divertido. Proporcione ao seu filho horas de aprendizado e diversão com este incrível cubo de atividades.', 249.0, 149.0, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rcdv-m6hafdizxm2j82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F29476851029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298063929', 'Açucareiro em Cristal com Bolinhas 200ml - 10x8x7cm Pearl Wolff', 'Açucareiro em Cristal Pearl com Lapidação em Bolinhas - 200ml - Wolff Dê um toque de elegância à sua mesa com o Açucareiro em Cristal Pearl da Wolff, uma peça encantadora que combina sofisticação e praticidade. Com um design refinado e lapidação em bolinhas na borda, este açucareiro é perfeito para quem deseja impressionar ao servir convidados. Ideal para acompanhar chás e cafés, ele se torna um destaque em qualquer ocasião. Características do Produto: Material: Cristal de alta qualidade, com brilho e durabilidade excepcionais. Dimensões: Comprimento: 10 cm Largura: 8 cm Altura: 7 cm Capacidade: 200ml, ideal para armazenar açúcar ou adoçantes. Compatibilidade: Cuidados com o Produto: Lave com detergente neutro e esponja macia. Seque imediatamente após a lavagem para preservar o brilho do cristal. Não use esponjas de aço ou produtos abrasivos. Para realçar o brilho, utilize uma flanela branca com um pouco de álcool. O Açucareiro Pearl da Wolff não é apenas funcional, mas também uma peça decorativa que eleva o charme da sua mesa. Sirva com estilo e transforme suas reuniões em momentos inesquecíveis.', 78.9, 27.9, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7reo3-m2v4j3nnqicn86', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F572649927%2F22298063929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
