INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197373664', 'Boneca Disney Princesas Bela 38cm com Sapatos Removíveis para Crianças a Partir de 3 Anos Multikids - BR2018', 'Junte-se a uma jornada mágica de aventuras e sonhos com a belíssima Boneca Disney Princesa Bela! Essa linda boneca incorpora o espírito de uma Princesa da Disney, inspirando as crianças a acreditarem em si mesmas e perseguirem seus sonhos, encher seu tempo de brincadeira com encantamento! Boneca de 38cm de altura com olhos pintados e sapatos removíveis. Você pode recriar as cenas do filme ou inventar suas próprias histórias mágicas com essa boneca perfeita! Leve Bela para onde você for e crie memórias mágicas juntas Características: - Marca: Multikids - Modelo: BR2018 *Imagens Meramente Ilustrativas* Especificações Técnicas: - Largura do produto: 11.43cm - Altura do produto: 38.1cm - Comprimento do produto: 16.51cm - Peso do produto: 1045g - Cor: Amarelo - Faixa etária: +3 anos - Composição do Material: Plástico, Poliéster - Desenvolvimento: Cognitivo, Motor Conteúdo da Embalagem: - 1x Boneca Disney Princesas Bela Multikids', 220.51, 183.9, NULL, 'Mom & Baby > Toys > Dolls & Stuffed Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rcd3-lsd86xv5rb823b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F23197373664', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398768688', 'Camiseta Infantil Kyly 100% Algodão Básica Lisa 4 à 8 Anos', 'Camiseta Infantil Kyly Lisa Básica 100% Algodão - Tamanhos 4 a 8 Anos Se você procura conforto, qualidade e versatilidade para o dia a dia das crianças, a Camiseta Infantil Kyly é a escolha ideal! ? Produto original Kyly ? Tecido 100% algodão – confortável e respirável ? Modelagem básica e manga curta ? Sem estampa – fácil de combinar com qualquer look ? Ideal para escola, passeios e brincadeiras ? Costuras reforçadas para maior durabilidade Especificações: Marca: Kyly Modelo: Básica lisa Material: 100% algodão Gola redonda (careca) Tamanhos disponíveis: 4, 6 e 8 anos Unissex ?? Dica: Ideal para personalização com silk, sublimação ou patches! ?? Produto novo, pronto para envio imediato! Informações Adicionais: Tamanho: 4 ao 8 Referência: 1082210 4/8 Modelo: Manga curta Detalhes Adicionais: Básica Marca: Kyly Dica: O básico que amamos! Esse modelo nunca sai de moda e pode ser usada muito no verão.', 39.9, 39.9, NULL, 'Baby & Kids Fashion > Boy Clothes > Tops', 'https://cf.shopee.com.br/file/sg-11134201-7rdyp-mcqczapazm373d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23398768688', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23098459996', 'Kit Aspirador Nasal Infantil Com Seringa', 'Aspirador Nasal Infantil Vila Toy Com Bico Extra O Aspirador Nasal Infantil Vila Toy com Seringa é a solução ideal para aliviar a congestão nasal do seu bebê de forma suave e eficaz. Com um design prático e seguro, ele proporciona um cuidado delicado para o nariz sensível dos pequenos, promovendo conforto e alívio imediato. Características • Seringa de sucção manual – fácil de usar, a seringa permite controlar a intensidade da aspiração para garantir que a limpeza nasal seja feita de maneira segura e eficiente. • Bico macio e anatômico – desenvolvido para se ajustar perfeitamente às narinas do bebê, sem causar desconforto ou irritação. • Material atóxico e seguro – feito com materiais livres de BPA e outros componentes prejudiciais, oferecendo total segurança para o bebê. • Design simples e eficiente – permite que os pais utilizem o aspirador com facilidade, mesmo em momentos de apuro. • Fácil de higienizar – a seringa e o bico podem ser facilmente desmontados e lavados, garantindo a higiene adequada após cada uso. • Ideal para resfriados e alergias – ajuda a aliviar a congestão nasal causada por resfriados, alergias e secreções, permitindo uma respiração mais tranquila. Indicação de uso Este aspirador nasal é indicado para recém-nascidos e crianças pequenas, ajudando a limpar as vias nasais de forma segura e eficaz. A sucção controlada pela seringa elimina secreções indesejadas, promovendo o alívio imediato e a sensação de bem-estar no bebê. Informações Adicionais: Tamanho: Único Cores: Branco Referência:2468 Marca: Vila Toy', 25.9, 25.9, NULL, 'Mom & Baby > Baby Healthcare > Nasal Care', 'https://cf.shopee.com.br/file/sg-11134201-7rfha-m9g4w00ivvh1ce', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23098459996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
