INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998728902', 'Chupeta Bebê New Baby Bico Silicone Assimétrico Lisa Fase 2 Rosa', 'Chupeta New Baby Palhacinho Silicone Assimétrico Lisa Fase 2 A Chupeta New Baby é uma escolha inteligente para bebês acima de 6 meses. Com bico de silicone assimétrico e livre de BPA, essa chupeta oferece conforto e segurança durante a sucção. Seu design vazado proporciona uma circulação de ar adequada, promovendo uma experiência de uso mais agradável para o bebê. A chupeta é um acessório de conforto para bebês, oferecendo alívio através da sucção não nutritiva. Disponível em variados designs e materiais seguros, ela pode acalmar e tranquilizar os pequenos em momentos de necessidade. É importante escolher uma chupeta adequada para a idade e observar os hábitos do bebê. Informações Adicionais: Tamanho: Único Cores: Rosa Referência: 111921 Marca: New Baby', 14.9, 14.9, NULL, 'Mom & Baby > Feeding Essentials > Pacifiers', 'https://cf.shopee.com.br/file/sg-11134201-7rdx7-mc9k29f8wq579d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22998728902', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398474677', 'Macacão Bebê KiKo Baby Manga Longa Babados Em Suedine', 'Macacão KiKo Baby Manga Longa Babados Em Suedine Delicado e encantador, o Macacão KiKo Baby com babados e laço é perfeito para deixar o bebê confortável com um toque de charme e elegância.Detalhes do Produto:Confeccionado em suedine macio, ideal para a pele sensível do bebê;Manga longa para maior proteção nos dias frescos;Faixa com babados e aplicação de laço aviamento na parte frontal, garantindo um visual delicado;Gola com acabamento em picueta, que traz um toque clássico à peça;Modelo com pezinhos fechados, que mantêm os pés aquecidos com conforto;Fechamento inferior com botões de pressão, facilitando na hora de vestir e trocar o bebê.Destaques:Design meigo e feminino, ideal para ocasiões especiais ou o dia a dia;Babados e laço que valorizam o visual com sofisticação;Conforto, praticidade e beleza em uma única peça.Informações Adicionais:Tamanho: RN ao P Cores: Rosa/ Vermelho Referência: 13765 Marca: Kiko Baby', 105.99, 105.99, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-7rfhi-m9onvb69qtuxc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23398474677', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
