INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43877849265', 'Boneco Funko Pop! NFL Chiefs - Travis Kelce Candide - 11903', 'Adicione o boneco Funko Pop! Travis Kelce à sua coleção! Com seu uniforme vermelho e branco, o tight end do Kansas City Chiefs está pronto para brilhar no seu time de heróis da NFL. Esta figura de vinil é a escolha perfeita para completar sua coleção de esportes e mostrar seu apoio a um dos maiores jogadores da liga. A figura tem aproximadamente 11 centímetros de altura e é uma excelente adição para fãs do Kansas City Chiefs e da NFL. Os Bonecos Funko POP! proporcionam uma maneira única e encantadora de celebrar sua paixão pela cultura pop. Com sua estética icônica de cabeça grande e corpo pequeno, essas miniaturas de vinil se tornaram um marco no mundo do colecionismo. Com uma ampla variedade de personagens de filmes, séries, videogames e quadrinhos, certamente encontrará algo que ressoe com sua paixão pela cultura pop. Faixa Etária Recomendável: Acima de 3 anos Origem: Importado Composição: Vinil Certificado: INMETRO Dimensões da Embalagem: A:16cm/L:11,5cm/C:9cm Características: - Marca:Candide - Modelo:11903 *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01x Boneco Funko Pop! NFL Chiefs - Travis Kelce', 166.78, 144.9, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mj76gcqzaozmd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F43877849265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
