INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58252996357', 'Coloração 7.1 Louro Médio Acinzentado Select Color Prohall 50g Tom Frio, Brilho Acetinado e Cobertura Total de Fios', 'Coloração de alta performance: brilho, cobertura total e segurança em um só produto A Select Color Louro Medio Acinzentado (7.1) e a coloração permanente da Prohall, criada para entregar tons vibrantes, brilho intenso e resultados duradouros. Sua fórmula avançada combina tecnologia de alta performance e ativos nobres que garantem alto desempenho na fixação dos pigmentos sem danificar os fios. Disponível em mais de 20 tonalidades, a Select Color e a escolha ideal para profissionais que buscam versatilidade, rendimento, qualidade e segurança em cada aplicação. Principais Benefícios Cor intensa, uniforme e duradoura. Cobertura total, inclusive dos fios brancos mais resistentes. Brilho elevado e acabamento luminoso. Pigmentos de alta fixação e estabilidade de cor. Textura cremosa, de fácil aplicação e excelente rendimento. Proteção da fibra capilar durante o processo de coloração. Tecnologias Avançadas Tecnologia Pro System Sistema exclusivo que combina ingredientes em perfeita sinergia, promovendo coloração uniforme, luminosa e de longa duração. Inovação Angstrom Com partículas menores que as da nanotecnologia, os pigmentos aderem profundamente à fibra capilar, garantindo cobertura superior e cor estável, mesmo nos fios brancos mais resistentes. Ativos: Óleos de Argan, Semente de Uva e Macadâmia: proporcionam hidratação profunda, brilho e emoliência, alem de uma textura cremosa que facilita a aplicação. Manteiga de Karite: oferece toque sedoso, maciez e facilidade no desembaraço pós-color. Algas Marinhas e Aloe Vera: protegem e acalmam o couro cabeludo, assegurando conforto durante todo o processo de coloração. Modo de Uso Misture Select Color com o oxidante adequado, seguindo a proporção indicada na embalagem. Aplique nos cabelos secos, distribuindo de maneira uniforme. Aguarde o tempo de ação recomendado para a tonalidade desejada. Enxágue completamente ate retirar 100% do produto. Finalize com tratamento pós-coloração da Prohall Professional. Indicação Indicada para todos os tipos de cabelo, especialmente para quem busca cor intensa, vibrante e com alta durabilidade. Resultados Esperados Coloração fiel e luminosa. Brilho intenso desde a primeira aplicação. Fios macios com toque sedoso.', 27.9, 27.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/br-11134207-820l5-moh84444m1ad0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703142099%2F58252996357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
