INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257052579', 'Glaco Moto – 20ml – 50 viseiras – Repelente de Água de Chuva para Capacete – Soft99', 'Glaco Moto é um produto da marca japonesa Soft99 indicado para repelir água de chuva das viseiras de capacete. > 20ml > Rende até 50 viseiras > Acompanha aplicador de microfibra > Aumenta em até 60% a visibilidade em dias de chuva Instruções de uso: 1) Lave e seque bem a viseira, retirando toda oleosidade e sujeira. Certifique-se de que a viseira está completamente limpa e seca, antes da aplicação; 2) Com a viseira limpa e seca, aplique de 6 a 8 borrifadas sobre a superfície, a uma distância de 10cm; 3) Espalhe com o aplicador que acompanha o frasco, até o produto “sumir”. Não é necessário resolver o excesso ou dar acabamento; 4) Aguarde 5 minutos antes de pegar chuva novamente e reaplique o produto, quando notar perda de repelência. Observação: Glaco Moto também pode ser aplicado em bolhas de acrílico, faróis e retrovisores. Observação 2: NÃO UTILIZAR NO INTERIOR DA VISEIRA E NÃO UTILIZAR EM ÓCULOS. Validade: 5 anos a partir da data de fabricação indicada no frasco. Glaco Moto Soft99. Só confie no original.', 59.9, 29.95, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Helmet Visor Shields', 'https://cf.shopee.com.br/file/br-11134211-820lb-mlxiskg6rqbkc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1449962409%2F58257052579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
