INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698879869', 'Hidratante Corporal Mustela Stelatopia+ Pele Ressecada e Atópica 300ml', 'Hidratante relipidante antiprurido orgânico certificado, acalma eficientemente a pele atópica. Stelatopia+ é formulado especificamente para peles extremamente secas e com tendência atópica dos bebês, desde o nascimento*, E para toda a família. Formulado com 99% de ingredientes de origem natural e com complexo de ingredientes ativos patenteados, o Óleo Destilado de Girassol Orgânico e o prebiótico Bioecolia®. Reduz imediatamente a vermelhidão, e tem efeito antirrecidiva por limitar a frequência de picos graves de ressecamento. Sem perfume. Fórmula vegana.** *Bebês saídos da neonatologia. ** Fórmula vegana: Sem ingredientes de origem animal. Prático, o formato em pump evita o desperdício do produto. Passo 1: Aperte o pump de 2 a 4 vezes. Passo 2: Aplique todos os dias, duas vezes ao dia, na pele limpa e seca. A embalagem está vazia? Essa embalagem de plástico 100% reciclado é reciclável!', 268.4, 268.4, NULL, 'Beauty > Bath & Body Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-824g4-meef6xwjcmivbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F23698879869', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
