INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598894915', 'Kit 3 Fralda Turma da Mônica Baby Tamanho P Pacote Mega 62 Unidades Descartáveis', 'Fralda Descartável Turma da Mônica Baby P - 62 Unidades As fraldas descartáveis Turma da Mônica Baby (Tamanho P) oferecem proteção completa e ajuste superior para o conforto dos pequenos. Com a inovadora tecnologia Qu4troSEC , proporcionam até 12 horas de absorção , garantindo um uso seguro dia e noite. Contam com barreiras antivazamento , que evitam acidentes, e uma cintura elástica ajustável , que se adapta perfeitamente ao corpo do bebê. Com toque macio e distribuição rápida da umidade, elas preservam a pele do bebê seca e saudável. Este pacote contém 62 fraldas , ideal para bebês entre 3 a 5 kg . A escolha perfeita para os pais que buscam qualidade, carinho e a magia infantil da Turma da Mônica!', 158.37, 158.37, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823p0-moobzt2rjwumd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23598894915', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998691868', 'Kit 2 Sabonete Líquido Fiorucci Erva Doce Refil 440ml', 'SABONETE LÍQUIDO FIORUCCI ERVA DOCE O sabonete líquido Fiorucci Erva Doce é enriquecido com extrato de erva doce, que auxilia na hidratação e proteção da epiderme. Possui pH fisiológico, que limpa sem agredir sua pele, proporcionando uma agradável sensação de frescor e maciez. Modo de usar: Aplique o sabonete nas mãos ou em uma esponja úmida, espalhando pelo corpo e massageando em movimentos circulares. Enxague até retirar todo o produto. Pode ser utilizado na banheira, proporcionando uma cremosa e relaxante espuma. Precauções: Uso externo. Não aplicar sobre os olhos ou pele irritada. Em caso de contato com os olhos, enxaguar abundantemente com água. Havendo sinais de irritação, suspenda o uso e procure orientação médica. Manter fora do alcance das crianças.', 19.98, 19.98, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqmfayoefrppc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18998691868', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
