INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697719649', 'Antena Interna Cinoy Radio Automotiva Amplificada p/ Carro Universal de Para-Brisa', 'Antena Interna Universal Cinoy Estilo Vitra Olympus Stetson Rádio Automotiva Tipo Vitra AM e FM A antena interno para carro ou camionete de qualquer modelo universal Cinoy é uma solução compacta e eficiente para melhorar o sinal de rádio dentro do veículo. Com design discreto e instalação simplificada, ela garante recepção de alta qualidade sem comprometer o espaço interno do carro. Ideal para quem busca uma alternativa prática e funcional para fortalecer a recepção de sinais em viagens. Especificação Técnica: - Marca: Cinoy - Modelo: VAIP - Recepção de Sinais AM e FM - Conexão PLUG DIN - Fixação feita por Fita Dupla Face (Já inclusa no produto) - Aplicação Universal - Recepção: AM / FM Instruções de instalação: - Antes de instalar, limpe o vidro com álcool e deixe-o seco; - Retire o papel de proteção do adesivo que fixa a antena; - Tamanho do cabo: 2,6 metros - Largura da antena: 25 cm Conteúdo da Embalagem - 1 Antena Automotiva Cinoy', 24.99, 23.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rdyq-lyuuiheu52e201', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F22697719649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23293004068', 'Pneu Goodyear Aro 18 Wrangler Fortitude HT 235/60R18 103V', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. O Goodyear Wrangler Fortitude HT foi desenvolvido especialmente para a sua SUV. Com desenho otimizado, o modelo tem como característica a versatilidade para oferecer o melhor desempenho tanto no seco, quanto no molhado. A otimização da sua banda de rodagem é capaz de garantir 10% a mais de durabilidade frente ao seu antecessor, além de ser um dos melhores no quesito segurança, uma vez que apresenta evolução em frenagens e aderência em pista molhada. E, de quebra, é amigo do seu bolso. Com 8% a menos de resistência ao rolamento, o pneu proporciona mais economia de combustível para o seu SUV. Sobre a marca Goodyear A marca Goodyear Considerada uma das maiores marcas de pneus no mundo, a Goodyear possui 2 centros de inovação, 48 fábricas e está presente em 22 países. Fundada por por Frank Seiberling em Akron, Ohio (EUA), já últrapassou os 100 anos de existência e hoje em dia conta com mais de 64 mil colaboradores no mundo todo. Investindo constantemente em inovação para fabricar pneus para automóveis, caminhões comerciais e leves, utilitários esportivos, carros de corrida, aviões e máquina agrícolas, é líder de vendas no mercado norte americano.', 1344.32, 1236.78, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Industrial Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd68-lvakkpfwf1brdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F23293004068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254078855', 'Barra de Proteína Cookies com Brigadeiro - 01 Unidade - Everlast Suplementos', 'A Barra de Proteína Everlast sabor Cookies com Brigadeiro é um snack proteico elaborado com matéria-prima importada, desenvolvido para oferecer praticidade, nutrição e sabor no dia a dia. Ideal para diferentes momentos da rotina, é uma alternativa prática para lanches entre as refeições. Cada barra contém 15g de proteínas (30% de proteína). A fórmula possui baixo teor de carboidratos, é zero glúten e não apresenta adição de açúcares, contendo apenas os açúcares naturalmente presentes nos ingredientes. O produto é enriquecido com vitaminas e minerais, além de fornecer 1g de BCAA e 1g de ácido glutâmico, compondo um perfil nutricional equilibrado. A embalagem contém 1 unidade, prática para levar na bolsa, mochila ou lancheira. Benefícios 15g de proteínas por barra (30% de proteína) Baixo teor de carboidratos Zero glúten Sem adição de açúcares Enriquecida com vitaminas e minerais Contém 1g de BCAA Contém 1g de ácido glutâmico Snack prático para o dia a dia Como usar Pronto para consumo. Pode ser ingerida a qualquer momento do dia, como lanche entre as refeições ou conforme a rotina alimentar.', 20.9, 10.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-8260z-mjylh8h50cg3ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F706221503%2F58254078855', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
