INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58263555069', 'Modulo Amplificador Ice X 3002 Banda 3000 Wrms 2 Ohms Novo', '----- MODULO ICE 3002 2 OHMS ----- A Linha ICE foi desenvolvida com tecnologia de ponta, atingindo um nível de qualidade de áudio impressionante, com resposta de frequência de 16Hz a 20kHz. O ICE 3002 oferece 3000 Wrms em 1 canal à 2 Ohms. Possui excelente resposta de frequência, sendo ideal para grandes projetos, podendo ser utilizado em qualquer modelo de alto-falantes, desde Subwoofers até Tweeters. Conta com controle de Bass Boost Variável, chassi 100% alumínio e micro ventiladores com acionamento automático por temperatura. Especificações Técnicas - Potência Máxima 12,6v @ 2 Ohms: 3000 WRMS - Potência Máxima 12,6v @ 4 Ohms: 1700 WRMS - Eficiência @ 2 Ohms: 82% - Tensão de Entrada: 9 - 15V - Impedância de Entrada: 100K Ohms - THD+N: <1% - Sensibilidade de Entrada: 150mV - 8V - Relação Sinal Ruído: 80dB - Resposta em Frequência: 16 a 20kHz (-3dBs) - Bass Boost @ 30 - 80Hz: Variável 0 a +12dBs - HPF (High Pass Filter): 16 a 160Hz @ 12dB/oitava Linkwitz-Riley - LPF (Low Pass Filter): 80 a 20kHz @ 12dB/oitava Linkwitz-Riley - Fusível Recomendado: 150 A - Corrente Máxima (sinal musical): 160 A - Cabos de Alimentação (mín. recomendado): 35mm - Peso (Kg): 3,7 - Altura (mm): 63 - Largura (mm): 225 - Profundidade (mm): 236 - Micro Ventiladores com Sistema de Acionamento por Temperatura - Proteção Térmica - Proteção Contra Curto Circuito - Possui Entrada RCA - Amplificador Classe D Garantia de fábrica: 12 meses', 793.07, 793.07, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mq63y66lbcb0be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1634328463%2F58263555069', NU