INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8538403839', 'Filtro De Cabine Ar Condicionado Marea/brava/wekeend 99 CES 0902', 'Filtro De Cabine Ar Condicionado Fiat Aplicações: Marea / Brava / Wekeend 99 em diante Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lb-mmixg9hmt43kf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F8538403839', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209443146', 'Doritos Ketchup Salgadinho de Milho', 'Doritos sabor Ketchup é a combinação perfeita da crocância e sabor irresistível que você já conhece, agora com um toque de Ketchup que vai te surpreender! Ideal para compartilhar com os amigos, maratonar séries ou para aquele lanche rápido e saboroso a qualquer hora do dia.', 15.99, 15.99, NULL, 'Food & Beverages > Snacks > Chips & Crisps', 'https://cf.shopee.com.br/file/sg-11134201-8259h-mqnem9vbcv7v4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58209443146', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209445700', 'Fanta Laranja Refrigerante Lata', 'Fanta Laranja: o sabor clássico e refrescante que você adora, agora em lata! Perfeito para matar a sede a qualquer hora do dia. Produzido com água gaseificada e suco natural de laranja, Fanta é a opção ideal para compartilhar com amigos e familiares. Refrescância garantida!', 3.79, 3.79, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-82585-mqz7gs4nft3681', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555161%2F58209445700', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20366948724', 'Tira Manchas Vanish em Pó Crystal White Oxi Action para roupas brancas 450g', 'O Tira Manchas Vanish em Pó Crystal White Oxi Action foi desenvolvido especialmente para roupas brancas, proporcionando uma limpeza profunda e eficaz. Sua fórmula com oxigênio ativo penetra nas fibras dos tecidos, removendo manchas difíceis como café, vinho, gordura, molho e suor, mantendo o branco intenso e vibrante por mais tempo. Com 450g, é ideal para uso frequente, oferecendo ótimo rendimento e resultado superior. Indicações de uso: Roupas brancas de algodão, poliéster e tecidos mistos. Remove manchas difíceis sem amarelar ou desgastar o tecido. Modo de usar: Pré-tratamento: Aplique o pó diretamente sobre a mancha úmida. Esfregue suavemente e deixe agir por até 5 minutos. Lave normalmente. De molho: Dissolva 1 colher de sopa cheia (aprox. 20g) em 4 litros de água morna (máximo 40ºC). Deixe as roupas de molho por até 1 hora. Lave normalmente. Na máquina de lavar: Adicione 1 colher de sopa cheia junto ao detergente no compartimento da máquina. Não deixe o produto secar sobre o tecido. Benefícios: Remove manchas difíceis com eficiência comprovada. Mantém o branco intenso e evita o amarelamento. Fórmula segura para uso frequente em roupas brancas. Embalagem prática de 450g para uso regular. Composição: Agentes branqueadores à base de oxigênio, tensoativos, conservantes e fragrância. Precauções: Manter fora do alcance de crianças e animais domésticos. Evitar contato com olhos e pele. Não ingerir. Em caso de contato ou ingestão acidental, procurar atendimento médico e levar a embalagem do produto. Conteúdo: 450g Marca: Vanish Linha: Crystal White Pó para Roupas Brancas', 55.45, 55.45, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m5onjd5rk242e9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F912497596%2F20366948724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198228835', 'Creme de Pentear, Gelatina Explosão de Hialurônico, Óleo de Jojoba e Argan 55ml bn.Cachos', 'O Pentear Explosão de Hialurônico 1 kg promove hidratação profunda com multibenefícios para cabelos cacheados, crespos e ondulados. Ele sela a fibra capilar, tem ação antirressecamento, controle de frizz e proteção. O queridinho dos cuidados com a pele, agora, também cuidando do seu cabelo!_x000D_ _x000D_ A Gelatina Explosão de Hialurônico conta com a tecnologia das nanopartículas do Ácido Hialurônico, que agem dentro do fio promovendo uma hidratação duradoura; além de garantir cabelos macios e com muito brilho! Máxima definição com controle de frizz e efeito antirressecamento para cachos e crespos ainda mais perfeitos!_x000D_ _x000D_ O Explosão de Óleos Argan + JoJoba é ideal para cabelos crespos, cacheados e ondulados. Revitaliza e repara os fios sem pesar, trazendo brilho e saúde para os cabelos. Possui proteção térmica e uma combinação de aromas que deixas os cabelos super perfumados. Dicas de Uso: Revitaliza os fios, restaura o brilho e repara a fibra capilar. O Reparador Explosão de Óleos é multifuncional e ideal para cabelos crespos, cacheados e ondulados. Sua fórmula com ação condicionante protege a fibra dos danos diários e térmicos, sem deixar os fios pesados. Além da combinação de aromas que deixam fios extremamente perfumados.', 122.99, 86.09, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rcew-m6csicmoj3h47e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F22198228835', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
