INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398376025', 'Adesivo Aplique Farol Sandero 2012/2014 Máscara Negra Preto', 'Adesivo Genérico.Máscara Negra torna o seu carro mais esportivo e destacam o seu veículo.Fabricado em Vinil Importado, as películas do farol são resistentes e com um acabamento perfeito. E a instalação é bem fácil. Par de Apliques Farol Sandero 2012 2013 2014 Máscara Negra Adesivo Preto Itens Inclusos:4 Adesivos Películas do Farol / Fabricado em Vinil Transparente / Dimensões: 63,2 x 24,8 cm Quantidade: 4 Adesivos de Farol Observações:Material autocolante.Resistente à chuva e raios UV.Embalagem segura para o transporte.Vinil importado. Instruções Para Aplicação:1 - Limpe e remova qualquer impureza na área de aplicação do produto.2 - Limpe as mãos e remova o protetor do liner.Procure ter o mínimo de contato com a face adesiva.3 - Centralize o produto no local da aplicação. Após esse posicionamento,pressione o produto gradativamente, sempre do centro para as bordas.Procure retirar todas as bolhas.4 - Após finalizar a instalação, não tente retirar a peça para reposicioná-la,pois isso danificará o produto. OBS: Para limpeza e conservação do produto, utilize apenas água e sabão neutro e/ou automotivo.Recomendamos que a aplicação seja feita por um profissional. Garantia de 1 ano.', 49.2, 46.25, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7reo4-m83rwdgfq202b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1466989517%2F22398376025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
