INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998536801', 'Mop Limpa Vidros com Spray Noviça Bettanin', 'Limpar o vidro costuma ser uma tarefa adiada por muitas vezes devido a sua dificuldade, não é mesmo? Com o Mop Limpa Vidros com Spray Noviça Bettanin, esse tipo de tarefa não é mais um problema! Indicado para a limpeza de vidros e espelhos, o utensílio possui sistema de limpeza 3 em 1, com uma inteligente combinação entre reservatório para armazenar água e produtos de limpeza, sistema spray, tecido de alta performance e rodo para finalização.', 59.9, 55.9, NULL, 'Home & Living > Home Care Supplies > Mops', 'https://cf.shopee.com.br/file/sg-11134201-7rfew-m968vi4wydzt0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F21998536801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
