INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094413794', 'Kit 4 Strobo Led Viatura Policia Ambulância Multifunção 12v', 'KIT 4 STROBO MULTIFUNÇÃO 12 VOLTS AUTOMOTIVO VIATURA POLICIA AMBULANCIA VEICULO DE EMERGENCIA REBOQUE. COR: AZUL Descrição Strobo automotivo em LED, com função de luz normal + 16 efeitos de Strobo, alternando as 16 funções com o botão passador de função (Push Button). Efeitos como flash constante, 2 ligam e 2 desligam, flashes aleatórios e diversos outros efeitos com variações de velocidade. -Aplicações: Caminhões uso interno e externo Veículos de segurança Ambulância Som Automotivo Carros corporativos Food Trucks. Especificações: Farol LED Multifunção Linha: Cyber Luz normal + 16 funções Strobo Proteção: IP 65 (resistente a água) Potência: 48W Base: Universal Durabilidade: 8x mais Cor: Branca fria Temperatura da cor: 6000K Quantidade de LEDs: 4 Voltagem: 12V Lente de policarbonato Corpo em alumínio LED em SMD moderno Slim Fit Design (10 mm de espessura) Conteúdo da Embalagem: 04 Farol StroboMultifunção Cyber 04 Acabamento de E.V.A. 08 Parafusos de inox 08 Porcas de inox. APRESENTAÇÃO • Produtos Novos - Disponível a pronta Entrega -Todos os produtos são postados em até 24hs -A SUPERSOM não se responsabiliza pela má instalação. Recomendamos que seja feita por um profissional especializado. - Campo de Perguntas disponível para tirar todas as dúvidas. SEJAM BEM VINDOS E BOAS COMPRAS!', 143.99, 143.99, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-824gz-meq32uvjp2ip8b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819076340%2F23094413794', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
