INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43602992476', 'Brinquedo Infantil Dino Pia e Pesca Rosa com Acessórios Fenix 3+ anos Jogo Interativo', 'O conjunto de brinquedos simulado para pia de cozinha inclui acessórios de cozinha coloridos que podem fornecer jogos práticos de fingir quando crianças em idade pré-escolar lavam pratos e limpam pratos. Este brinquedo de pia está equipado com uma torneira real atualizada e um sistema automático de circulação de água, que ajuda a economizar água e manter uma velocidade constante. Com nesta pia de brinquedo, as crianças podem desempenhar o papel de lavar pratos como mães, satisfazendo assim seu desejo de melhorar as habilidades cognitivas e sociais. ESPECIFICAÇÕES DO PRODUTO: - Dimensões da embalagem : 42cm x 23cm x 8cm - Faixa Etária: +3 - Composição: plástico PP - Com luz e som: não - Alimentação: 02 Pilhas AA (Não inclusas) Características: - Marca:Fênix - Modelo:PLL-943R *Imagens Meramente Ilustrativas* Conteúdo da Embalagem: - 01 Pia Dino - 04 Peixinhos de brinquedo - 01 Vara de Pesca - 01 Rede de Pesca - 08 Comidinhas - 03 Talheres - 02 Xícaras - 02 Copos', 142.99, 124.9, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rats-maip6agqk28gc5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F43602992476', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
