INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499256818', 'V-Light Pro 50ml Vitrificador de Farol Lanterna do Carro Vidro e Para-Brisa Vonixx', 'V-LIGHT PRO 50ML - CERAMIC COATING PARA FARÓIS DESCRIÇÃO: V-Light é um coating de alta performance à base de dióxido de silício, desenvolvido especialmente para recuperar faróis compostos por policarbonato e que sofreram oxidação com o passar do tempo. O produto forma um filme vítreo, semiflexível, de alta transparência e resistência, que suporta dilatações que os faróis de policarbonato sofrem com a variação da temperatura, sem correr risco de trincar ou amarelar novamente com o tempo. DURABILIDADE: Até 1 ano de proteção nos faróis e lanternas TEMPO DE CURA: Parcial: 6 horas Total: 72 horas MODO DE USO: FARÓIS OXIDADOS: 1. Realizar o lixamento dos faróis 2. Descontaminar com Barra Descontaminante e V-Lub e em seguida limpar com Revelax 3. Aplicar uma quantidade generosa de produto em movimentos horizontais usando o aplicador e a microfibra de suede de maneira uniforme 4. Certificar-se do preenchimento de toda a superfície, observando a uniformidade e transparência PROTEÇÃO PARA FARÓIS NOVOS: 1. Descontaminar com Barra Descontaminante e V-Lub em seguida limpar com Revelax 2. Aplicar o produto em pouca quantidade de produto em movimentos horizontais usando o aplicador e a microfibra de suede de maneira uniforme 3. Certificar-se do preenchimento de toda a superfície 4. Realizar acabamento com uma microfibra limpa e seca', 139.77, 139.77, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvg7mwb1nntdb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F20499256818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
