INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12106957666', 'Bandana HUPI - Love Bikes Rosa', 'Bandana A bandana é muito mais do que um acessório do vestuário. É um item indispensável para atividades ao ar livre. Em formato tubular, pode ser utilizada de diversas maneiras: como faixa de cabeça, gorro, gola, máscara, lenço e outras formas. Como a maioria dos capacetes de ciclismo possuem aberturas de ventilação, a bandana auxilia na proteção do couro cabeludo contra queimaduras solares, sujeiras e insetos. Auxilia também a reter o excesso de suor e evita com que escorra para os olhos. Também é muito adequada para proteger em dias frios, sendo utilizada como máscara ou touca, protegendo o rosto e o pescoço, tanto para os ciclistas como para os corredores. * Composição: 91% Poliester | 9% Elastano; * Tamanho: 24cm X 42cm; * Super leve e respirável; * Fácil lavagem e secagem; * Tamanho único. Peso das Bandanas: Com embalagem 63 gramas | Sem embalagem 32 gramas. Confira em nosso site mais itens que combinam com a bandana como, meias, viseiras, manguitos, luvas...', 55.68, 37.9, NULL, 'Fashion Accessories > Hair Accessories > Headbands', 'https://cf.shopee.com.br/file/fe33f73e1ddb0e52182d77d66ed1c5c2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F12106957666', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993958358', 'Jogo de chave allen 1,5 a 10 mm com 9 peças 42-9M - Gedore', 'Produto: Jogo de chave allen 1,5 a 10 mm com 9 peças - 42-9M Marca: Gedore Descrição: O Jogo de Chave Allen da Gedore é a solução ideal para apertar e soltar parafusos com perfeição e segurança. Este jogo contém 9 peças variando de 1,5 a 10 mm, feitas em Aço Gedore-Vanadium de alta qualidade, conhecido por sua durabilidade e resistência Ã corrosão. O acabamento escurecido não só protege o material como também confere um design elegante e discreto. Características: • Material Robusto: Aço Gedore-Vanadio para maior durabilidade. • Acabamento Escurecido: Aumenta a resistência contra a corrosão. • Perfil do Corpo em L: facilita o efeito de alavanca, otimizando o aperto e desaperto de parafusos. • Design Compacto: Ideal para espaços confinados. Ao escolher o Jogo de Chave Allen da Gedore, você não apenas compra um produto, mas um companheiro confiável para todas as suas necessidades de montagem e desmontagem. Seja em ambiente profissional ou doméstico, este conjunto é a escolha perfeita para garantir que todos os trabalhos sejam feitos com precisão e eficácia. Especificações: Medidas das chaves: 1,5 a 10 mm Material da chave: Aço Gedore-Vanádio Acabamento: Escurecido Referencia: 42. Itens Inclusos: 9 chaves allen: 1,5; 2; 2,5; 3; 4; 5; 6; 8; 10 mm. Dimensões (C x L x A): 21.30 x 9.50 x 5.90 centímetros Peso: 0.28 Kg', 68.7, 59.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259d-mqyx8eqxjb41dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F22993958358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
