INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14132875117', 'Protetor de coluna garagem estacionamento zebrado Simplefix', 'Produto: Protetor de coluna para garagem 100 x 5 cm x 10 mm em EVA Marca: Simplefix Descrição: Proteja seu carro com estilo e segurança com o Protetor de coluna para garagem 100 x 5 cm x 10 mm em EVA da Simplefix. Ideal para manobras em garagens ou estacionamentos, este protetor de alta qualidade evita riscos e amassados em sua lataria, mantendo seu veículo sempre novo. Feito com material de alta densidade em EVA, e com dimensões de 100 cm de comprimento, 5 cm de largura e 10 mm de espessura, o protetor oferece cobertura ampla e eficiente. Além disso, seu design zebrado em amarelo e preto não só adiciona um toque moderno Ã sua garagem mas também aumenta a visibilidade, reduzindo o risco de colisões. Características: • Material Durável: Fabricado em EVA de alta qualidade, resistente a impactos e de longa duração; • Facilidade de Instalação: Produto autoadesivo, fácil de aplicar e perfeito para uso imediato; • Design Atrativo: Estampado em cores vibrantes de amarelo e preto, proporcionando maior segurança através de melhor visibilidade; • Proteção Ampliada: Com medidas generosas, garante a proteção total da região mais suscetível a danos durante as manobras. Especificações: Material: E.V.A Comprimento: 100 cm Lateral: 5 cm Epessura: 10 mm. Peso: 0.21 Kg', 58.14, 58.14, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a8-mr4j1d2vv4li20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F14132875117', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
