INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20957608099', 'Colchão Airtech Spring Pocket Viúva (128x188x30) - Molas Superpocket, EPS, D26 Pró - Airtech', 'O Colchão Airtech Spring Pocket Viúva (128x188x30) - Molas Superpocket, EPS, D26 Pró - Airtech tem sua estrutura composta por Molas Superpocket ensacadas individualmente, que fazem o peso de um corpo não interferir no conforto do outro, proporcionando um perfeito suporte para a coluna e conforto para qualquer biótipo, possui Ortopillow e em sua camada de conforto espuma D26 Pró Aditivada de Alta Performance, bordado em matelassê e placa EPS. Seu tampo é em malha de alta qualidade e lateral em Camuça, apresentando um toque refinado ao colchão. Possui a tecnologia No Turn, que dispensa a necessidade de virar o colchão. O Airtech Spring Pocket recebe tratamento antialérgico e antiácaro, ajudando a reduzir os problemas respiratórios. Ideal para suas confortáveis noites de sono. Características: Estrutura em molas Superpocket (ensacadas individualmente), placa EPS, Ortopillow, tampo em malha, bordado em Matelassê, manta de espuma D26 Pró, faixa lateral em Camurça, No Turn (não precisa virar), tratamento antialérgico e antiácaro. Informações Técnicas: - Estrutura Interna: Molas Superpocket, placa EPS, Espuma D26 Pró de Alta Performance. - Estrutura Externa: Tampo em Malha e feixa lateral em Camurça - Cor: Branco e Bege - Altura: 30cm | Largura: 128cm | Profundidade: 188cm - Suporta até 120kg por pessoa - Conteúdo da Embalagem: 1 Colchão Ortobom + Manual.', 1799.9, 1499.99, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-22100-a4lzgkzz34iv37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F20957608099', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17288439374', 'Gabinete Banheiro 2 Portas Retrô 63cm Multimóveis MP5006 Branco/Preto', 'O Gabinete Banheiro 2 Portas Retrô 63cm Multimóveis é produzido em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade, facilidade na limpeza, além de um acabamento superior. Com 2 portas, possui um excelente espaço interno para organizar itens de higiene, toalhas e demais objetos (a prateleira interna suporta 8 Kg e o tampo 9 Kg). Os pés retrô, em polipropileno, dão um charme especial ao móvel deixando-o com um visual leve e permitindo você compor um ambiente com ar vintage e moderno ao mesmo tempo. Uma ótima opção para deixar seu banheiro bonito, prático e organizado. Não acompanha torneira e cuba. Conteúdo da Embalagem: 1 (um) balcão 1 (um) kit com 4 pés retrô Dimensões do produto montado: Altura: 85cm | Largura: 63cm | Profundidade: 32cm *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 359.99, 239.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-22100-7f6b9ix624ivad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F17288439374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
