INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898513272', 'Faqueiro Talheres Leme Inox 40 Peças Tramontina Azul', 'Faqueiro Talheres Leme Inox 40 Peças Tramontina Cores Deixe sua mesa muito mais bonita e cheia de estilo com o faqueiro Tramontina Leme com lâminas em aço inox e cabos de polipropileno 40 peças! Perfeito para uso diário, ele tem peças produzidas com lâminas em aço inox com resistência e durabilidade devido ao tratamento térmico e a espessura. Os cabos são em polipropileno e proporcionam um manuseio superconfortável, além de deixar a composição da sua mesa muito mais elegante, devido a cor cinza. O faqueiro ainda é muito fácil de limpar e poder ser levado à máquina de lavar louças, facilitando suas tarefas na cozinha. Com a Tramontina, você tem os melhores talheres para sua casa! Descrição do produto Contém: 8 facas para churrasco, 8 garfos de mesa, 8 colheres de mesa, 8 garfos de sobremesa e 8 colheres para chá Marca: Tramontina Quantidade de Peças: 40 Serviço: Até 8 pessoas Linha Comercial: Faqueiros e Talheres Leme Material Cabo: Polipropileno Material Lâmina: Aço inox Altura: 25cm Largura: 10 cm Comprimento: 10cm Peso: 600g Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 183.5, 139.63, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7qve5-lgpdwdclzjefa3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F18898513272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
