INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997169057', 'Par Palheta Limpador Parabrisa 20'''' 15'''' Nissan Versa 2011 á 2019', 'Par Palheta Limpador Parabrisa 20'''' 15'''' Nissan Versa 2011 á 2019 DESCRIÇÃO DO PRODUTO Essencial para os dias de chuva, a palheta do seu automóvel deve estar em boas condições para limpar perfeitamente seu parabrisa, ajudando a ter uma visibilidade melhor e assim evitando acidentes. ESPECIFICAÇÕES DO PRODUTO: - Haste em Plástico Semirrigido - Fita de Borracha - Evita Riscos No Vidro - Menos Ruídos - Fácil de Instalar Compatível com: - Versa 2011 - Versa 2012 - Versa 2013 - Versa 2014 - Versa 2015 - Versa 2016 - Versa 2017 - Versa 2018 - Versa 2019 Especificação Técnica: Medidas Palheta Dianteira: • 20 Polegadas 510MM (Encaixe Gancho) • 15 Polegadas 375MM (Encaixe Gancho) OBS.: É recomendável a troca de palhetas do seu automóvel a cada 6 meses. O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: • 01 Palheta Dianteira 20" • 01 Palheta Dianteira 15" FINALIZAÇÃO Todos os nossos produtos possuem procedência e credenciamento no DETRAN. A imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 29.9, 20.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rbkl-lov6dl7bs5glbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F22997169057', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
