INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260265580', 'Linguiça de pernil Seara 600g', 'A Linguiça de Pernil Seara combina suculência e um sabor autêntico de comida caseira em uma receita cheia de tradição. Elaborada com cortes selecionados de pernil, é perfeita para o churrasco, para o feijão ou para dar um toque especial às receitas do dia a dia. Um sabor nobre e familiar que agrada a toda a família.', 23.99, 23.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Meat', 'https://cf.shopee.com.br/file/sg-11134201-824hf-mptnglzlbbia67', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58260265580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399249836', 'Leave-In Elseve Reparação Total 5 Cicatri Renov 100ml', 'O Leave-In Cicatri Renov Elseve Reparação Total 5 identifica e repara os danos fio a fio do cabelo sem pesar. Ele trata os fios instantaneamente sem pesar. Possui 10 benefícios para uma plástica capilar: reparação instantânea; selagem das pontas; 100% mais brilho; maciez profunda; toque deslizante; desembaraço imediato; 10x menos quebra; anti-frizz; anti-umidade e proteção térmica. Para todos os tipos de cabelo, renova e protege a qualquer hora e em qualquer lugar. Pode ser usado com o cabelo seco ou molhado, antes ou depois do secador.', 57.33, 57.33, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lv0c3apg97z19d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689225278%2F19399249836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22497778424', 'Moldura Painel Velocimetro Gol Voyage Parati Saveiro 1988 a 1994 CL', '**Leia com ATENÇÃO todas as informações do anúncio e compre somente na certeza. Verifique o modelo, ano, ou qualquer dúvida nos contate no campo de perguntas antes de finalizar a compra. O custo por eventual devolução será por conta do comprador! ** Produto 1ª Linha (NÃO É ORIGINAL) -DESCRIÇÃO: Moldura Painel Velocímetro Preto -COMPATÍVEL: Volkswagen - Gol/ Voyage / Parati / Saveiro CL 1988 a 1994 -ITENS INCLUSOS: 01 - Moldura Painel Velocímetro -ESPECIFICAÇÕES TÉCNICAS: Cor: Preta Alta Durabilidade Aplicação: Interna Ultra Resistente Material: Plástico Excelente Acabamento -OBSERVAÇÕES: * Anúncio referente a UNIDADE! * Recomendamos que os produtos sejam instalados por profissionais especializados. * Não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. * Imagem meramente ilustrativa. * Atenção: Não Permitimos a utilização de nossas fotos e/ou vídeos a terceiros. * Não vendemos para PESSOA JURÍDICA fora do ESTADO DE SÃO PAULO. *Caro Cliente! Caso precise devolver o produto, independente do motivo, se atente ao prazo oferecido pela Plataforma. Não encerre por conta própria seu pedido de devolução até que o mesmo se resolva! Após o vencimento/encerramento, não poderá mais usufruir dessa cortesia e os custos serão por sua conta.', 34.59, 30.1, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdvs-m04lktpoxtmx87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F22497778424', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52111098419', 'Camisa Brasil Canarinho Feminina 10 Neymar Jr', 'NEYMAR JR Neymar Jr. é um gênio do futebol moderno. Com dribles inebriantes, criatividade sem limites e uma visão de jogo privilegiada, ele transforma o campo em palco. Sua habilidade em desequilibrar adversários e marcar gols decisivos faz dele um dos maiores talentos da geração! Composição: 100% Poliéster Cor predominante: Amarelo Indicado para: Casual Gênero: Feminino Origem: Importada Seleção: Brasil Escudo: Aplicado Manga: Curta Gola: Careca Modelagem: Regular Dimensões aproximadas (A x L): P: 62 x 46 cm M: 65 x 47 cm G: 67 x 50 cm GG: 69 x 52 cm', 124.9, 124.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Jerseys', 'https://cf.shopee.com.br/file/sg-11134201-823qs-monyu68kagwbf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F52111098419', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256409581', 'Guarda-Roupa Casal Bartira Village com 3 Portas 4 Gavetas e 243,1cm', 'O Guarda-Roupa Village da Bartira é uma excelente escolha para o casal que busca uma solução prática e elegante para organizar roupas e acessórios em um ambiente. Ele oferece versatilidade na hora de compor a decoração do quarto, pois se adapta facilmente a diferentes estilos de decoração, permitindo que você crie um ambiente harmonioso e personalizado. Com 3 portas de correr, o armário Village otimiza o espaço disponível no quarto, já que não requer espaço adicional para abrir as portas. Além disso, suas 4 gavetas oferecem espaço extra para guardar itens menores, como acessórios e peças íntimas. Dessa forma, você pode manter tudo organizado e ao alcance das mãos, facilitando o dia a dia. A qualidade do armário Village também merece destaque. Fabricado pela Bartira, uma marca reconhecida por sua excelência em móveis, esse armário é feito com materiais resistentes e duráveis, 100 em MDP 15mm com acabamento em FF (Finish Foil), garantindo sua longevidade. Suas portas deslizantes possuem trilhos suaves, o que torna seu uso ainda mais prático e silencioso. Guarda-Roupa Casal modelo Village da Bartira é a união perfeita de qualidade, beleza e otimização de espaço! Características Gerais: 3 Portas de correr (1 porta ripada e 2 portas lisas) 4 Gavetas internas Corrediças telescópicas 2 Cabideiros em alumínio Trilhos: Superior em plástico e inferior em alumínio Produzido 100 em MDP 15mm Acabamento: Em 100 Finish Foil Cabideiro: sim Tipo de porta: Correr Puxador: Embutido Quantidade de gavetas: 4 Gavetas Quantidade de gavetas: 4 Quantidade de portas: 3 Dificuldade de Montagem: Média Conteúdo da Embalagem: Guarda-Roupa Casal Bartira Village com 3 Portas, 4 Gavetas e 243,1cm Dimensões (AxLxP): Medidas internas das gavetas: 11 x 66,8 x 40,8 cm Medidas internas das prateleiras: 75,7 x 44,6 x 1,5 cm Guarda Roupa Montado: 230,1 x 243,1 x 55,31 cm Garantia do Fornecedor: 6 meses Atenção: Não nos responsabilizamos pela montagem ou instalação do produto, Foto meramente ilustrativa Dificuldade de Montagem: Média Observações: Item composto APENAS pelo Guarda-Roupa Casal Bartira Village com 3 Portas, 4 Gavetas e 243,1 cm de Largura. Demais objetos presentes na imagem são meramente ilustrativos e não compõem a oferta. Entrega do Produto: Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto, não nos responsabilizamos pela instalação/montagem, orientamos que este produto seja montado por um técnico de sua confiança, após a sua entrega, Não nos responsabilizamos pelo transporte por escadas/elevadores, guincho ou içamento deste produto', 1935.79, 1839.01, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/sg-11134201-8260y-mlhuxc91gav9f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58256409581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294921649', 'Panela Elétrica de Arroz Philco PH5 Visor Glass 5 Xícaras', 'Tenha mais praticidade e facilidade ao preparar seus alimentos com a panela elétrica de arroz philco ph5 visor glass! Com uma capacidade para cozinhar até 5 xícaras de arroz, a panela elétrica de arroz philco ph5 visor glass proporciona também praticidade na hora de refogar alimentos e até cozinhar legumes e verduras no vapor ao mesmo tempo em que cozinha o arroz, garantindo menos tempo no preparo das suas refeições. A panela elétrica de arroz philco ph5 visor glass vem acompanhada de bandeja perfurada que permite o cozimento de legumes e verduras no vapor e um copo medidor para o preparo das refeições na medida certa, além de coletor de água que evita o acúmulo de água na tampa da panela. Muito segura, possui um sistema de desligamento automático e pode ativar a função manter aquecido, evitando que queime os alimentos, tampa vedada com alça, saída de vapor e botão de travamento, além de tigela antiaderente, que facilita a limpeza após o uso. O cordão de energia é removível, permitindo que você sirva os alimentos onde quiser. Mais praticidade no seu dia a dia com a panela elétrica de arroz philco ph5 visor glass! Características Gerais: Antiaquecimento externo: Sim Lâmpada piloto: Sim Porta-fio: Não Desligamento automático: sim Consumo de energia (kW/h): 0,4 Kw/h Temperatura máxima (C): Não especificado Capacidade (litros): Não especificado Potência (W): 400w Capacidade de alimentos (g): 5 Xícaras Tensão/Voltagem: 110V|220V Cor: Inox|Preto Tipo de Tomada: 20A (4.8mm) Tipo de Plugue: 3 Pinos Conteúdo da Embalagem: 1 Panela Elétrica de Arroz Philco PH5 Visor Glass 5 Xícaras Manual de Instruções Dimensões: Altura: 26cm Largura: 24cm Comprimento: 24cm Garantia: 12 meses Observações: Devido às normas da ABNT e às resoluções n 13 de 2006, n 2 de 2007 e n 8 de 2009 do CONMETRO Acompanha bandeja para cozimento a vapor, copo medidor e coletor de água. Dicas de Utilização: Utilize o copo medidor para adicionar a quantidade correta de água e arroz. Para cozinhar legumes no', 160.55, 160.55, NULL, 'Home Appliances > Kitchen Appliances > Rice Cookers', 'https://cf.shopee.com.br/file/sg-11134201-82633-mm8x09797h8h6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F23294921649', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
