INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497748077', 'Hover Ball Bola Flutuante Do Flamengo De Futebol - Zoop Toys', 'O Hover Ball é um brinquedo incrível e inovador que proporciona diversão e entretenimento para crianças e adultos. Este brinquedo é uma bola flutuante que utiliza uma tecnologia para criar uma camada de ar abaixo dela, permitindo que ela flutue suavemente sobre o chão. Em qualquer superfície lisa e plana dentro de casa ou em um ginásio e torne um novo espaço emocionante para toda a criançada. Luzes piscando tornam o jogo mais divertido, emocionante e cativante! Para garantir a segurança durante a brincadeira, o Hover Ball possui laterais revestidas com espuma macia. Essa proteção de espuma absorve impactos, minimizando a chance de danos aos móveis, paredes ou pessoas durante o jogo. Isso permite que as crianças brinquem de forma segura e sem preocupações. Especificações: Marca: Zoop Toys Referência: FLA0002 Cód. Barras: 7899788408701 Idade recomendada 3+ anos. Funciona a bateria ou pilha? 4 Pilhas AA Alimentação:(Não inclusas) Dimensões do Produto na Embalagem: 20 x 19 x 7 cm Peso: 221 g Certificado Inmetro: 005719/2019 Garantia do Fabricante: 3 meses Garantia do Vendedor: 7 dias Produto Novo, Original, Lacrado e Acompanhado de Nota Fiscal.', 68.99, 68.99, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lwww0ao1pu2e7a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F20497748077', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
