INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099588900', 'Camisa Camiseta Agro Proteção UV Pecuária Boi Brasil Blusa Manga Longa', 'CAMISA AGRO MANGA LONGA PROTEÇÃO - Proteção Solar – Tecido com fator de proteção solar (FPS) para bloquear raios UV, mantendo você seguro ao ar livre. - Cobertura Completa – Manga longa que protege contra sol, arranhões e insetos. - Conforto e Frescor – Material leve, respirável e perfeito para dias quentes. - Design Exclusivo – Estampas temáticas de agropecuária, como animais de fazenda e ferramentas agrícolas. - Versatilidade – Ideal para trabalho no campo, eventos agropecuários, trilhas ou uso diário. Sobre a Loja • Especializada em artigos para ciclistas, com produtos de qualidade e preços justos. • Apenas produtos à pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h, e sexta, das 8h às 17h. A camisa perfeita para quem vive o campo. Garanta a sua!', 99.9, 45.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4rw7i808gu9f1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F19099588900', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
