INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17188362214', 'Bieleta Estabilizadora Onix 2012/2019 Dianteiro Le Ld Nakata', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação As bieletas são hastes que ligam a barra estabilizadora à Suspensão do veículo, proporcionando melhor dirigibilidade e maior estabilidade ao veículo. Barulhos e instabilidade na Suspensão é um sinal de problemas nas bieletas. Para garantir total eficiência da Suspensão, a recomendação é realizar as revisões periódicas das bieletas do seu carro e dos demais itens da Suspensão, e quando constatado defeitos nas peças, a substituição deverá ser realizada imediatamente. Conteúdo Da Embalagem 1 Bieleta Tipo de Veículo para Carros Marca Há mais de 65 anos a Nakata é uma das líderes de seu segmento, comprometida 100% com o mercado de reposição e com a missão de oferecer e garantir soluções competitivas para a reparação de veículos. A Nakata mantém uma a qualidade excepcional de suas autopeças e oferece uma linha completa para freios, suspensão, motor e transmissão, liderando o mercado nas linhas de juntas homocinéticas e pivôs de suspensão. Importante Recomendamos que os produtos sejam instalados por profissionais especializados e não nos responsabilizamos pelo mau uso ou instalação indevida, causando a perda da garantia. Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades. Tempo de garantia: 12 Meses Valor unitário Imagem meramente ilustrativa Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078 EAN 7890903046365 Código do Fabricante N93036 Posição Dianteiro Posição Dianteiro', 44.5, 44.5, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-7r9a5-llud8xc0y2jd76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F17188362214', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
