INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15249324579', 'Sonhe | Descubra o Propósito de Deus para a sua Vida | Dutch Sheets', 'VOCÊ FOI PROJETADO PARA SONHARO que aconteceu conosco? Por que tantas pessoas estão decepcionadas com a vida? Um dia tivemos sonhos — sonhos importantes que nos davam um propósito — mas, de algum modo, saímos dos trilhos. Com certeza não é isso que Deus quer para nós.O nosso Projetista sonhou sonhos únicos para cada um de nós antes mesmo de nascermos. Ele os teceu habilmente dentro do nosso DNA, juntamente com os dons e as habilidades necessários para realizá-los. No entanto, aqui estamos nós, correndo atrás do aplauso terreno quando poderíamos estarexperimentando a aprovação do Céu.Se você quer ter certeza de que conhece a vontade de Deus, se quer que cada dia valha a pena, embarque nesta jornada com Dutch Sheets enquanto ele compartilha conosco lições emocionantes sobre os sonhadores da Bíblia e os sonhadores de hoje, que sonham os sonhos de Deus.Quando ouvir o chamado de Deus para a sua vida, você nunca mais será o mesmo!', 42.95, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/99593eaa9f236a6dd5924cd62d3beec9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15249324579', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
