INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993553546', 'Correia Basso Basica Ny-01 Sintético Sound7 Marrom e Preto', 'A Correia Basso Básica NY-01 d Sound7 é a escolha perfeita para os músicos que buscam conforto e estilo. Feita de couro sintético de alta qualidade, esta correia é ajustável e tem um comprimento de 1,5 metros, tornando-a adequada para baixos e violões de todos os tamanhos. Com uma largura de 5 cm, ela é projetada para distribuir o peso do instrumento de maneira uniforme, reduzindo a tensão no ombro e no pescoço durante as performances. A cor preta e marrom clássico e o design elegante da Correia Basso Básica NY-01 complementam qualquer instrumento, adicionando um toque de sofisticação ao seu visual no palco. Escolha a Correia Basso Básica NY-01 da Sound7 e experimente a diferença que uma correia de qualidade pode fazer.', 28.07, 28.07, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rfh8-m3c3pe6ku4zsb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F23993553546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
