INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21861876411', 'Filtro Óleo Fiat Stilo Attractive 1.8 8v 2010 A 2011 Tecfil', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. Aplicação STILO 1.8 ATTRACTIVE FLEX 8V 5P 2010 até 2011 STILO DUOLOGIC 1.8 ATTRACTIVE FLEX 8V 5P 2010 até 2011 Conteúdo Da Embalagem 1 Filtro de Óleo Tipo de Veículo para Carros Marca Especialista no segmento de Filtros Automotivos a Tecfil foi fundada em 1953, e atualmente é a maior fábrica de filtros da América Latina, além de ser a líder e maior referência do mercado no segmento de reposição automotiva. A empresa possui ainda todas as Certificações exigidas no mercado, o que lhe confere diferenciais de qualidade. O Produto Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o Filtro de Óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor podendo causar até a fundição do mesmo. Importante • Tempo de garantia - 3 meses. • Imagem meramente ilustrativa. • Valor Unitário. • Prazo de troca e devolução: 7 dias a partir do recebimento do produto - Lei nº 8.078. EAN 7891342000192 Código do Fabricante PSL619 Combustível Flex Gasolina Combustível Flex Gasolina >', 12.54, 12.54, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbk3-lltc0gmasyyt8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F21861876411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
