INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599249876', 'Kit Bloco De Montar Banco 105 Peças Peiz Building Series Colorido P/ Lembrancinha Aniversario Prenda', 'ITEM ANUNCIADO: BLOCO CIDADE DE MONTAR COM 105 PEÇAS COLECIONE!!!! ***CADA EDIFICIO CONECTA UM AO OUTRO, VOCE PODE MONTAR SUA CIDADE, CONECTANDO UM AO OUTRO...*** O Bloco de Montar Peiz Building Series Colorido é um brinquedo infantil perfeito para crianças a partir de 3 anos. Com 105 peças de montar, ele estimula a criatividade e a coordenação motora dos pequenos. Feito de plástico resistente, é seguro e durável para garantir horas de diversão. Com formas variadas, as peças podem ser combinadas de diferentes maneiras, permitindo que a imaginação das crianças voe longe. O Bloco de Montar Peiz é uma ótima opção de presente educativo. Beneficios: Estimula a criatividade e a imaginação. Otimo para desenvolver habilidades motoras e cognitivas. Perfeito para crianças e entusiastas de todas as idades. Características: Cores: Sortidas e unissex, podendo ser para menino ou menina Material: Plástico. Tamanho aprox. montado: 6cm x 10cm EMBALAGEM CONTÉM: 01 Brinquedo Blocos de Montar Banco Garantia do vendedor: 90 dias QUALQUER DÚVIDA ESTAMOS A DISPOSIÇÃO! Bolinha Mágica, pequeno presente, GRANDE ALEGRIA!!', 34.7, 23.99, NULL, 'Mom & Baby > Toys > Block Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4yrnjk3vg40e2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F19599249876', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
