INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19898132148', 'Bar End Chifre Bike Absolute Ergonomic 126mm - Preto Confort', 'BAR END ABSOLUTE ERGONOMIC 126MM - PRETO Descrição: O BAR END é uma solução de conforto para o ciclista durante as longas pedaladas. Garante uma pegada que alivia a tensão. O BAR END ABSOLUTE tem o corpo em alumínio e finalização emborrachada (mais aderência). Possui comprimento de apoio para as mãos de 126mm. Para instalação, o BAR END é fixo em guidão de bike padrão de 22mm de diâmetro e ocupa 18mm da extremidades do comprimento do guidão. Acompanha parafuso Allen de 5mm. A instalação deve ser feita com uso de ferramentas apropriadas e deve respeitar o torque de aperto recomendado pelo fabricante do guidão. Produto de excelente qualidade e acabamento. Proporciona conforto e segurança na pedalada. Especificações: - Marca: ABSOLUTE; - Modalidade: MTB e Urbano; - Cor: PRETO; - Material: Corpo – ALUMÍNIO, Acabamento - EMBORRACHADO; - Design Ergonômico; - Comprimento: 126mm – CURTO; - Diâmetro do Guidão: 22mm; - Profundidade de montagem no Guidão: 18mm; - Peso aproximado: 150g – PAR; - Part Number: 51542; - Cód. Barras: 6970284415316.', 32.0, 32.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfht-m9dvkcasr15z6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F19898132148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58260133901', 'Cream Cheese Philadelphia', 'O cream cheese Philadelphia é perfeito para o café da manhã, lanches rápidos ou receitas especiais. Sua textura cremosa e sabor suave o tornam um ingrediente versátil para diversas preparações, desde torradas e bagels até cheesecakes e molhos. Experimente o Philadelphia em suas receitas favoritas e descubra um mundo de possibilidades culinárias!', 15.49, 15.49, NULL, 'Food & Beverages > Dairy & Eggs > Others', 'https://cf.shopee.com.br/file/sg-11134201-8257u-mqnem07otdz48c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58260133901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897173937', 'Kit Eico Pro Máscara Cronograma Capilar Hidratação Nutrição e Reconstrução Spray Protetor Térmico', 'Contém: 01 Tratamento Máscara Óleo Sublime 300g 01 Tratamento Máscara Força & Crescimento 300g 01 Tratamento Máscara Obrigatório 300g 01 Spray Eico Pro Finalizador Protetor Térmico 200ml (DA SUA ESCOLHA) Sem Sal, Sem Parabenos, Sem Petrolatos, Sem Corante - Linha Liberada A linha Óleo Sublime Eico Professional foi desenvolvida para aqueles cabelos quimicamente tratados e cabelos naturais, ótima nutrição para cabelos que estão sem vida, ressecados e sem brilho. Ativos: Pro Elixir Complex, Óleo de Argan, Marula e Abacate A linha Tratamento Obrigatório Eico Professional foi desenvolvida para aqueles cabelos quimicamente tratados, danificados, quebradiços, rebeldes e porosos. Reconstrução perfeita para quem procura a recuperação da fibra capilar. Ativos: Caviar Verde e Ácido Hialurônico A linha Tratamento Força&Crescimento Eico Professional foi desenvolvida para aqueles cabelos com queda, enfraquecidos e quebradiços. Tratamento eficaz combatendo a queda fortalecendo da raiz até as pontas e estimulando muito o crescimento deixando seus cabelos cumpridos e fortes. Ativos: Biotina, Giseng, Pantenol e ProForce Complex Tratamento: Após lavar o cabelo com o shampoo EICO PROFESSIONAL 300g. Enxágue completamente, retire o excesso de água com uma tolha. Aplique uma pequena quantidade do tratamento EICO sobre a palma das mãos e massageie suavemente por toda a extensão dos fios evitando a raiz. Enluve mecha por mecha e deixe agir por 10 minutos. Enxágue completamente. Utilize o tratamento ao menos uma vez por semana. Para um melhor resultado utilize a linha completa de tratamento EICO. O Fluido 0% Frizz possui ação ultra disciplinante, controla o volume e é ideal para um liso imediato com até 5X menos frizz.Este produto possui proteção térmica até 230°C, ele protege os fios sob altas temperaturas como as de secador e chapinha. Filtro UV: Protege contra os danos da luz solar. Produto Vegano Não testado em animais', 189.9, 179.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdwm-lzqexj2x4ydi5e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385344228%2F23897173937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
