INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21296932304', 'Kit 2 Varal de Chão Retrátil Slim Preto Mor', 'Kit 2 Varal de Chão Retrátil Slim Preto Mor O Varal de Chão Slim da Mor é a maneira mais barata e ecológica para secar suas roupas. Prático e funcional é perfeito para quem não tem muito espaço em casa ou apartamentos. Pode ser carregado facilmente para onde você preferir e quando não estiver utilizando, basta dobrá-lo e guardar em qualquer cantinho. Sua estrutura foi desenvolvida em tubo de aço com acabamento em pintura epóxi a pó branca. Possui sete varetas com capacidade para até 5,2m de roupa ou 16Kg distribuídos. Suas peças plásticas são de polipropileno, incluindo as ponteiras em seus pés que ajudam a proteger o piso. Com o Varal de Chão Slim as tarefas do dia a dia ficarão muito mais simples. Descrição do produto Composição: 02 varal 6125 Marca: Mor Material: Aço pintado Altura: 79 cm Largura: 42 cm Comprimento: 79 cm Peso: 1,62 kg Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 199.83, 138.53, NULL, 'Home & Living > Home Care Supplies > Clotheslines & Drying Racks', 'https://cf.shopee.com.br/file/sg-11134201-7qvco-lgo467c6rjac52', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F21296932304', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
