INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899091446', 'Kit 3 Fralda Roupinha Huggies Natural Care Tamanho XXG Pacote Mega 20 Unidades Descartáveis', 'Fralda Pants Premium Huggies Natural Care Tamanho XXG A Fralda Pants Premium Huggies Natural Care Tamanho XXG com 20 unidades combina conforto, cuidado com a pele e praticidade. Além de possuir óleo de amêndoas e aloe vera, ela ajuda a prevenir irritações na pele do bebê. O formato estilo roupinha facilita na hora de vestir e acompanhar os movimentos do bebê. Além disso, é dermatologicamente testada e ajuda a cuidar da pele do bebê, mantendo-a fresquinha Produto sem propriedade cosmética nem ação terapêutica.', 143.97, 143.97, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-823op-moobzdduzggf23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F18899091446', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11748048820', 'Desodorante Antitranspirante Aerosol Dove Cuidado Total 150ml', '• O Desodorante Aerosol Dove Men+Care Proteção Total protege contra o suor e mau odor, o mantendo seco o dia inteiro • Desodorante aerosol projetado para 72h de proteção contra o mau odor, com uma fragrância refrescante e de longa duração • Este desodorante é formulado com tecnologia Tripla Ação que ajuda a proteger a pele, reduzindo o risco de irritações • Desenvolvido para ser um desodorante antitranspirante de uso diário para homens, ajudando você a se sentir revigorado, confortável e confiante o dia todo • Desodorante aerosol para homens com 1/4 de creme hidratante que é forte contra o mau odor e suave na pele • Desodorante ideal para homens que, além de hidratar a pele, contém uma agradável fragrância que a mantém refrescada e seca o dia todo O Desodorante Aerosol Dove Men+Care Proteção Total oferece uma proteção de 72 horas que mantém você refrescado e seco durante o dia todo, além de contar com uma fragrância suave e de longa duração. Este desodorante foi desenvolvido para ser usado diariamente, ajudando a se sentir revigorado, confiante e confortável o dia inteiro. O que faz de um antitranspirante o aliado perfeito para o dia a dia? Para nós, é a união entre potência e cuidado. É por isso que a linha de antitranspirantes Dove Men+Care combina uma avançada fórmula, que contém 1/4 de creme hidratante, com a tecnologia Tripla Ação que protege sua pele contra irritação. Dove Men+Care tem o que você precisa para se sentir sempre seguro e com uma agradável sensação de frescor que dura o dia inteiro. Para obter o máximo do seu Desodorante Aerosol Dove Men+Care Proteção Total, agite a embalagem para ativar os ingredientes. Segure-a voltada para cima a 15 cm das suas axilas e aplique um jato de dois segundos em cada uma. Experimente os desodorantes, sabonetes, shampoos, gel e espumas de barbear da Dove Men+Care e conheça um novo jeito de se cuidar. Dove Men+Care celebra uma nova definição de força masculina, em que o cuidado com o bem-estar do seu corpo é o centro de tudo. Dove Men é certificada Cruelty-Free pela PETA, sendo assim, você pode confiar que não realizamos e nem realizaremos testes em animais em nenhum lugar do mundo. Além disso, a lata do nosso antitranspirante é feita de metal reciclável e o produto não danifica a camada de ozônio.', 27.99, 23.62, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/d095caf2a89037804b93235a8f799658', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11748048820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19006822155', 'Kit Super Band Média Forte Extensor Elástico Power Odin Fit', 'Utilizada para potencializar os treinos a Super Band/Power Band Odin Fit facilita a execução e o fortalecimentos dos músculos nos treinos de força, resistência, alongamento e velocidade. Especificações do kit Power Bands 2 intensidades Média e Forte: 1 elástico (roxo) medindo 21mm de largura - média intensidade (30 a 60lb - 14 a 27kg); 1 elástico (Preto) medindo 32mm de largura - forte intensidade (40 a 80lb - 18 a 36kg). Cada elástico possui 208 cm de comprimento e Espessura de 4,5mm. Contém: 1 (um) Super Band Médio 22mm – Odin Fit; 1 (um) Super Band Forte 32mm – Odin Fit Produto com garantia de 3 meses contra defeitos de fabricação.', 178.8, 117.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Fitness Equipment', 'https://cf.shopee.com.br/file/d139c9376cce9d3a52e9b6cedc65e01f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F407831463%2F19006822155', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45650552132', 'Porta-Copo De Silicone Life CT-252 Verde Antiderrapante', 'Porta-Copo De Silicone Life CT-252 Verde, Antiderrapante Reutilizável, Proteção Para Mesa, Prático Limpar, para Bebidas Quentes Frias em Casa, Escritório 1. Life Porta-Copo De Silicone CT-252 Verde: coaster/descanso de copo antiderrapante que oferece praticidade e estilo para o dia a dia em casa ou no trabalho. 2. Proteção Para Mesa: ajuda a evitar marcas de copo, pingos e arranhões em superfícies como madeira, vidro, pedra e mármore, mantendo a bancada organizada. 3. Silicone Flexível E Reutilizável: material durável, fácil de lavar e secar, ideal para uso contínuo; basta enxaguar e está pronto para a próxima bebida. 4. Para Bebidas Quentes E Frias: compatível com copos, canecas e taças; ótimo para cozinha, escritório, bar, área gourmet e momentos de café ou happy hour. 5. Design Compacto CT-252: leve e prático para transportar, combina com decoração em verde e é uma ótima opção de porta-copo de silicone para uso diário. Garantia 90 dias', 28.96, 28.96, NULL, 'Home Appliances > Kitchen Appliances > Others', 'https://cf.shopee.com.br/file/br-11134275-81z1k-mge4ro9gfd3bc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1163157664%2F45650552132', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
