INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998076398', 'Kit 2 Hidratante Corporal Neutrogena Body Care Intensive Hidrata & Repara 200ml', 'O que é e para que serve? Um hidratante corporal com alta concentração de D-Pantenol, ativo rico em Vitamina B5, que restaura a barreira protetora da pele desde a primeira aplicação. Com tecnologia catiônica, oferece hidratação intensa de alta fixação adequada até para as peles mais delicadas. Benefícios e diferenciais -Restaura a barreira protetora da pele desde a primeira aplicação -Hidratação de alta fixação por 48 horas -Textura ultraleve de absorção imediata -Ideal para pele seca e extrasseca Como usar Aplique o produto sobre toda a pele do corpo massageando suavemente até a absorção completa. Dê especial atenção às áreas mais ressecadas como pernas, cotovelos e pés. Composição Lista completa de ingredientes: Aqua, Glycerin, Distearyldimonium Chloride, Paraffinum Liquidum, Cetyl Alcohol, Isopropyl Palmitate, Paraffin, Benzyl Alcohol, Dimethicone, Parfum, Titanium Dioxide, Panthenol, Sodium Chloride, Tocopheryl Acetate. Precauções Apenas para uso externo. Não ingerir. Conservar fora do alcance de crianças e em local fresco e seco. Descontinue seu uso se surgirem irritações na pele. Evitar contato direto com os olhos. Caso isso ocorra, enxágue-os com água em abundância. Em caso de ingestão acidental do produto, procure seu médico imediatamente."', 57.98, 57.98, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-823om-mojrcieng2ki1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23998076398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
