INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194398536', 'Kit 2 Base Cetim Novo Toque Tratamento 8ml', 'Base Cetim Tratamento Novo Toque 8ml Cuide das suas unhas com a Base Cetim Tratamento Novo Toque! Desenvolvida para fortalecer e proteger, sua fórmula proporciona um acabamento suave e uniforme, preparando as unhas para uma esmaltação impecável. Com textura leve e secagem rápida, ela cria uma camada protetora que ajuda a evitar descamação e quebras. Ideal para quem busca unhas saudáveis, resistentes e com brilho natural. Aposte na Base Cetim para um cuidado completo e prolongue a duração do seu esmalte! Especificações: Longa duração Alta cobertura Brilho intenso Secagem rápida Acabamento: Transparente Conteúdo: 8 ml Hipoalergênico: Não Testado em Animais: Não Modo de usar: Agite bem antes de usar. Aplique a base sobre as unhas antes da base ou após a esmaltação para acabamento. Comece a esmaltação pelo centro e, em seguida, preencha as laterais. Se desejar aplique uma segunda camada de esmalte. Use um palito com algodão umedecido em removedor para limpar o excesso do esmalte. Finalize com um secante. Precauções: Uso externo, produto inflamável, não expor ao calor/luz solar, não ingerir. Manter fora do alcance das crianças. Usar somente em adultos, não usar sobre a pele irritada ou lesionada, em caso de irritação, suspender o uso e procurar orientação médica.', 6.98, 6.98, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mqn1dqsa6xamba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23194398536', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
