INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20799071312', 'Caixa Organizadora São Bernardo em Plástico Preta 20L', 'Manter a organização da sua casa não é uma tarefa fácil, mas com a Caixa Organizadora São Bernardo, você economiza espaço, organiza objetos em um só lugar e deixa-os devidamente conservados sem contato com poeira ou umidade. Nela é possível guardar brinquedos, livros e objetos variados de forma simples e prática. Confeccionada em plástico, possui travas de fixação que prendem a tampa à caixa plástica. Na cor Preta, a caixa organizadora São Bernardo vai trazer estilo para sua casa, além de conter 20 Litros para guardar tudo o que deseja. Casa em Ordem Aproveite e coloque a casa em ordem com a ajuda das caixas organizadoras, melhorando assim a disposição dos espaços e facilitando o armazenamento de objetos utilizados no dia a dia de forma versátil! Existem diversos modelos e tamanhos de caixas que além de multifuncionais, vão dar um UP na decoração. Escolha a sua!', 39.99, 36.99, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-825b7-mqgdn1yi7572cd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050213612%2F20799071312', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
