INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54506978350', 'Copo Térmico Tumbler Lotso Toy Story 1,15L Zona Criativa - 10026740', 'Depois de um vivendo grandes aventuras, você precisa de uma mãozinha para se hidratar? A gente te ajuda! Com 1,15l de capacidade, esse copo é a companhia perfeita para um dia cheio de aventuras passando de fases! Não importa qual é a fase, esse copo te acompanha em todos os lugares! O produto é importado, feito em aço inox e plástico, possui detalhes incríveis que vão fazer você se apaixonar! Depois de um dia inteiro explorando novas fases, você precisa de uma mãozinha pra tomar aquele suco geladinho? A gente te ajuda! Com 1,15l de capacidade, um canudo com protetor e uma alça para carregar, esse copo é a companhia perfeita para o trabalho ou faculdade! Com uma tampa rosqueável, além de ser térmico, possui parede dupla que mantém sua bebida gelada por 12h e quente por 8h! Não importa onde é, esse copo te acompanha em todos os lugares! Especificações: Altura: 26cm| Largura: 10cm| Comprimento: 7cm| Capacidade: 1,15l| Material: Aço inoxidável e plástico Cuidados e recomendações de uso: Não colocar o produto na geladeira ou congelador. Choques ou quedas podem danificar o produto. Lavar com água, esponja macia e sabão neutro. Não vai á lava-louças e nem ao micro-ondas. Não utilizar produtos químicos ou abrasivos. Características: - Marca:Zona Criativa -Modelo:10026740 *Imagens meramente ilustrativas* Conteúdo da embalagem: - 01x Copo Térmico Tumbler Lotso - Toy Story', 174.44, 174.44, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262c-mlmbs2xl962s5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1088013647%2F54506978350', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294504190', 'Kit Amortecedor Dianteiro Nakata Fit 1.4 2003 A 2008', 'Este anúncio contém os seguintes produtos: Par de amortecedores dianteiros; Par de kit de amortecedor dianteiro composto por coxim, rolamento, coifa e batente. Fabricante dos amortecedores dianteiros: Nakata Fabricante dos kits dianteiros: Go Mec Produtos novos, com 2 anos de garantia para os amortecedores e 3 meses para os kits. Este produto se aplica a esses veículos: Veiculo: Fit; Motores: 1.4; Anos de fabricação: 2003, 2004, 2005, 2006, 2007, 2008; Veiculo: Fit; Motores: 1.5; Anos de fabricação: 2005, 2006, 2007, 2008; Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há duas décadas, nosso estoque conta com uma variedade de aproximadamente 45.000 itens. Nossa equipe de Pós-Vendas é altamente capacitada, resultando na excelência no atendimento e na busca constante pela satisfação dos clientes. Navegue pela loja virtual e fique à vontade!', 739.0, 739.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-824hv-mfgul4lz1hxkde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397705076%2F22294504190', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
