INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194254884', 'Pastilha De Freio Dianteira Renaut Clio 1996 Até 2016 Todos', 'Pastilha de Freio Dianteira Renault Clio 1996 a 2016 – Todas as VersõesGaranta a segurança e o bom desempenho do seu Renault Clio com esta pastilha de freio dianteira de alta qualidade. Compatível com todas as versões e motorizações do Clio, fabricadas entre 1996 e 2016, ela oferece frenagem eficiente, silenciosa e com excelente durabilidade.Fabricada com compostos resistentes ao desgaste e à alta temperatura, essa pastilha proporciona menor emissão de ruído e poeira, além de encaixe perfeito no sistema de freio original.Aplicação:Renault Clio – Todos os modelos e versõesAno: 1996 até 2016Posição: DianteiraVantagens: Frenagem segura e estável Encaixe preciso e fácil instalação Alta durabilidade mesmo em uso intenso Baixo ruído e mínima geração de resíduos', 61.28, 61.28, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcccbjdemelka5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1464009232%2F22194254884', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498664840', 'Arla 32 Aditivo De Combustível Diesel 05 Litros', 'Arla 32 Bioarla – Aditivo para Motores Diesel (5 Litros)O Arla 32 Bioarla é a escolha certa para quem busca eficiência e desempenho em veículos a diesel de linha pesada. Com embalagem de 5 litros, foi desenvolvido para reduzir as emissões de poluentes e melhorar o funcionamento dos sistemas SCR (Redução Catalítica Seletiva).Fabricado pela BIOARLA, este produto atende aos padrões mais exigentes do mercado e é compatível com diversos modelos de caminhões e picapes com motorização diesel. Sua composição à base de ureia de alta pureza garante a eficiência na conversão de óxidos de nitrogênio (NOx) em nitrogênio e vapor d’água, contribuindo para um transporte mais limpo e responsável.Mais que um aditivo, o Arla 32 é um componente essencial para a manutenção do sistema de pós-tratamento de gases, aumentando a vida útil do motor e reduzindo o impacto ambiental.Benefícios:Redução de emissões nocivasMelhora na eficiência do sistema SCRCompatível com veículos pesados a dieselProduto confiável e certificadoCondução mais limpa e sustentável', 47.52, 47.52, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mb5ckwq1595b03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1464009232%2F22498664840', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
