INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998288696', 'Tônica Schweppes Rosé Frutas Vermelhas 220ml Pack C/6 Unidades', 'Experimente a refrescante e sofisticada Tônica Schweppes Rose Frutas Vermelhas na conveniente lata de 220ml. Esta bebida é a escolha perfeita para elevar seus momentos de descontração e dar um toque de elegância às suas celebrações. Sugestão de Consumo: Servir gelado, acompanhado do destilado de sua preferência e decore com frutas vermelhas ou uma rodela de limão. Também pode ser apreciado sozinho como uma bebida refrescante. Volume: 220ml Sabor: Frutas Vermelhas Contém: 6 Unidades (Latas). Ingredientes: Água gaseificada, açúcar, acidulante (ácido cítrico), aromas naturais e artificiais, conservadores (benzoato de sódio e sorbato de potássio), corantes (carmim de cochonilha e betacaroteno) e quinina. Armazenar em local fresco e seco, protegido da luz solar direta. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 31.99, 31.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6zjwak0ri2v33', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F23998288696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
