INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45401771546', 'Boneco Funko Pop! Exc One Piece - Monkey D. Dragon', 'Adicione poder e revolução à sua coleção com o exclusivo Boneco Funko Pop! Monkey D. Dragon com Chase. Este personagem icônico da série anime One Piece chega em versão colecionável de vinil com aproximadamente 11 centímetros de altura, pronto para ocupar um lugar de destaque na sua coleção POP! Animation. Com 1 em 6 chances de encontrar a versão chase sem capuz, este item exclusivo é perfeito para fãs e colecionadores que buscam peças raras e diferenciadas. O boneco conta com embalagem de autenticação inovadora, utilizando tecnologia micro-óptica que não pode ser duplicada, com códigos únicos verificáveis oficialmente pelo Octane5. Este é um item essencial para qualquer fã de One Piece que deseja enriquecer sua coleção com exclusividade e estilo.', 199.99, 199.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-821fy-mh9gbn75tssva8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F45401771546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
