INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259705212', 'Iogurte Lacfree Banana Maçã e Mamão Verde Campo', 'Sabe quanto de natureza você encontra nesta garrafinha de 170g do primeiro iogurte sem lactose do Brasil? Com pedacinhos de três deliciosas frutas - banana. maçã e mamão -. ele não tem conservantes nem aditivos artificiais. Até o corante é de origem natural. o conhecido urucum. fruto cujo nome vem do tupi-guarani e significa “vermelho”. Sua escolha natural. para encher de saúde e sabor o seu dia a dia. Este iogurte é zero gordura, não possui adição de açúcares e é zero lactose. Uma opção saudável para lanches rápidos entre as refeições e atividades do dia a dia. 100% natural e livre de conservantes e aditivos artificiais.', 5.79, 5.79, NULL, 'Food & Beverages > Dairy & Eggs > Yogurt & Cultured Milk', 'https://cf.shopee.com.br/file/sg-11134201-825ao-mqneky1ljpc121', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F58259705212', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
