INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '55257698903', 'Tênis Skechers Go Run Consistent 2.0 Feminino Roxo', 'Tecnologias Go Run: solados leves e responsivos que garantem excelente retorno de energia. Air-Cooled Goga Mat™: Palmilhas oferecem amortecimento responsivo e ventilação eficaz, mantendo seus pés frescos, secos e confortáveis durante todo o treino. M-Strike®: Otimiza a transição de impacto ao impulso, garantindo passadas suaves e mais estáveis, o que aumenta sua velocidade e reduz o risco de lesões. Lavável na máquina: Permite higienização prática e rápida sem danificar o produto. Composição cabedal (parte superior): Material têxtil e sintético Forro: Têxtil com acolchoamento reforçado no calcanhar Palmilha: Em EVA, forrada, moldada e removível Solado: Borracha com função antiderrapante, colado Altura da Sola: 4 cm Entressola: EVA leve e macio Lingueta: Macia e acolchoada Cor predominante: Roxa Gênero: Feminino Origem: Nacional Ajuste: Cadarço Peso aproximado: 470g o par nº 37', 430.9, 430.9, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mm94xku1c5jc8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F55257698903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
