INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209718634', 'Filé de Salmão em Pedaços Noronha 500g', 'Saboreie a qualidade superior do Filé de Salmão em Pedaços Noronha, disponível em práticas embalagens de 500g. Cada pedaço é cuidadosamente cortado a partir de filés selecionados de salmão, garantindo um sabor suave e uma textura tenra que é perfeita para uma variedade de pratos. Ideal para quem busca uma opção de refeição rápida e saudável, este salmão é excelente para saladas, massas ou como um prato principal requintado. Seja grelhado, assado ou adicionado a um ensopado, o Filé de Salmão em Pedaços Noronha proporciona uma experiência culinária deliciosa e conveniente. Transforme qualquer refeição em uma ocasião especial com este filé de salmão de alta qualidade!', 57.99, 57.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Seafood', 'https://cf.shopee.com.br/file/sg-11134201-81zwp-miyqch1ymebnbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58209718634', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
