INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393486127', 'Tamanco Mississipi de Salto Bloco MC411', 'Produto marca Mississipi. Sinta a elegância e a praticidade em cada passo com o Tamanco Mississipi de Salto Bloco da coleção Primavera/Verão 2024 e está disponível na cor ! Perfeito para mulheres que buscam estilo e praticidade no dia a dia, esse modelo combina o charme de um salto bloco alto com detalhes sofisticados, criando um calçado versátil e moderno. O salto bloco de 6,5 cm proporciona um leve aumento na altura, alongando a silhueta e garantindo mais conforto ao caminhar. As tiras macias envolvem seus pés com delicadeza, proporcionando um ajuste perfeito e evitando incômodos. o destaque fica por conta da tira repleta de brilhos na parte frontal, que adiciona um toque de elegância e sofisticação ao seu visual. Seja para um passeio no parque, um dia de compras ou um happy hour com as amigas, esse tamanco te acompanha em qualquer ocasião, garantindo um look moderno e cheio de estilo. Peso: 0,585 kg Altura do salto: 6,5 cm', 129.9, 119.9, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-8260g-mlwg7gg6h7upd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1082095796%2F23393486127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
