INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58262870965', 'Cooler para Processador Thermalright Peerless Assassin 120 SE,ARGB,120mm, Preto,TR-PA-120-SE-BK-ARGB', 'COOLER THERMALRIGHT PEERLESS ASSASSIN 120 SE O cooler para processador Thermalright Peerless Assassin 120 SE é o ideal para seu computador utilizando 6 heatpipes de 6mm. QUALIDADE SUPERIOR Possuindo cores chamativas ARGB nas duas ventoinhas e com ruído de 25.6 dBA máximo. Marca: Thermalright Modelo: TR-PA-120-SE-BK-ARGB Características: - O Peerless Assassin 120 SE ARGB conta com uma estrutura robusta preparada para levar os melhores processadores do mercado. - Inclui ventiladores PWM ARGB de alto desempenho com rolamento de fluidos dinâmicos para uma refrigeração aprimorada. - Base de 6 Heatpipes de 6mm de cobre niquelado para melhor distribuição do calor. Soquete: - Intel: 115X/1200/1700/1851 - AMD: AM4/AM5 Dissipador de calor: - Dimensões: 125 x 110 x 155 mm - Peso: 730g - Tubos de calor: 6 heatpipes de 6mm - Material: Cobre niquelado (Heatpipes e base) e Alumínio (aletas) TDP: 265W Ventoinha: -Ventoinha TL-C12C-S: -Dimensões: C 120 mm x L 120 mm x A 25 mm -Peso: 120 g -Velocidade nominal: 1550 RPM ± 10% (máx.) -Nível de ruído: 25,6 dBA -Fluxo de ar: 66,17 CFM (máx.) -Pressão de ar: 1,53 mm H2O (máx.) -Amperagem: 0,20 A - Conector: 4 pinos (conector de ventoinha PWM) - Conector ARGB: 3 pinos 5 V - Tipo de rolamento: Rolamento S-FDB Sobre a Pichau Informática Com mais de 18 anos de atuação no mercado nacional de tecnologia, a Pichau se destaca por seu compromisso com a inovação, qualidade e a satisfação do cliente. Referência em performance e confiabilidade, a empresa segue evoluindo para entregar produtos de excelência em diversas áreas, incluindo o esporte.', 534.04, 273.78, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-824io-mpo1ou8re2od09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F627750190%2F58262870965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
