INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13848043505', 'Inalador Compressor NebPlus com Máscara Multilaser', 'Tamanho Ideal de Partículas O NEBPLUS transforma os líquidos em micro partículas de 0,2 um, o que facilita a absorção do medicamento no pulmão, e pode ser usado no tratamento de asma, bronquite, alergias e outras doenças respiratórias. Características: Fácil de Transportar Com bolsa para guardar e transportar. Fácil de Utilizar Somente um botão de operação e pode ser usado com as mãos livres. Inclinação Máxima de 45º Permite fazer a inalação sem derramar a medicação. 1- Bolsa para transportar. 2- Acompanha máscara: infantil e adulto. 3- Copo de medição. 4- Nebulizador compressor. 5- Botão liga/desliga. 6- Alça para transportar. 7- Cordão para fixar na cabeça. 8- Tubo de ar. 9- Bocal. 10- Filtros de ar. Garantia do Fornecedor: 03 meses * Imagens Meramente Ilustrativas *', 252.89, 229.9, NULL, 'Health > Medical Supplies > Nasal Care', 'https://cf.shopee.com.br/file/br-11134201-820m4-mqx9hjvpxona44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F389315825%2F13848043505', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250012002', 'Mini Clássicos | Heidi', 'Colecione os mais famosos clássicos da literatura infantil de todos os tempos. Histórias de fantasia, de magia e de aventuras que estimulam a imaginação das crianças, educando por meio de preciosos ensinamentos. Dimensões: 16x11cm 16 páginas.', 7.9, 1.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8259g-mg88f1oaq0p697', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250012002', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794212265', 'Paulo: Uma Biografia | N. T. Wright', 'Esta cativante reconstrução da vida e do pensamento do apóstolo Paulo - escrita com excelência por um dos estudiosos paulinos mais influentes da atualidade - traz à tona o mundo romano antigo em todos os detalhes: sociais, históricos e culturais. Nesta biografia definitiva, N. T. Wright oferece uma visão fascinante da história de Paulo, levando-nos a caminhar ao lado do apóstolo, observando, aprendendo, sofrendo e celebrando com ele. O autor nos guia pelas jornadas fascinantes do antigo perseguidor de cristãos e suas experiências e desafios cidade após cidade, onde pregou a mensagem revolucionária do evangelho da salvação e deixou um legado cujas reverberações são sentidas até hoje. Em Paulo: uma biografia, N. T. Wright não nos apresenta um teólogo impassível ou um evangelista implacável, mas o retrato autêntico de um personagem complexo, multifacetado e que pode, sem dúvidas, ser considerado um dos maiores líderes cristãos da história. 23X15 CM 480 Páginas', 51.9, 50.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdvw-mbxl0eraswge2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22794212265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44864013284', 'Devocional 3 Minutos de Sabedoria para Mulheres | Bouquet de Rosas', 'Caderno devocional 3 min de sab p/ mulh bouquet de rosas Devocional 3 minutos de sabedoria para mulheres Manter uma rotina devocional consistente é essencial para desenvolver intimidade com Deus. Os devocionais foram projetados para ajudar a estruturar esse tempo sagrado. Eles permitem registrar orações, estudos bíblicos, pedidos e gratidão, promovendo o crescimento espiritual contínuo. Ao preenchê-los regularmente, é possível perceber a evolução da fé e reconhecer as bênçãos ao longo da jornada. Não adie mais: seu tempo com Deus começa agora! 11x15cm 192 Páginas', 15.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8259x-mqnkbbbp5bsx2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F44864013284', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799325377', 'Desodorante Aerossol Rexona Feminino Bamboo 150ml', 'Desodorante Aerossol Rexona Feminino Bamboo 150ml Mais uma vez Rexona se supera e relança sua linha de desodorantes com uma fórmula inovadora, que combina um novo e exclusivo ativo antitranspirante com a tecnologia de fragrâncias encapsuladas. O resultado? 72 horas de proteção ativada pelo seu movimento e muito mais confiança para você encarar qualquer desafio.', 19.99, 19.99, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-lxcz1dvs4w2u18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F18799325377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492893842', 'Uma História da Obra da Redenção | Jonathan Edwards', 'A encarnação e a ressurreição de Cristo são os acontecimentos mais incríveis de toda a história humana. Em 1739, Jonathan Edwards pregou uma série de trinta sermões em sua igreja em Northampton, Massachusetts, tendo como referência Isaías 51.8: “Pois a traça os roerá como uma roupa, e o bicho os comerá como se fossem lã. Mas a minha justiça durará para sempre, e a minha salvação, por todas as gerações”. Este livro é baseado nesses sermões, e Edwards, de maneira magistral, traça a obra da redenção de Deus desde o início até o fim da história. Edwards considerava esta obra o ápice de todo o seu trabalho ao longo da vida. Seu objetivo foi escrever uma teologia sistemática usando um “método inteiramente novo”. Esse novo método acabou contribuindo para o que talvez seja o primeiro tratado de teologia bíblica na história da igreja cristã. Ele desejava que todos soubessem que a Bíblia tem uma mensagem e um propósito ― revelar à humanidade o único plano de redenção que se desdobrou nas Escrituras, desde a primeira até a última página da Bíblia. Esse plano especial tem em vista uma pessoa, Jesus Cristo. Para Edwards, tudo na história do mundo foi planejado à luz “do grande trabalho de redenção por Jesus Cristo... o grande projeto de todos os desígnios de Deus”. Esta é uma obra que todos os estudantes da Bíblia devem não somente ler, mas ter à disposição em suas estantes para saber explicar com robustez o triunfo do evangelho. 16x23cm 304 Páginas', 63.9, 58.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rccm-lsyy9elqcr8ma0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23492893842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
