INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15911085646', 'Generais de Deus Os Evangelistas de Cura | Roberts Liardon', 'Esse é um livro evangélico especial e de grande importância para os Cristãos. A obra é de Roberts Liardon e a distribuição é feita pela editora Bello Publicações. Generais de Deus: Os Evangelistas de Cura é um livro sobre a vida e o ministério dos grandes evangelistas de cura do século 20: Oral Roberts, Lester Sumrall, Charles e Frances Hunter, F. F. Bosworth e George Jeffreys. Esse obra além de lhe contar um pouco da histórias desses grandes evangelistas, também irá inspirá-lo a: • Desenvolver uma fé maior em sinais e milagres • Encontrar encorajamento para enfrentar batalhas espirituais • Sentir a alegria de ganhar almas • Cumprir o chamado de Deus em sua vida • Buscar a Deus para receber cura física e espiritual Deus usou a vida desses exemplos de fé para curar milagrosamente milhares de pessoas. Aprenda como você também pode experimentar sinais e milagres em sua vida e na vida de outros', 41.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/827da308821b9c82781e3aaf9f204009', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F15911085646', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
