INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19125940040', 'Roupa Intima Tena Dermacare Pants Ultra G/EG com 8 unidades', 'TENA Pants Dermacare é uma roupa íntima descartável e unissex de rápida absorção, que proporciona ao usuário ativo segurança e proteção da pele. Um produto hipoalergênico com tecido respirável e macio que ajuda na prevenção de irritações, permitindo que a pele esteja sempre saudável e seca. A excepcional segurança deve-se à tecnologia antivazamento que absorve rapidamente grandes quantidades de urina mantendo-a longe da pele de forma que, mesmo sentado ou deitado durante muito tempo, o usuário permanece seco e confortável, reduzindo significativamente o risco de infecções cutâneas. É indicado para perdas de urina severa. Proteção e cuidado para a pele todos os dias. • Tamanho: G - EG (70 - 110 cm) • Referência: 70-110 kg', 48.19, 48.19, NULL, 'Health > Personal Care > Adult Diapers & Incontinence', 'https://cf.shopee.com.br/file/sg-11134201-7rblh-m5imunbw42gk35', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819145905%2F19125940040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
