INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994254818', 'Serra Mármore Britânia 1300w Hobby 13000 RPM BSM01', '***PRODUTO A PRONTO ENTREGA COM ENVIO IMEDIATO*** ITEM ORIGINAL COM NOTA FISCAL Somos a Domus, Loja oficial da Shopee. Temos 5 anos de experiência em E-Commerce e nosso maior objetivo é garantir a satisfação dos nossos clientes! Serra Mármore Britânia BSM01 1300W 13000 RPM com Disco 110mm. Alta rotação, cortes precisos e total praticidade. A Serra Mármore BSM01 da Britânia é ideal para cortar azulejos, cerâmica, mármore, granito e pedras decorativas com eficiência e segurança. Com motor de 1300W e rotação de até 13.000 RPM, entrega performance superior para trabalhos profissionais ou domésticos. Possui regulagem de ângulo e profundidade de corte, adaptando-se ao tipo de material e acabamento desejado. A chave de acionamento com trava dupla garante maior segurança, enquanto o cabo de 1,8 metro facilita o manuseio em diferentes espaços. Diferenciais do produto: Alta rotação de 13.000 RPM para cortes precisos Motor potente de 1300W para alto desempenho Regulagem de profundidade e ângulo de corte Disco diamantado de 110mm incluso Chave com trava dupla para maior segurança Cabo elétrico de 1,8m para maior alcance Disponível nas versões 127V e 220V Design ergonômico com estrutura robusta Especificações técnicas: Marca: Britânia Modelo: BSM01 Potência: 1300W Rotação: 13.000 RPM Diâmetro do disco: 110mm (4.3/8”) Voltagem: 127V ou 220V Material: Plástico e metal Comprimento do cabo: 1,8m Acessórios: 1 disco diamantado, 2 chaves para troca Uso: Cortes em cerâmica, mármore, granito, azulejos e pedras decorativas A Serra Mármore ideal para sua obra, com desempenho e segurança que você confia.', 346.9, 346.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcmcn4qjhfleeb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F22994254818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
