INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497868558', 'Etiqueta adesiva TP19 verde Pimaco', 'A PIMACO Multiuso TP Verde Ø19mm é a opção ideal para quem busca praticidade e eficiência na organização, identificação e sinalização de itens. Com um design compacto e cor vibrante, essa etiqueta adesiva é perfeita para uso em diversos ambientes, como escritórios, escolas, lojas, indústrias e até em casa. Sua cor verde proporciona um contraste suave e é perfeita para situações que exigem uma identificação clara e visualmente acessível. Detalhes: - Tamanho: Ø19 mm - Quantidade de folhas 10 - Quantidade de etiquetas por folha 20 - Quantidade de etiquetas por envelope 200.', 16.91, 13.53, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/sg-11134201-82632-mlql2a562o0394', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1350081126%2F21497868558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
