INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23608652275', 'Cortador de Grama 6,5 HP à Gasolina 4T LF-600RM TRAPP', 'Cortador de Grama 6,5 CV à Gasolina 4T LF-600RM TRAPP Características Equipado com afogador manual e válvula de combustível para facilitar a partida do motor. Possui bujão para facilitar a drenagem do óleo do cárter, controle manual de aceleração e baixo índice de vibração e ruído; Nova dimensão nas rodas traseiras, facilitam muito a mobilidade dos novos cortadores em qualquer tipo de terreno; Rodas de termoplástico com bucha sinterizada; Tamanho das rodas: Dianteiras 203 mm / Traseiras 305 mm; Com restrição de uso em terrenos acidentados (inclinação máxima de 15) e eventuais manobras de até 30; Cabo ergonômico para maior conforto do eperador, dobrável, facilitando o transporte e armazenamento; Base em chapa de aço de 1,9 mm de espessura; Equipado com motor TRAPP, movidos a gasolina comum (não aditivada); Consumo de combustível aproximadamente 1 litro/h; Lubrificante óleo SAE 20W50; Efetuar 1 troca após primeiras 5 horas de trabalho e as próximas a cada 50 horas de trabalho, com manutenção do filtro de ar; Lâmina em aço especial, de 3 mm de espessura com têmperatura por indução no fio de corte; Saída Lateral; Regulagem de altura de corte em 9 posições, com variação de 2,8 a 8,9 cm (sistema de regulagem de altura individual nas 4 rodas); Rendimento aproximado de 800m/h; Todas as peças recebem tratamento anticorrosivo e pintura com tinta a pó de poliéster polimerizado em estufa a 220C, garantindo maior durabilidade e acabamento; Garantia: 12 meses. Ficha Técnica: Potência: 6,5 CV Capacidade do Tanque de Combustível: 1,7 litros Capacidade óleo do Cárter: 0,6 litro Faixa de corte: 48 cm Recolhedor: Saída Lateral (não acompanha) Peso líquido (kg): 35 Rotação: 3000 rpm Aplicação: Recomendado para médias e grandes áreas de até 800m.', 2948.9, 2692.9, NULL, 'Home & Living > Gardening > Lawn Mowers', 'https://cf.shopee.com.br/file/br-11134201-23030-kjwhyvbuyeove7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F23608652275', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19399498626', 'Colchão Casal Espuma D23 Comfortpedic Line (138x188x12) - Orthoflex', 'COLCHÃO CASAL D23 ORTHOFLEX COMFORTPEDIC LINE 138X188X12 Marca: Orthoflex Linha/Modelo: D23 Comfortpedic Line Dimensões(Cm): Colchão D23 Comfortpedic Line Comprimento(Profundidade): 188 cm Largura: 128 cm Altura: 12 cm Espuma de Estofamento: - Alta Qualidade Suporte de Peso: - 70 kg Nível de Firmeza do Colchão: - Macio c/ Firmeza Densidade da Espuma: - D23 Tipo de Colchão: - Espuma Benefícios Extras de Colchão: - Ecologicamente Correto, Manta Acrílica Tecido com Tratamento: - Antiácaro e Antifungo Tipo do Bordado do Tecido: - Matelassê Características do Tecido: - Poliéster Tecido da Faixa Lateral: - Poliéster Modo de Utilização: - Double Side Certificação de Qualidade: - INMETRO, Qualidade Costa Rica Nossa Avaliação: - Qualidade Muito Boa Tempo de Garantia: - 12 meses Imagens Meramente Ilustrativas. Não nos responsabilizamos pela montagem/instalação dos produtos. Todas as informações divulgadas são de responsabilidade exclusiva do fabricante/fornecedor. -Verifique com os fabricantes do produto e de seus componentes eventuais limitações à utilização de todos os recursos e funcionalidades - Confira as dimensões do produto e analise se irão passar normalmente por elevadores, portas, escadas e corredores, pois não nos responsabilizamos caso o produto necessite durante a entrega de: Desmontagem, subir escadas ou ser transportado por guincho, cordas para apartamentos. A entrega limita-se ao descarregamento em local que tenha e ofereça total facilidade de acesso normal; - Só fazemos entregas por transportes rodoviários. Não realizamos entregas por transportes fluviais, aéreos e outros diferente de rodoviário. Não realizamos entregas na região norte: Amapá, Amazonas, Pará, Roraima e Acre; - Temos áreas com restrição e dificuldades que os transportadores rodoviários não atendem. Área de difícil acesso, área de risco, área rural, áreas fluviais, estradas não pavimentadas; - Sendo assim, caso seu endereço esteja em área restrita de entrega, a retirada de sua compra deverá ser realizada no CD do transportador ou indicar no momento da compra um endereço entrega fora da área restrita; - Caso realize pedido com entregas em locais de difícil acesso ou áreas com restrição e dificuldades que os transportadores e proprio correios não atendem, a compra sera cancelada pela Costa Rica Colchões, com a devida comunicação e estorno do pagamento ao cliente.', 481.91, 457.82, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-825ab-mq3sbob5zwgdc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1235923910%2F19399498626', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18698049823', 'Piscina com Armação 1.500L 42x189x189CM e Capa para Piscina 1500L MOR', 'Piscina com Armação 1.500L 42x189x189CM e Capa para Piscina 1500L MOR Para garantir momentos de lazer refrescantes e práticos, a Piscina com Armação 1.500 Litros MOR é a escolha ideal para famílias que desejam se divertir nos dias quentes. Com um formato quadrado de 189 x 189 x 42 cm, essa piscina maximiza o espaço interno, permitindo que várias crianças aproveitem ao mesmo tempo. Seu material em lona de PVC impermeável evita vazamentos e assegura maior segurança, enquanto sua cor azul vibrante adiciona um toque alegre ao ambiente. A estrutura dessa piscina é altamente resistente, composta por tubos de aço reforçados com acabamento em epóxi anticorrosivo, o que garante maior durabilidade e proteção contra ferrugem. Além disso, sua montagem e desmontagem são práticas, tornando-a perfeita para transportar e armazenar com facilidade. Seja no quintal, na praia ou no campo, essa piscina é uma opção versátil para quem busca refrescância sem complicações. Para manter a água sempre limpa e protegida, a Capa para Piscina Retangular 1.500 Litros MOR é um acessório indispensável. Fabricada em polietileno de alta qualidade, essa capa impede a entrada de folhas, poeira e insetos, reduzindo a necessidade de limpeza frequente. Seu formato quadrado de 2,19m x 2,19m cobre toda a piscina de maneira eficiente, prevenindo também a evaporação excessiva da água. Além de preservar a qualidade da água, a capa reduz a exposição à luz solar direta, minimizando o crescimento de algas e micro-organismos. Com cordas de poliéster para fixação, ela se ajusta firmemente à estrutura da piscina, evitando deslocamentos causados pelo vento. Seu material resistente garante longa durabilidade, proporcionando proteção eficaz por muito mais tempo. Com a combinação da Piscina com Armação 1.500 Litros MOR e sua respectiva Capa Protetora, você garante um verão mais divertido e tranquilo para toda a família. A praticidade na montagem, a resistência dos materiais e a eficiência da proteção fazem desse conjunto uma excelente escolha para quem deseja lazer e segurança em um só produto. VANTAGENS E BENEFÍCIOS Diversão Completa: A piscina de 1.500 litros oferece espaço ideal para momentos refrescantes com a família, enquanto a capa protege a água contra sujeiras e reduz a necessidade de manutenção. Durabilidade e Resistência: Fabricada em lona de PVC e estrutura em aço com acabamento epóxi, a piscina é resistente ao sol e ao uso contínuo. A capa de polietileno garante proteção contra agentes externos e maior vida útil. Praticidade na Montagem e Armazenamento: Fácil de montar e desmontar, a piscina pode ser transportada e guardada sem dificuldades, enquanto a capa leve e dobrável permite armazenamento compacto. Economia e Sustentabilidade: A capa reduz a evaporação da água e minimiza o uso de produtos químicos, ajudando a economizar recursos e manter a piscina sempre pronta para o uso. Fixação Segura e Ajustável: Com cordas de poliéster, a capa fixa firmemente na piscina, evitando deslocamentos pelo vento e garantindo vedação eficiente para uma água sempre limpa. DADOS TÉCNICOS Piscina com Armação 1.500 Litros 42 x 189 x 189 CM 001003 MOR Material: Lona de PVC impermeável Estrutura: Aço com acabamento epóxi Formato: Quadrado Cor Predominante: Azul Capacidade Máxima: 1.500 litros Dimensões: Altura: 42 cm Largura: 1,89 m Comprimento: 1,89 m Peso: 6,77 kg Capa para Piscina Retangular 1500 Litros 2,19m x 2,19m 1403 MOR Capacidade da Piscina Compatível: 1.500 litros Material: Polietileno de alta qualidade Dimensões: 2,19 m x 2,19 m Peso: 1,04 kg Recursos: Proteção contra sujeiras como folhas, poeira e insetos Redução da evaporação e proliferação de algas Fixação segura com cordas de poliéster Leve, prática e fácil de instalar CONTEÚDO Piscina com Armação 1.500 Litros 42CM x 1,89m x 1,89m MOR Capa para Piscina Retangular 1500 Litros 2,19m x 2,19m MOR Garantia: 3 meses Referência: 1003 | 1403 Marca: MOR * Imagens meramente ilustrativas.', 339.9, 314.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-m6qwerdbucgr1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F18698049823', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9738399935', 'Filtro De Ar Condicionado UNO Novo uno vivace Argo Mobi', 'FILTRO DE AR CONDICIONADO fiat mobi Fiat argo Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar. - Retém partículas que provoca alergias, como Pólen. - Efetiva filtração de partículas finas como fuligem, gases de escape, bactérias, etc... - Proteção do sistema de ventilação (aquecimento e Ar condicionado).', 22.99, 22.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyzefp7d49wl7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F9738399935', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
