INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16311724021', 'Disco Diamantado Segmentado Bosch ECO For Universal 230 x 22,23x2,6x7mm', 'O disco diamantado Eco for Universal possui segmentos de corte sinterizados oferecendo um bom desempenho de corte em diversos materiais como: concreto, tijolo, calcário e telha. Características: - Corte de Concreto, Alvenaria, Tijolo, Granito - Compatível com quase todos os materiais empregados na construção civil - Mais desempenho para sua ferramenta. Acessórios Profissionais Bosch. - Ganho de produtividade, uma vez quem não será necessário trocar o acessório da sua ferramenta para cada material - Design Segmentado - Adequado para todas as marcas de ferramentas elétricas. Público Alvo: Encanadores, eletricistas, trabalhadores de construção civil, construtores, instaladores de piso e revestimentos (azulejos e porcelanato), Instaladores de piso e revestimentos sanitários, pedreiros, instaladores, calheiros, azulejistas, vidraceiros, mestre de obras Diferenciais Técnicos: O disco diamantado Eco for Universal possui segmentos de corte sinterizados oferecendo um bom desempenho de corte em diversos materiais como: concreto, tijolo, calcário e telha. Dados técnicos: - Diâmetro do disco: 230mm - Diâmetro do furo: 22,23mm - Tipo de disco: segmentado - Quantidade de segmentos: 18 - RPM Máximo: 6.650 RPM', 95.9, 95.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/2bb3301a45e4d526b4be79a5947ec87a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F16311724021', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
