INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254732358', 'Galão Aditivo Radiador Pronto Para Uso 5 Litros Black Brasil', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Galão Aditivo Radiador Pronto Para Uso 5 Litros Black Brasil APLICAÇÃO ADITIVO RADIADOR ECONOMY PRONTO PRA USO ROSA GALÃO 5 LITROS CÓDIGO DO FABRICANTE 300.307.015 - BLACK BRASIL CONTEÚDO DA EMBALAGEM 01 Galão Aditivo Radiador Pronto Para Uso 5 Litros Marca Black Brasil QUALIDADE Produto Novo GARANTIA SEM GARANTIA NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 33.9, 33.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8260k-mkctbbersydk6f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F433880234%2F58254732358', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209696882', 'Ração Úmida Whiskas Sachê Frango ao Molho para Gatos Adultos', 'Whiskas Sachê Frango ao Molho é uma ração úmida deliciosa e nutritiva, feita com ingredientes naturais de alta qualidade, vitaminas e minerais. Cozidos a vapor, os pedacinhos de frango são irresistíveis para seu gato! * Refeição completa e balanceada para gatos adultos. * Ajuda a manter a saúde do trato urinário. * Sem conservantes, corantes ou aromatizantes artificiais. Guia alimentar: sirva 3 sachês por dia para gatos adultos de 4kg. Cada sachê de Whiskas equivale a 1/4 de xícara de Whiskas seco (1 xícara = 200ml).', 3.79, 3.79, NULL, 'Pets > Pet Food > Cat Food', 'https://cf.shopee.com.br/file/sg-11134201-822wk-mo5ms28b9lhc0c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554990%2F58209696882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18157593786', 'Estante com Painel TV 55" e 2 portas Denver Multimóveis Rustic/Preto', 'Não tem nada melhor do que um ambiente bonito e organizado para receber as visitas, não é mesmo? A Estante com Painel TV 55" e 2 portas Denver Multimóveis vai deixar sua sala completa, enriquecendo ainda mais a decoração. Produzida em MDP, que garante maior durabilidade, resistência e facilidade na limpeza, possui painel para TV de até 55” (suporta até 26 Kg) com espaçamento para a passagem dos fios, que deixa o visual mais clean e os cabos organizados. Além das prateleiras que podem ser utilizadas para artigos decorativos, possui nichos para acomodar os equipamentos eletrônicos e 2 portas com um amplo espaço interno para manter seus pertences organizados. A TV pode ser fixada no painel com o auxílio de um suporte (vendido separadamente), porém, neste caso, para maior segurança, sugerimos que a estante seja fixada na parede. Conteúdo da Embalagem: 1 (uma) estante Dimensões do produto montado: Altura: 164 cm - Largura: 165 cm - Profundidade: 32,5 cm Tamanho Painel TV: 133,5 x 100cm *Devido as variações de tamanho dos televisores no mercado, sugerimos que verifique as medidas da sua TV e compare com o painel antes de efetuar a compra. *Você pode consultar as medidas internas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 719.9, 499.99, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-23010-t9ecv2you7lv2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F18157593786', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892624627', 'Armário Aéreo 80cm com 1 Porta Basculante Paris Multimóveis MP2187', 'O Armário Aéreo 80cm com 1 Porta Basculante Paris Multimóveis MP2187 é a solução ideal para quem busca funcionalidade e estilo. Produzido em MDP (15mm), material reconhecido pela durabilidade, possui acabamento acetinado (cerca de 20% de brilho) que agrega elegância ao ambiente. Com 1 porta basculante equipada com pistão a gás e puxador em ABS com acabamento cromado, oferece praticidade no dia a dia. Além disso, seu amplo espaço interno proporciona organização para diversos objetos. Com design moderno e funcional, o armário aéreo se destaca como uma opção prática para otimizar o espaço, garantindo qualidade e beleza. Conteúdo da Embalagem: 1 (um) Armário Aéreo 80cm Manual de Montagem Kit Ferragem Dimensões do produto montado: Altura: 33,5cm | Largura: 80cm | Profundidade: 32cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 219.99, 199.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rcf6-ltv5epx5m06b78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23892624627', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
