INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22198135739', 'Kit 2 Livros | Bíblia para crianças 3 Palavrinhas + Box com 6 Minilivros 3 Palavrinhas Deus é amor', 'Kit 2 Livros | Bíblia para crianças 3 Palavrinhas + Box com 6 Minilivros 3 Palavrinhas Deus é amor Bíblia para crianças 3 Palavrinhas: Conheça lindas histórias do Antigo e Novo Testamento! Junto da Turma de 3 Palavrinhas, você vai descobrir os ensinamentos de Jesus e aprender valores como bondade e compaixão. Editora: Ciranda Cultural Edição: 1, 2024 Autor: Ciranda Cultural Idioma: Português Páginas: 128 Dimensões: L 13.50 x A 20.00 x E 0.74 Faixa Etária: + 6 anos Encadernação: Brochura Box com 6 Minilivros 3 Palavrinhas Deus é amor: Sarah, Davi e Miguel sabem que Deus é amor, bondade, perdão e muito mais. Leia os minilivros para descobrir os diversos dons dados pelo senhor e espalhe-os por onde você for! Editora: Ciranda Cultural Edição: 1, 2021 Autor: Paloma Blanca Alves Barbieri Idioma: Português Páginas: 60 Dimensões: L 17.30 x A 23.10 x E 3.54 Faixa Etária: 0-3 anos Encadernação: Capa dura Acabamento: Cartonado', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7ra2v-m4hqajwkmtm8f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22198135739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22336015156', 'Pés Como os da Corça nos Lugares Altos | Hannah Hunard', 'Pés como os da corça nos lugares altos é uma bela alegoria do constante jornadear dos filhos de Deus em busca dos lugares altos do amor, da alegria e da vitória, e o mais conhecido e amado dos livros de Hannah Hunard.14x21cm192 Páginas', 36.9, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvjl5vqq86g03b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22336015156', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092261711', 'Do Lar Ao Coração: Olhando para a decoração e ordem da casa a partir da Bíblia', 'É comum as mulheres experimentarem emoções conflitantes diante dos seus desafios no cuidado do lar. Por vezes, se sentem sufocadas nas intermináveis tarefas que a administração doméstica exige. Outras vezes, exasperam-se pela falta de reconhecimento do seu árduo trabalho. Diante de tudo isso, como encarar o grande desafio que a mulher tem dentro do lar? Há somente um caminho: através da sabedoria bíblica. No livro Do Lar Ao Coração: Olhando para a decoração e ordem da casa a partir da Bíblia, as autoras buscam unir o cuidado do lar àquilo que possui valor eterno. Elas procuram entender biblicamente que a ordem e a estética do lar podem ser vistas como excelentes oportunidades para uma vida cristã significativa. Assim, sem ignorar os detalhes e afazeres diários, destacam o que está muito acima deles: cuidar do lar pela real possibilidade de viver nele dias felizes e surpreendentes! 14x21cm 144 Páginas', 37.95, 36.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-ll2uq9aw1z7x2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22092261711', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898860110', 'Memórias de Sherlock Holmes | Arthur Conan Doyle', 'Sherlock Holmes é um detetive britânico enigmático e pedante do final do século XIX e início do século XX. Ele utiliza a metodologia científica e a lógica dedutiva para solucionar seus casos e conta com a ajuda de seu fiel amigo e parceiro dr. Watson. Memórias de Sherlock Holmes é o último livro em que o doutor Watson narra os misteriosos casos solucionados pelo famoso detetive. O livro conta com onze histórias envolventes e enigmáticas em que vemos Holmes e Watson em ação. 23x16 cm 288 Páginas', 19.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824g3-me2su9noe8shc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22898860110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18759996811', 'Compêndio De Teologia Cristã | Johannes Wollebius', 'O Compendium Theologiae Christianae de Johannes Wollebius foi um importante manual de dogmática na formação de líderes, poetas, filósofos, teólogos, pastores, etc. Este compêndio foi usado como livro-texto, entre os séculos XVII e XVIII, nas principais universidades protestantes da Europa e, também, nas universidades de Yale e Harvard. O Compendium contribuiu no desenvolvimento do protestantismo escolástico e da vigorosa teologia puritana, e revelou-se um excelente representante da ortodoxia e piedade reformada do início do século XVII. Esta obra descontrói a caricatura que se arrasta contra os teólogos do período do protestantismo escolástico. A má fama de uma teologia árida, marcada pela especulação e sem aplicabilidade para a vida cristã não descreve a dogmática de Wollebius. O Compendium revela exegese bíblica, um calvinismo experimental e a aplicabilidade da doutrina cristã. O autor entendia que o propósito da teologia é a nossa salvação e uma vida dedicada para a adoração e a glorificação de Deus. 16x23cm 400 Páginas', 66.9, 66.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22110-f6otmw811gjv68', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18759996811', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9272794040', 'Novo Testamento Interlinear Grego-Português, Vilson Scholz - Sbb', 'Essa obra serve de auxílio na pesquisa do texto original e na preparação de pregações e estudos bíblicos. A tradução interlinear do Novo Testamento Grego coloca uma palavra ou expressão em português debaixo de cada palavra ou expressão grega. Traz o texto original grego (The Greek New Testament, 4a edição, 1994) e a tradução literal em português, além de duas outras traduções em português: a Almeida Revista e Atualizada e a Nova Tradução na Linguagem de Hoje. -Recursos: *Texto grego: The Greek New Testament, 4a edição Tradução literal do grego, por Vilson Scholz *Textos bíblicos em português: Tradução de Almeida Revista e Atualizada; Nova Tradução na Linguagem de Hoje *Análise de verbos irregulares *Análise dos verbos mais frequentes Breve explicação sobre a língua grega no Novo Testamento', 169.9, 169.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/e6141f9c9aac59fde0f3029afc64801d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F9272794040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
