INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598059071', 'Copo Infantil Antivazamento De Transição Com Alça E Tampa 330ml Patrulha Canina Plasútil', 'Copo Infantil de Treinamento Patrulha Canina 330ml com Alça e Tampa Protetora - Plasútil Torne o aprendizado de beber sozinho mais seguro e divertido com o Copo Infantil de Treinamento Patrulha Canina da Plasútil. Com capacidade de 330ml, ele é ideal para acompanhar o dia a dia dos pequenos, proporcionando conforto e praticidade enquanto eles se encantam com os personagens favoritos do desenho. Destaques e Benefícios - Capacidade de 330ml: Tamanho perfeito para hidratar as crianças sem necessidade de constantes reabastecimentos, ideal para casa, passeios ou viagens. - Alças Laterais Ergonômicas: Facilita o manuseio por mãos pequenas, ajudando no desenvolvimento da coordenação motora e incentivando a autonomia. - Tampa Protetora: Garante a higiene do bico e previne vazamentos, perfeito para transportar na mochila ou bolsa. - Estampa Divertida: Decorado com os adoráveis personagens da Patrulha Canina, o copo estimula o uso pelas crianças, transformando a experiência em um momento alegre. - Material Resistente e Seguro: Fabricado em plástico atóxico e livre de BPA, é durável, leve e adequado para o uso diário. Especificações Técnicas - Capacidade: 330ml Material: Plástico de alta qualidade, livre de BPA - Design: Bico anatômico, tampa protetora e alças laterais - Tema: Patrulha Canina - Cores: Estampas vibrantes com os personagens favoritos das crianças Este copo é uma excelente escolha para auxiliar na transição dos pequenos para a independência, com toda a segurança e qualidade que a Plasútil oferece. Perfeito para pais que procuram praticidade e um toque de diversão no dia a dia! Loja do Primo Variedades.', 39.0, 39.0, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/br-11134201-820lq-mqy77zdmjitief', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F402450553%2F23598059071', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18097700671', 'Tampa Reservatório Radiador UNO 1991/2004 - 44277 - 23031', 'Tampa Reservatório Radiador UNO 1991/2004 MILLE - 1,0 BAR (TAMPA AMARELA) Além de fechar o reservatório de expansão, esta tampa também mantém a pressão do sistema, através de uma válvula que se abre, dando passagem ao excesso de pressão. O controle da pressão faz com que o líquido tenha uma circulação completa, atingindo todos os pontos do motor, tenha um ponto de ebulição mais elevado, impede a formação de vapor no interior do motor, permite a entrada de ar atmosférico quando a temperatura do líquido abaixa.', 25.87, 25.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd4x-luf6b4xrp4pla7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18097700671', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
