INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258310162', 'Protetor Solar PS-01 FPS99 Toque Seco e Antioleosidade 40ml', 'Protetor Solar PS-01 FPS99 Toque Seco e Antioleosidade 40ml O Protetor Solar Principia FPS 99 é perfeito para quem não abre mão de uma alta proteção aliada ao cuidado com a pele. Com 20% de filtros UV, defende contra os raios UVA e UVB, prevenindo o envelhecimento precoce e os danos causados pelo sol. Sua fórmula leve e com toque seco controla a oleosidade, sendo ideal para todos os tipos de pele. Enriquecido com 5% de niacinamida, ajuda a uniformizar o tom, hidratar e fortalecer a barreira cutânea. Seguro, eficaz e de rápida absorção, o Protetor Solar Principia é o aliado essencial em sua rotina de cuidados diários!', 77.97, 68.99, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-81zv6-mmqllfcmlh50ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58258310162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
