INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21298487530', 'Kit 2 Fronhas Travesseiro Cetim Percal 300 Fios 100% Algodão 50cmx70cm Toque Acetinado Viva Conforto', 'Kit 2 Fronhas Avulsas para Travesseiro Lisa com Abas Cetim 300 Fios 100% Algodão 50cm x 70cm As Fronhas Viva Conforto são confeccionadas em Percal 300 fios 100% algodão Toque Acetinado. Possui um toque macio, sendo uma excelente solução para vestir o travesseiro com conforto e praticidade. Seu tamanho padrão para travesseiros 50 x 70cm, são muito confortáveis e oferecem diferentes combinações, seja com peças neutras, coloridas ou estampadas, proporcionando um ambiente aconchegante e personalizado. Características: - Fronha com 3 abas de 4 cm e fechamento envelope. - Material: 100% Algodão Percal 300 fios - Antialérgico - Toque super macio - Dimensões: 50 x 70 cm *Imagens meramente ilustrativas.', 90.0, 69.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcvcbxavha2ac4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F297240324%2F21298487530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
