INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294384872', 'Filtro Óleo Mann BMW X1 sDrive 20i 2010-2015 (Motor N20B20A', 'Filtro de óleo do motor. Mais desempenho, menos consumo. Para satisfazer as elevadas exigências aplicadas nos motores modernos, as montadoras exigem os mais altos níveis de desempenho dos componentes utilizados. Os filtros são projetados para os modernos óleos de alto desempenho e podem resistir até mesmo aos mais exigentes desafios técnicos. E tem mais: como o local de aplicação de filtros do óleo variam de montadora para montadora, os filtros de óleo MANN-FILTER estão disponíveis em diversos modelos. Especificações Técnicas: - (A) Diâmetro total de 74,00mm; - (B) Diâmetro interno de 41,00mm; - (C) Diâmetro interno de 41,00mm; - (H) Altura de 79,00mm; - Número original (OEM): 11427640862, 11428683204, 11427953125. Aplicações: - BMW 125i (F20/F21) 2012-2016 (Motor N20B20A); - BMW 220i (F22/F23) 2015-2018 (Motor N20B20A); - BMW 320i (F30/F31/F34) 2013-2018 (Motor N20B20A, N20B20B); - BMW 328i (F34) 2012-2018 (Motor N20B20A); - BMW 420i (F32/F33/F36) 2014-2016 (N20B20A, N20B20B); - BMW 428i (F32/F33/F36) 2014-2016 (N20B20A, N20B20B); - BMW 528i (F10/F11) 2012-2016 (N20B20A); - BMW X1 sDrive 20i 2010-2015 (N20B20A).', 155.99, 117.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-22110-8vpuku1plnjv50', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23294384872', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
