INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11548400377', 'Kit 600 Hastes Flexíveis Cotonetes', 'Cotonetes é feito com algodão 100% puro e possui hastes plásticas flexíveis. Por isso oferece toda a suavidade, conforto e absorção para o cuidado da sua pele. Cotonetes é indicado para a higiene pessoal de toda a família. Pode ser usado para limpar delicadamente a parte externa da orelha (desde que não atinja o canal do ouvido), as dobrinhas do pescoço e pernas do bebê, além de ser recomendado para aplicar e remover maquiagem.', 66.99, 45.64, NULL, 'Health > Personal Care > Hand Sanitizers', 'https://cf.shopee.com.br/file/96fbd8d85b7fca96cd872004ec5cc933', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F11548400377', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
