INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798679427', 'Macacão de Bebê Amore Vira Pé Amiguinhas da Selva Com Zíper e Protetor 100% Algodão', '👶 Conforto e Qualidade: Macacão Vira Pé Amore! Seu bebê merece o máximo de carinho e conforto, e a Amore desenvolve roupas e conjuntos pensando exclusivamente no bem-estar dos bebês. Este macacão é sinônimo de maciez e aconchego. Ele garante que o dia do seu amor seja mais confortável, alegre e cheio de estilo, permitindo total liberdade para brincar e descansar. ✨ Detalhes Que Fazem a Diferença Priorizamos a segurança e a praticidade para facilitar a rotina dos papais e mamães: • TECIDO PREMIUM: 100% Algodão – Extremamente macio, ideal para a pele sensível do bebê. • VIRA PÉ INTELIGENTE: Protege os pezinhos do frio sem a necessidade de meias extras. • FECHAMENTO COM ZIPER: Garante trocas de fralda rápidas e descomplicadas, especialmente durante a noite. • PROTETOR DE ZIPER: Segurança extra para evitar o contato do metal com a pele delicada do bebê. • MODELAGEM EXCLUSIVA: Desenvolvida para vestir com conforto e estilo. Dica: Se o seu bebê estiver entre tamanhos ou for maior que a média, opte sempre pelo tamanho seguinte para garantir maior tempo de uso e conforto. 📦 Conteúdo da Embalagem 1 Macacão Amore Vira Pé com Zíper Atenção: A mercadoria é composta somente pelo produto listado acima.', 34.9, 32.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Bodysuits & Jumpsuits', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg2ja9gm5fk7b3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F435692544%2F23798679427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
