INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22191214817', 'Kit 2 Varal de Chão com Abas Retrátil Slim Preto Mor', 'Kit 2 Varal de Chão com Abas Retrátil Slim Preto Mor Para quem vive uma vida agitada e não pode deixar as roupas secando a céu aberto, ou para quem precisa de uma opção por conta da quantidade de roupas o Varal de Chão com Abas Slim ocupa pouco espaço, é prático para montar, desmontar e guardar. Com estrutura em tubo de aço e acabamento em pintura epóxi de alta qualidade o Varal de Chão com Abas oferece resistência e durabilidade e suas exclusivas peças plásticas coloridas são um diferencial que além de trazer maior charme, ajudam a proteger contra corrosão. Ideal para quem busca praticidade e qualidade em um mesmo produto, o Varal de Chão com Abas Slim otimiza seu espaço distribuindo seis varetas resistentes no centro e duas abas com quatro varetas cada com capacidade para até 11 metros de roupas ou 19 Kg distribuídos. Assim que recolher suas roupas você guarda o seu varal dobrado em qualquer lugar. Perfeito para manter a organização da sua casa! Descrição do produto Marca: Mor Material: Polipropileno Material da estrutura: Aço Altura: 89 cm Largura: 49 cm Comprimento: 1,44 m Peso: 2,82 kg Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 320.26, 199.63, NULL, 'Home & Living > Home Care Supplies > Clotheslines & Drying Racks', 'https://cf.shopee.com.br/file/sg-11134201-7qvem-lgo4e11iixu3c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F22191214817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
