INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798270826', 'Faqueiro Tramontina Búzios Em Aço Inox Com Detalhe 24 Peças', 'Conjunto de Talheres 24 Peças Inox Búzios Tramontina Encante amigos e familiares com o Faqueiro Tramontina Búzios em Aço Inox com Detalhe 24 Peças! Produzido totalmente em aço inox, o faqueiro é resistente e durável, proporcionando uma composição mais especial para sua mesa. As peças possuem acabamento de qualidade, agregando charme às refeições. As peças são fáceis de limpar e podem ser lavadas na máquina de lavar louças. - Talheres produzidos em aço inox que mantêm a beleza, higiene e durabilidade. - Lâminas das facas com maior durabilidade do fio devido ao tratamento térmico. - Garfos e colheres com maior resistência devido à espessura do aço e estampagem das lâminas. - Adequados para máquina de lavar louças. Kit composto por: - 06 Colher de Mesa. - 06 Colher de Chá. - 06 Faca para Churrasco. - 06 Garfo de Mesa. Certificação NSF - Produtos da Linha Búzios certificados pela National Sanitation Foundation (NSF), organização reconhecida em segurança alimentar e práticas de higiene.', 149.9, 81.1, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7rav5-mau2af5mj0b49f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1404215442%2F18798270826', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
