INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18803160547', 'Pote de Vidro Hermético Quadrado - 520 Ml Oikos', 'Esse é o pote hermético de vidro quadrado de 520ml da OIKOS. Por que eu sou o pote da sua vida? - ele pergunta e a gente responde: ele é feito de vidro borossilicato, um vidro bem resistente inclusive ao choque térmico. É por isso que ele pode ir do forno ao freezer, da mesa para a lava-louças. Ele é bem bacana no quesito conservação de alimentos, já que combina a força das 4 travas e com o anel de silicone que veda de verdade. Assim, dá para você levar ele para cima e para baixo com você - e sem vazar absolutamente nada!', 65.9, 44.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-8262i-mle9u1bl1pfmca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F18803160547', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17465192355', 'Pote De Vidro De Mantimentos 800ml C/ Tampa De Bambu Oikos', 'Esse é o pote de vidro hermético quadrado de 800ml para mantimentos com tampa de bambu da OIKOS. Seu formato quadrado ajuda a aproveitar melhor o espaço - ele encaixa direitinho no canto do armário. E não para por aí: sua tampa de bambu é empilhável, o que ajuda mais um pouquinho a aproveitar o espaço disponível em casa. E não julgue pelas aparências, ele não é só um potinho bonito: com a combinação da vedação de silicone e o bambu antibactericida, esse pote se torna um verdadeiro mestre na conservação de alimentos! E não é só de comida que vive esse pote: algodão, fios, peças de jogos, pisca-piscas, flores secas e o que mais você quiser guardar - isso que é versatilidade.', 51.9, 42.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/f803f5d41995e26fe91697c304e0abe7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F17465192355', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
