INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19778249723', 'Kit 2 Cestos Organizadores Multiuso Decorativo Natural Seagrass - Oikos', '"Conheça o Kit de 2 cestos quadrados de seagrass 32cm da Oikos. Práticos, versáteis e decorativos, são perfeitos para organizar toalhas, roupas, brinquedos, livros, jogos, pastas, produtos de limpeza e até como cachepot para acomodar suas plantinhas e o que quiser. São de seagrass. Para limpar, basta utilizar um pano limpo e seco. Para uma limpeza mais pesada, pode ser lavada manualmente em água corrente e detergente neutro. Deixe secar completamente em local arejado. Leve funcionalidade e modernidade para sua casa! O kit contém: 2 Cestos organizadores de seagrass 32cm"', 256.9, 153.9, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mlfqczmiae4g27', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F752849300%2F19778249723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22692810874', 'Chave Combinada Com Catraca-M 14mm (408,0053) - Noll', 'A Chave Combinada com Catraca 14mm (408,0053) - NOll é indicada,para uso profissional e residencial, com sistema de catraca que facilita e agiliza apertos e desapertos de porcas e parafusos. Um dos lados da chave possui uma catraca com as mesmas medidas que permite a execução de trabalhos com menor esforço do que os modelos de chaves simples, pois dispensa a retirada da chave para novo movimento de apertar e soltar. • Produzida em aço cromo vanádio • Acabamento cromado e polido • Logotipo e medidas estampadas em baixo relevo facilitando a identificação da ferramenta. Especificações Técnicas: Referência: 408,0053 Marca: Noll A Chave Combinada com Catraca 14mm(408,0053) - NOll é indicada,para uso profissional e residencial, com sistema de catraca que facilita e agiliza apertos e desapertos de porcas e parafusos. Um dos lados da chave possui uma catraca com as mesmas medidas que permite a execução de trabalhos com menor esforço do que os modelos de chaves simples, pois dispensa a retirada da chave para novo movimento de apertar e soltar.', 39.86, 39.86, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rcc6-lquw9g4g304g2b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22692810874', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
