INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19921090552', '5 Oleo Motor Lubrax Tecno 10w30 Semissintético', '5 Oleo Motor Lubrax Tecno 10w30 Semissintético Óleo lubrificante multiviscoso semissintético para uso nos modernos motores a gasolina, etanol, flex e GNV (injeção eletrônica, multiválvulas e turboalimentados). Atende ao nível de desempenho API SN e está disponível nos graus de viscosidade SAE 10W-30. Aplicações: Lubrax Tecno é recomendado para uso nos modernos motores a gasolina, etanol, flex e GNV de veículos nacionais ou importados com injeção eletrônica, multiválvulas e turboalimentados, sendo compatível com conversores catalíticos. Recomendações: Especialmente recomendado para uso profissional em veículos com USO INTENSO urbano como carros de aplicativos, taxis e veículos comerciais. Características e Benefícios: - Possui duas vezes mais proteção contra ao desgaste das peças do motor, de acordo com os resultados de teste de Proteção ao Desgate da API Seq IVA; - Excepcional proteção contra a oxidação garantindo até 68% menor espessamento do óleo resultando numa maior lubrificação em todas as partes do motor, de acordo com os resultados de teste de Proteção a Oxidação da API Seq IIIG STM; - Proporciona até 14% mais limpeza do motor e controle na formação de borras e depósitos, mesmo a altas temperaturas, de acordo com os resultados de teste Controle de Borra da API Seq VG; - Excelente desempenho em qualquer temperatura e permite partidas rápidas, mesmo a baixas temperaturas.', 239.9, 239.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/23b424d4a02bbd09e0bd4741222f3fe3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F295637446%2F19921090552', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
