INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793820461', 'Protetor Solar Sundown Praia e Piscina FPS70 200ml', 'O Protetor solar Sundown Praia e Piscina FPS70; com tripla proteção, ajuda a proteger a pele de elementos agressores como o sol, cloro e a água salgada do mar. Oferece proteção imediata uva + uvb, protegendo a pele de queimaduras solares dentro e fora dágua. É resistente à água e ao suor e seguro para uso em toda família. Proteção completa para curtir a vida ao ar livre; uva + uvb balanceado; hidratação prolongada. Fotoestável: mesma proteção durante todo o tempo de exposição ao sol; dermatologicamente testado; previne o envelhecimento precoce.', 176.15, 176.15, NULL, 'Beauty > Skincare > Face Sunscreen', 'https://cf.shopee.com.br/file/sg-11134201-7rd44-m76u8x4g398pde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F22793820461', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
