INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18296871412', 'Cachimbo NGK Twister / Tornado / CB 300 / XRE 300 / XLX 250 / 350 (SD05FMGC)', 'Os cachimbo de velas têm a função de conduzir a corrente elétrica do transformador até a vela de ignição. Sua excelente vedação impede a entrada de umidade entre a vela e o terminal, evitando, desta forma, as falhas de ignição comuns nos dias de chuva.- Ótima isolação elétrica.,- Resistência a altas temperaturas.,- Ótima supressão de interferência.,- Boa vedação a umidade.- Garantia 3 meses defeito fabricação- Foto Ilustrativa', 51.11, 51.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7qvfv-lfxl3ih5bdtv25', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F18296871412', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
