INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203779427', 'Brinquedo Fisher-Price Novo Telefone Feliz para Bebês', 'Características do Produto: Marca: Fisher-Price Faixa Etária: A partir de 1 ano Cor: Colorido Ean: 887961321746 Características Adicionais: A cordinha conectada ao fone garante que ele nunca se perca As cores coloridas, os movimentos e sons ajudam a estimular os sentidos do bebê O discador ensina o bebê a contar e mostra os números de 1 a 9 e ajuda a exercitar as habilidades motoras finas As habilidades motoras grossas do bebê são exercitadas com os movimentos de levantar e tirar o telefone do gancho O brinquedo estimula a brincadeira de faz de conta precoce o bebê vai ter diversos e excelentes benefícios de desenvolvimento também Este clássico brinquedo agora conta com um desenho mais moderno, mas continua divertido e encantador como sempre com seu rostinho adorável, disco que gira, sons de telefone tocando e olhinhos que se mexem para cima e para baixo quando o bebê brinca com ele Fornecedor: Mattel do Brasil Ltda', 104.6, 89.9, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mpia6vmc9q186e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F58203779427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
