INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999069181', 'Jogo Aventura dos Pets', 'Os pets saíram para passear, mas são tantas distrações durante o passeio que eles não conseguem chegar ao destino! Gatos, ossos, comida... vários itens impedem que eles avancem no tabuleiro. Neste jogo de estratégia simples, você tem que cruzar o tabuleiro com seus peões representados por cachorrinhos de diferentes raças; temos 4 labradores ou 4 dálmatas ou 4 bulldogues francesses ou 4 vira-latas, todos muito fofos e alegres! Mas, a cada chegada , o dado é lançado e um dos elementos das casas do tabuleiro fica proibido, travando a passagem. O que fazer? Desviar ou mexer com outro peão? É exatamente essas pequenas decisões que farão você chegar à vitória e deixar seus pets sempre felizes! Contém:1 tabuleiro, 1 dado, 16 peões cartonados , 16 bases para os peões, 6 etiquetas para o dado e 1 regra A partir de 4 anos 2 a 4 jogadores Tempo estimado de jogo: 20 minutos', 69.99, 34.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rbkp-lo2y8cotc5gmf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F545750185%2F21999069181', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398477975', 'Lixa 3M D''agua 331Q 360 Embalagem com 50 Unidades', 'Características do Produto: Marca: 3M do Brasil Modelo: 331Q Forma do produto: Folha Dimensões: 22,5 x 27,5 cm Quantidade: Pacote com 50 folhas Tipo de Mineral: Óxido de Alumínio Grão: 360 Especificações Gerais: Fabricada com mineral óxido de alumínio para alta durabilidade e excelente acabamento Tratamento de impermeabilização no papel do costado Alta flexibilidade para melhor manuseio Costado resistente a quebras e descascamento Adesivo: Resina sobre Resina Alto poder de corte e durabilidade Excelente acabamento Uso a seco ou com água Costado: P80 a P220: Papel peso C à prova d''água – 331Q (Grãos grossos - Para desbaste inicial e remoção de material) P240 a P320: Papel peso C à prova d''água – 331Q (Grãos médios - Para preparação de superfícies antes do acabamento) P360 a P600: Papel peso C à prova d''água – 331Q (Grãos finos - Para acabamento e polimento final) Usos do Produto / Aplicações: Aplicações: Lixamento, Lixamento de Primers, Lixar Enchimento, Moldagem de Enchimento Para madeira, metal, gesso, massas corridas, tintas, primer e massas Indicada para lixamento manual a úmido ou a seco em reparação automotiva Instruções de Uso: Corte a folha conforme a dimensão do bloco lixador ou necessidade manual. Utilize sempre água limpa na lubrificação durante o lixamento. Evite diferenças superiores a 100 pontos entre duas etapas consecutivas para maior rendimento. Para desbaste, utilize movimentos orientados; para acabamento, movimentos circulares. Cuidados: Sempre utilize água limpa na lubrificação. Não mergulhe ou armazene lixas em baldes antes ou após o uso. Evite acumular lixas usadas no balde para prevenir contaminação de grãos. Armazenamento e Manuseio: Validade de 60 meses se armazenado na embalagem original, em ambiente seco, afastado de pisos, janelas e locais úmedos. Dimensões Dimensões do Produto (CxL): 27,5 x 22,5 cm Fornecedor: 3M do Brasil', 83.07, 83.07, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-824jc-mpiajpd72sjkca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23398477975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097385836', 'Pillow Top Queen Extra Macio Toque de Pluma em Fibra Siliconada 600g/m2 158x198cm BF Colchões', 'Transforme suas noites de sono com o pillow top super macio da BF Colchões. Uma camada extra de conforto que é utilizada entre o colchão e o lençol que, além de deixar sua hora do sono mais aconchegante, irá proteger seu colchão. Com enchimento de 600g/m2 de fibras siliconadas e tecido micro percal 200 fios, possui acabamento matelado com toque ultra macio, aumentando o seu conforto na hora de dormir. O tecido lateral é respirável e garante maior frescor e higiene. Chacoalhe antes de usar para maior maciez. Tenha uma cama de hotel em casa com o pillow top macio de fibras da BF Colchões. Características Marca: BF Colchões Tamanho: Queen Conforto: Super Macio Enchimento: 600g/m2 de Fibras de poliéster siliconadas Revestimento: 100 Poliéster Micro Percal 200 Fios Tecido lateral respirável Alta qualidade e durabilidade Lavável Medidas: 158x198cm (largura x comprimento)', 304.2, 209.0, NULL, 'Home & Living > Bedding > Mattress Protectors & Toppers', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e4zawmpq3k91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F22097385836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594746296', 'Kit 3 Truly Wanpy Petisco Sopa para Gatos Sabor Frango, Abóbora e Cenoura 50g', 'PRODUTO ORIGINAL COM NOTA FISCAL! - - - - - APRESENTAÇÃO: COMBO 3 x G Wanpy Sopa Frango Abobora Cenoura 50G - - - - - - - - - - DESCRIÇÃO: Muito mais do que um petisco, um momento de conexão entre você o seu pet! A linha de Sopinha para Gatos da Wanpy oferece uma opção prática, nutritiva e saborosa, auxiliando na ingestão hídrica do felino. Sabor Frango, Abóbora e Cenoura , sem corantes ou conservantes artificiais, são feitos com os caldos de suas proteínas. Pode ser misturado com a ração seca e outros petiscos também, uma alternativa saborosa e funcional! - - - - - MODO DE USO: Ofereça a recomendação diária descrita na embalagem ou sempre que necessário para agrado do seu pet! Tal petisco não substitui o alimento comleto :) . - - - - - - - - - - Enviamos o seu pedido o quanto antes possível! Agradecemos a preferência.', 69.0, 35.53, NULL, 'Pets > Pet Food > Cat Treats', 'https://cf.shopee.com.br/file/br-11134207-81z1k-min648dqnncy38', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442964228%2F23594746296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
