INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23038107681', 'Jogo De Chaves Combinadas De 6mm a 32mm Com 12 Peças Vonder', 'Jogo De Chaves Combinadas Com 12 Peças Vonder Este jogo de chaves combinadas é perfeito para aperto e soltura de porcas e parafusos sextavados. Com 12 peças de diferentes tamanhos, é ideal para uso industrial, oferecendo resistência e durabilidade. Características do Produto: > Versatilidade de Uso: Cada chave combina dois tipos de extremidade (fixa e estrela), o que facilita o trabalho em locais de difícil acesso. > Durabilidade Superior: Fabricadas em aço cromo vanádio, as chaves possuem alta resistência e longa vida útil. > Acabamento Cromado Fosco: O acabamento resistente à oxidação e corrosão garante uma vida útil ainda mais longa para as ferramentas. Composição do Jogo (12 Peças): Tamanhos Disponíveis: 6 mm, 7 mm, 8 mm, 10 mm, 11 mm, 13 mm, 14 mm, 17 mm, 19 mm, 22 mm, 27 mm e 32 mm. Cuidados no Uso: Nunca utilize prolongadores sobre as chaves para evitar aumento do torque e desgaste prematuro das ferramentas. Especificações Técnicas: * Norma: DIN 3113. * Peso Aproximado: 1,6 kg. * Garantia Legal: 90 dias. * Material: Aço cromo vanádio de alta resistência. * Acabamento: Cromado fosco para maior durabilidade e resistência à corrosão. Ideal para quem exige qualidade e precisão no uso diário de ferramentas em ambientes industriais e profissionais.', 320.0, 189.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrn6btvdvhn110', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F942805673%2F23038107681', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
