INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23796908996', 'Alavanca Freio Mão Fiat Palio 1997 a 2008 - 132266 - SH5018XX', 'Alavanca Freio Mão Fiat Palio 1997 a 2008 132266 SH5018XX (Weekend) - 1.0/1.3/1.4/1.6/1.8 8/16vGeralmente acionado por uma alavanca, o freio de mão é formado por um cabo de aço que ao ser "puxado" pressiona as lonas do freio traseiro contra as rodas, mantendo-as travadas. Ele só deve ser acionado com o veículo parado ou pode danificar os pneus e seu próprio sistema.', 349.42, 349.42, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rd4t-m7s4ckowpnb1e4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23796908996', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
