INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793658831', 'Deo Colônia Masculino Tedd 15ml - Amakha Paris', 'Manifeste toda a irreverência e presença marcante com a Deo Colônia Masculina Tedd Amakha Paris. Desenvolvida para o homem que vive intensamente e define suas próprias regras, esta fragrância é um convite à liberdade e autoconfiança. Sua composição olfativa única garante um rastro sedutor e inesquecível em qualquer ocasião, tornando-o perfeito para o dia a dia ou momentos especiais. A Deo Colônia Masculina Tedd Amakha Paris 15ml oferece uma fragrância amadeirada especiada, ideal para homens que desejam expressar sua personalidade independente e irreverente com um aroma marcante e portátil. ✅ Referência olfativa: Azzaro Wanted. ✅ Família olfativa: Amadeirado Especificado. ✅ Notas: • Topo: Limão, Gengibre, Lavanda e Hortelã. • Corpo: Maçã, Junípero ou zimbro, Cardamomo da Guatemala e Gerânio. • Fundo: Fava Tonka, Madeira de Âmbar e Vetiver do Haiti. Indicações: ✔️ Ocasião: Dia e Noite. ✔️ Estação: Verão / Outono. ✔️ Momento: Social. ✔️ Perfil: Detalhista. Modo de Uso: Aplique o perfume nos pontos de pulsação (pescoço, pulsos, atrás das orelhas). Borrife a cerca de 15–20 cm da pele e evite esfregar os pulsos após a aplicação. Para maior fixação, aplique sobre a pele limpa e hidratada.', 50.0, 32.5, NULL, 'Beauty > Perfumes & Fragrances', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhkisjmi90chd2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1454161052%2F22793658831', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699097296', 'Jogo De Cabos De Vela Tucson I30 Sportage 2.0 16v Gasolina', 'Este anuncio contem os seguintes produtos: 1 Jogo de cabos de velas. Fabricante do jogo de cabo de velas: Magneti Marelli Produtos novos, originais, com 90 dias de garantia total. Este produto se aplica a esses veiculos: - HYUNDAI - I30 2.0 16v (145cv - G4GC) - (Gasolina / Gnv) - Desde 01/2008 - Tucson 2.0 16v - FLEX (142cv. gasolina / 145cv. etanol / Betta) - (Gasolina / Gnv) - desde 2013 -Tucson 2.0 Gasolina desde 2004 - KIA - Sportage 2.0 16v CVVT (142cv) - (Gasolina / Gnv) - desde 08/2004 - CABO DE IGNICAO: - Marca: MAGNETI MARELLI - Tipo: Supressivo - Codigo: CVMH1102 - Referencia Ngk: SC-N08 - Embalagem: 1 Jogo. ANTES DE EFETUAR A COMPRA POR FAVOR TIRAR SUAS DUVIDAS NO CAMPO DE PERGUNTAS EQUIPE KADUCAR', 197.76, 197.76, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbn5-lpiahvpv61zb1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339675952%2F19699097296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
