INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22194928561', 'FIO DENTAL KESS 100M ENCERADO SABOR MENTA', 'O fio dental Kess remove a placa bacteriana e os resíduos de alimentos das áreas onde a escova dental não consegue acessar. Possui fio encerado mais fino que desliza melhor entre os dentes e evita que o fio desfie.', 12.74, 12.74, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-825zn-mm7jhnacu1oi48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F22194928561', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209342644', 'Clareador E Hidratante Capilar Sun In Phytoervas 120ml', 'Sun In da Phytoervas é um clareador capilar e hidratante capilar, que proporciona reflexos de luz e clareamento dos fios. A intensidade do clareamento é gradativa e varia de acordo com a tonalidade natural dos cabelos. O Sun In tem ação condicionadora, é enriquecido com extrato de camomila e óleo de Macadâmia que ajuda a proteger os fios enquanto clareia. Sua nova fórmula é mais potente e de fácil aplicação com spray.', 20.42, 20.42, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-820n4-mnd66afych6q08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F58209342644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
